/* 平成26年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h26.committeeSessions.push(...[{"id":"h26-20140303-3","meetingId":"h26-c-budget","date":"2014年3月3日","dateIso":"2014-03-03","committee":"予算特別委員会","time":"午前１０時００分～午後６時１１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を176件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"塚本副委員長","kind":"質問・要望","question":"会派におかれましては、一人当たりの質問時間は、答弁時間も含めて、１０分、１５分、２０分のいずれかとし、会派で割り振ることとしております。なお、無所属の委員の質問時間は、答弁時間も含めて、１日につき１０分となります。終了時間のお知らせにつきましては、残り時間がなくなった時点で、振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-001"},{"speaker":"本多委員","kind":"質問","question":"次の質問に行きます。７９ページの被災者雇用助成なんですけれども、６７５万円の更正減額なんですが、平成２３年度では６人、１３５万円の助成、平成２４年度は２８人で８７０万円余ということで、今回は平成２５年度で、補正で減額になっているんですが、その内訳というか、背景をお知らせください。","respondent":"山崎ものづくり・経営支援課長","answer":"雇用者１人に国が９０万円、区がその２分の１の４５万円を上乗せ補助しまして、１人当たりの雇用で１３５万円の補助です。こちらの制度につきましては、被災者雇用の当初１年間に限って補助の対象ですので、平成２３年度で６名、平成２４年度で２８名、今年度は８名です。","voiceIndex":13,"id":"exchange-002"},{"speaker":"本多委員","kind":"質問","question":"これは被災地に戻られるというケースも多々あるのでしょうか。その辺がわかれば教えてください。","respondent":"山崎ものづくり・経営支援課長","answer":"どちらかといいますと、現地に事業所を持って現地で雇用しているパターンのほうが８割というようなことです。","voiceIndex":15,"id":"exchange-003"},{"speaker":"本多委員","kind":"意見","question":"それで、その辺の着眼点と、あと、オリンピック・パラリンピックに向けての都市における色彩計画についてとか、これは国が指定する色とかを使うケースが多いと思うんですが、区独自でそういう色彩計画を特段できるのかどうか、その辺についてお聞かせください。","respondent":"稲田道路課長、柏原オリンピック・パラリンピック調整担当課長","answer":"例えば、海抜表示板等は設置しましたけれども、なるだけユニバーサルデザインに沿いながらということで、白地に紺の青というところでやってきた経緯がありますが、今後もそういうまちなかに補完するような看板におきましては。色彩の部分ですけれども、例えばカラーの部分につきましても、これにつきましては、東京都も含めて、全体として、デザインであるとか、サインの部分であるとか、そういったところの検討会も立ち上がってくると聞いてありますので。","voiceIndex":19,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"いろいろオリンピック・パラリンピックに向けては着眼するところがたくさんあると思いますので、そういう色彩計画、色づくりについても都と連携して考えていっていただきたいと思います。それと、標識とか看板についてなんですけれども、雪についての積載量の想定を超える場合の対応につきまして、どのようなお考えか、どういうふうに対応していくのかお知らせください。","respondent":"稲田道路課長","answer":"これらは、そのような自重、それから死荷重というんですけれども、上に乗るような荷重、例えば雪とか、そういうものを含めまして計算の中に入れておりまして、ちゃんとそのような計算の中になったというものです。","voiceIndex":22,"id":"exchange-005"},{"speaker":"本多委員","kind":"質問","question":"おおかたは、多分国のほうの基準でやられていると思うので、相当重量がかかっても対応できると思うんですが、もうちょっと簡易的な標識とか、区道、都道、国道、全般的において簡易的な標識とかについては、同じように対応が大丈夫というか、その点はいかがなんでしょうか。","respondent":"稲田道路課長","answer":"単独で立っている小さな街角にあるような標識、これにおきましても一定の基準がございまして、それに従いながらやっておりますので、風荷重というようなものにも対応しておりまして、基準的に大丈夫であります。","voiceIndex":24,"id":"exchange-006"},{"speaker":"本多委員","kind":"質問","question":"次の質問に行きます。補正予算での歳入に関連して、競馬組合事業や宝くじなどと同様に、こういう公営的なもの同様に、カジノを公営カジノでの事業とした場合、区内に誘致をすべきだと思います。","respondent":"柏原行財政改革担当課長、本城企画財政課長","answer":"東京都等の動きもあると思いますので、そういったところを注視しながらということになってこようかと思います。予算面の対応につきましては、以上のようなことを踏まえまして、財政的な観点から申しますと、補正予算等につきましては、今後、事業のかかる実際の財政規模等を含めて、補正予算による対応が必要かどうか。","voiceIndex":26,"id":"exchange-007"},{"speaker":"本多委員","kind":"質問・要望","question":"誘致については、都の動き、国の動きの注視はわかるんですが、さらに一歩区が先に乗り出していただきたいと思います。それをもう１点と、あと、補正の歳入でそういう可能性というのでしょうか、それがあるのかということを教えてください。","respondent":"桑村企画部長","answer":"カジノのほうですけれども、これは今、法案審議中ということで、まず国の議論を受けるということが一つです。それから、これは法案を通ってから実際の実施法というのが、これは１年以内につくることになります。","voiceIndex":29,"id":"exchange-008"},{"speaker":"本多委員","kind":"質問・要望","question":"１分ありますので、本会議での「公営カジノは犯罪だ」という言葉がありましたが、それを打ち消していただきたいと思います。","respondent":"桑村企画部長","answer":"いわゆる財政的なものですとか、そういったものに寄与するということで提案されているわけですので、当然プラスの面があると理解しております。ただ、その意味では、いろいろな議論があるということを考えながら私どもとしては判断させていただきたいというものです。","voiceIndex":31,"id":"exchange-009"},{"speaker":"南委員","kind":"意見","question":"法律で今、禁止されているわけでありますけれども、見直しはするということにはなっているようですが、なぜ禁止されているのか、まずそこを聞きたいと思います。","respondent":"桑村企画部長","answer":"カジノ法案が通れば、当然それとは違いますので、いわゆる競馬をやるというようなことは禁止されてございません。その意味では、賭博罪が成立するかどうかというのは、今のカジノの法案とはちょっと違う次元の話だろうと思ってあります。","voiceIndex":34,"id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"どこがどういうふうに違うのかが、もう１回説明をしていただきたいと思うんですけれども、賭博行為が禁止されている、カジノは賭博じゃないんですか。お金を賭けて、そしてやるわけですよね。ですから、それはもう紛れもない賭博じゃないでしょうか。どこがどう違うか教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-011"},{"speaker":"南委員","kind":"質問","question":"議論はこれからされていくということなんですが、今現在ある法律、そこで賭博行為を禁止している、その趣旨は何ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"ですから、賭博行為は禁止だというふうに法律でなっていると私は理解しています。品川には大井競馬場があります。いないですか。委員の皆さん、そういう相談受けたことないですか。私はあります。したがって、そういう賭博行為というのはやめるべきだ、法律で禁止するのは当たり前だと思っています。そういう見解について、もう一度、最後お尋ねして終わりたいと思います。","respondent":"桑村企画部長","answer":"競馬についても競馬法に基づいてやられているわけです。その意味では、一定のルールに基づいてそういう行為が許されるというのは、これは社会的な合意がなされるわけでございましょうから、その意味でのいわゆる議論の結果を待ちたいというのが私どもの見解です。","voiceIndex":42,"id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"どうやら質問している趣旨をわかっていただけていないのかわかりませんけれども、私はお金を賭けて、いわゆるそういうお金を賭ける行為を賭博というふうに言うと思うんですけれども、そういうことが今の法律では禁止されているわけです。その禁止されている意味は何かということを聞いているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":44,"id":"exchange-014"},{"speaker":"南委員","kind":"意見","question":"私は、法律で禁止されている、されていないの、そういう線引きではなくて、やっぱりお金を賭けて、そしてゲームをやると、そういう行為そのものは、やっぱり人生を狂わせる、その人の家庭をめちゃめちゃにさせる実例がいっぱいある、そういうことに基づいてやめるべきだと、そういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":47,"id":"exchange-015"},{"speaker":"つる委員","kind":"質問・要望","question":"そのルーツをちょっと調べたら、上巳の節句ということで、昔から季節や物事の節目には災いをもたらすということで邪気が入るということで、そうした行事が季節の邪気払いの行事として、老若男女を問わず、皆の幸福を願っていく、そういうような行事として位置づけられていたそうでありますので、私、個人的には、これを祝日にまたしてほしいなという思いがありながらなんですけれども。","respondent":"黒田長期計画担当課長","answer":"平成２４年の合計特殊出生率は、品川区では１.０９です。","voiceIndex":49,"id":"exchange-016"},{"speaker":"つる委員","kind":"確認","question":"品川区の公式見解として１.０９ということで確認します。ある経済誌によると、平成２４年、品川区は１.１１というふうに出ていたんですが、この辺は誤差なのかどうかあれなんですが、いずれにしましても、２３区で１４位、東京都全体で見ると、６２区市町村中で４８位という位置づけで、数字で見る限りは、国とか東京都の平均よりも低いというふうに出ています。","respondent":"福島青少年育成課長","answer":"私からは、少子化と次世代育成についてお答えさせていただきたいと思います。品川区では、次世代のための後期計画を立てまして、その計画が着実に進むよう、次世代推進協議会のほうで検討を行っているです。そちらの協議会につきましては、年２回やっているところです。","voiceIndex":51,"id":"exchange-017"},{"speaker":"つる委員","kind":"質問・要望","question":"時間のほうは余裕がありますので、もう少し詳しく教えていただければと思いましたが、次の質問と絡めて、もしお答えできるところがあれば教えていただきたいんですが、国の平成２５年度の補正予算の中で、１０分の１０でありますけれども、地域少子化対策強化交付金、これが３０.１億円が計上されて盛り込まれたと思います。市町村は８００万円とありました。","respondent":"福島青少年育成課長","answer":"先ほど説明いたしました次世代育成支援対策推進法に基づきまして、品川区としましても、品川区次世代育成支援対策推進行動計画の後期計画を立てているところです。こちらにつきましては、平成２２年から平成２６年の計画です。","voiceIndex":53,"id":"exchange-018"},{"speaker":"つる委員","kind":"提案","question":"国のお金を使えなかったという部分があると思いますけれども、品川区の独自の施策として、さまざまな案も、その計画も、着実な実行も含めてそうなんですが、やっていただきたいという期待も含めまして、公明党の会派からも産後ケアセンターの設置の提案だとか、また、私も昨年の決算特別委員会では、産後ドゥーラの活用の検討とかをしてみたらどうでしょうか、このような提案をさせていただきましたが。","respondent":"亀井品川保健センター所長","answer":"産後ケアセンターは、確かに国が来年度、モデル事業みたいな形で考えているということは聞いておりますけれども、その辺の国のモデル事業、そんなに大規模なものになるかどうかわかりませんけれども、その動向とか、そういう産後ケアセンターが、サンプルとしては、今。","voiceIndex":55,"id":"exchange-019"},{"speaker":"つる委員","kind":"提案","question":"私もこの間、産前産後ケア推進協会というところのセミナーに参加して、実際そういった現場に携わっている方々のいろいろな提案もお聞きする中で、いい案だなとか、自治体もしっかりと絡んで推進していけば、大きい意味では社会保障の安定性にもつながっていくなというようなこともさまざま学ぶ部分もありますので、また追っていろいろと議会として提案をしていきたいと考えますが、文京区では。","respondent":"福島臨時給付金担当課長","answer":"こちらの補正予算につきましては、全てシステム開発費です。といいますのも、今、さまざまなシステムが必要になりますので、それをまず改修し、的確な支給を図っていきたいということで、まずは今年度補正につきましては、システム開発費について出したところです。","voiceIndex":57,"id":"exchange-020"},{"speaker":"つる委員","kind":"質問・要望","question":"総務委員会でもいろいろと各委員のほうからも質疑させていただきましたので、かぶらない観点で質問させていただきたいんですが、厚労省のほうでも既に注意喚起というところで、いわゆる振り込め詐欺の注意喚起のビラとかが出ておりますが、品川区でも生活安全担当が中心となって、恐らく啓発等も日常的に今までもされていたひとつであると思いますが、この辺の、それに特化したという。","respondent":"福島臨時給付金担当課長","answer":"こちらは特化して行うということではないんですけれども、今後、支給につきましては６月ぐらいからを考えているんですが、その前にさまざまなＰＲが必要というふうに考えております。","voiceIndex":59,"id":"exchange-021"},{"speaker":"つる委員","kind":"質問","question":"６月支給を目指してということで、趣旨を含めて本当に早めの対応がありがたく思われるところでありますが、またさらに支給に際しては、特に子育て世帯のほうになるかもしれませんが、いわゆるＤＶ被害の方への対応ということで、事前申出期間が２月１０日から２月２８日にあったかと思いますが、品川区はそうした対応があったかどうか、この辺の概略を教えてください。","respondent":"福島臨時給付金担当課長","answer":"こちら、ＤＶ関係の申し出ですけれども、関係各課等集まりまして検討しましたけれども、現在のところ０件でございました。","voiceIndex":61,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問・要望","question":"０件がいいとか悪いとかという判断は多分ないと思うんですが、間違いなく本当に必要とされている方にしっかりと給付金が支給される万全の体制をとっていただきたいと思います。年間を通じての１万円というそういった概算の数字だと思いますけれども、早めに支給されることが、支給対象の方をはじめ望まれるところだと思いますので、ぜひ万全な体制で臨んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"向委員","kind":"質問","question":"私からは、まず４８ページ、４９ページ、妊婦健康診査、続けて、７２ページ、７３ページ、予防接種、７４ページ、７５ページ、不妊治療助成事業追加分、時間があれば４０、４１ページにいきたいのですが、簡単にざっとお伺いします。具体的に妊婦健診そのもの、それとも超音波、妊婦・産婦歯科健診と細かい項目があると思うんですけれども、どのあたりが実績増になったのか教えてください。","respondent":"江部健康課長","answer":"続けて、妊婦健診の検査数の増につきましては、個別に超音波が増えたとか、何が増えたというよりも、全体的な件数、妊婦の件数が増えており、１回目の健診の数、それから２回目以降の健診の数も同様の比率で増えてあります。","voiceIndex":65,"id":"exchange-024"},{"speaker":"向委員","kind":"質問","question":"このあたり、先ほど、円滑な接種が行われるようになったという答弁がありましたが、区の傾向というか、周知、お母さんとかお父さんが、お子さんの予防接種、どうかなと迷いながらされていると思うんですが、周知に１年、２年、今、区がどのくらい必要とお考えなのかをお尋ねしたいのと、そのあたり、ワクチン接種の勧奨、スムーズに円滑に進めるために、保健師が主体になって頑張っていらっしゃるとか。","respondent":"伊津野保健予防課長","answer":"定期予防接種の勧奨につきましては、原則として個別勧奨を行っております。保健所の新生児の訪問ですとか、健康診断につきましての保健師の活動も重要でありますが、かかりつけの医療機関での説明もかなり重要なことだと考えております。","voiceIndex":67,"id":"exchange-025"},{"speaker":"向委員","kind":"質問・要望","question":"そのあたりの勧奨については、区としてもいろいろ対策をとってくださって、ご丁寧に対応してくださっているのも存じております。引き続き、頑張っていただきたいと思います。続けて、不妊治療助成についてなんですけれども、７４ページ、７５ページのところ、金額を確認いたしますと、２００万円ほど追加になっている、これも実績増だと思います。","respondent":"江部健康課長","answer":"治療内容につきましては、私どもは一般不妊治療ということでございまして、内容的には特に変わったものではございませんで、ちょっと年齢の高齢化と、それから、健康な方たちを含めた全体的に件数増であるというふうに認識しております。","voiceIndex":71,"id":"exchange-026"},{"speaker":"向委員","kind":"質問","question":"私も３０過ぎて結婚しました。周りを見ても、３０を過ぎて結婚する同級生も本当に多いです。このあたりは、また改めて別の日にお尋ねしたいと思いますので、よろしくお願いします。その中で、満２７週以下、妊娠６カ月ぐらいだと思うんです。男子が６人、女子３人ということで、本区では、こういう２００グラム台とかで産まれる赤ちゃんというのは、今年度はどうだったのか、それをちょっと教えてほしい。","respondent":"江部健康課長","answer":"ちょっと今、資料を持ち合わせておりません。申しわけありません。","voiceIndex":73,"id":"exchange-027"},{"speaker":"向委員","kind":"質問","question":"わかりました。数字はまた改めてお尋ねするということで、未熟児の赤ちゃん、今後も産まれる可能性は、来年も再来年もずっとあるだろうなというのは、私が申し上げるまでもないですが、このあたりの主な原因ということについては、区としていろいろ、母体の疾患だったり、先ほど、出産年齢が高齢化になっているようなお話が出ましたけれども、そのあたり、簡単にお答えいただけますでしょうか。","respondent":"江部健康課長","answer":"先ほどの答弁漏れで数字がわかりましたが、１,０００グラム未満で、平成２４年度、総数１４名です。うち男子が８名ということで、２００グラムという数字はとっておりません。申しわけございません。","voiceIndex":75,"id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"特別区民税ですけれども、補正では５.９％の増になっていると思うんですけれども、利子割交付金、配当割交付金、株式の交付金が、今回、軒並み大幅に増になっていますよね。それと、利子割以下の交付金は、このアベノミクスの効果が出ているのでしょうか。それと、特別区民税においても、富裕層の影響は出ているのでしょうか。その３点についてお伺いします。","respondent":"高森税務課長、本城企画財政課長","answer":"平成２５年の予算の中身なんですけれども、平成２４年１０月の時点で予算の調整を行っておりまして、この時点では経済状況の緩やかな回復傾向があるというふうには見込んでおったものを、やはりまだ。その他の歳入の中の株式譲渡の関係の交付金等、それらにつきましては、直接的なものとしては、急激な株価上昇等によって、こういった交付金の増に続いているわけで、そういう意味では、この間の一連の国の経済政策等の効果の一因として。","voiceIndex":78,"id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"企画財政のほうでそういうふうに理解をしているというのはわかるんですけれども、その理解をした上で、政策的にどういうふうにこういう現実を見て、どういうふうにしていくかということをお答えいただきたいのと、それと、今日ちょっと席を見て、長期計画担当の方が、もう長計が終わったからかもしれないんですけれども、ぜひこういう区民税とか数字に出てくることにおいても、長計等においては。","respondent":"本城企画財政課長、黒田長期計画担当課長","answer":"それと、これからにつきましては、こういった経済的な状況の中で、これから４月以降、例えば消費増税に伴う駆け込み需要の反動とか、それら一連の波及効果も慎重に見極めながら。長期計画の中での財政の見通しですが、計画事業、今回は後期ですので、平成２６年度から平成３０年度までを見込む中では、ある程度、見通しを立てた財源投資を立てておりますが、いわゆる住民税は前年の所得にかかる税ということで。","voiceIndex":81,"id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"わかりました。次、財調についてお伺いしますが、３３０億円から３４０億円と１０億円の増ということですけれども、原資が固定資産税と法人住民税ですよね。これらの平成２５年度の要望はどうだったのかということと、それと、今後の見通しは、企画財政等でどういうふうに考えているかをお尋ねしたいのと、それとあと、長期計画の担当の方に、長計において財調というのはどのように組んだのか教えてください。","respondent":"本城企画財政課長、黒田長期計画担当課長","answer":"平成２５年度中の傾向がそのような形でございまして、平成２６年度の財調の全体的なフレームを見通すに当たりましても、その基調が基本的には続くということで、それを加えた伸びを含んでいるところです。長期計画の中では、いわゆる法人住民税につきましては、現行の制度に基づいて財源を見ているわけですが、国の税制改正の流れの中では、いわゆる東京都の財源として、いわゆる法人二税について。","voiceIndex":84,"id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"わかりました。次、基金についてお伺いしますが、毎回伺うんですけれども、繰り入れが１４億円の減ですよね。これに対して総務費での基金積立金の追加が２３億円ですよね。これは企画財政に答えていただきたいんですけれども、この件に関して、基金については長計の中でどういうふうに入ってきたのか、入ってきたというか、長期計画担当としてはどういうふうに基金についてはということもお尋ねします。","respondent":"本城企画財政課長、黒田長期計画担当課長","answer":"それとあと、今回につきましては、一方では、先ほどもご説明いたしましたが、お金の入ってくる面で、当初予算に比べて税が約２０億円、財調として１０億円、プラス３０億円が当初予算よりも多く見込まれているということと、あと。いわゆる長計の中の基金ですが、財政計画を立てる中で、施設の老朽化等も一定程度見込んでおりますので、そういった中である程度の基金の積み増しというのは、計画的にしています。","voiceIndex":87,"id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"財政がどうなるかというものすごく心配している一人なんですけれども、基金の積立とかは、たしか積み増しの理由の一つとして、基金の運用を国債でやっているというような記憶があるんですけれども、国家財政の現況と国債の運用の考え方について、何か矛盾はないのかなという思いがあるんですけれども、その辺についてはいかがでしょうか。","respondent":"本城企画財政課長","answer":"そういった面につきましても、基金の運用に当たっては、基本的には安全な運用ということが一般の原則でありますが、資産の中で、国家の財政力を基本的な担保として生かす国債が資産としては最も安心、確実だという。","voiceIndex":90,"id":"exchange-033"},{"speaker":"藤原委員","kind":"質問・要望","question":"地域振興基金ですけれども、財産収入の株式のところで、歳入のところで地域振興基金積立金と書いてあって、７０４万円で、総務費のところで８５４万円、積立金を追加しているんですが、総予算で６億１,２００万円積み立てる予定でしたから、この補正の積立の原資がどうなっているのかと、積立の考え方を教えていただきたいですが、この基金は、今までたしか１００万円単位だったと思うんですけれども、今回。","respondent":"本城企画財政課長","answer":"ケーブルテレビ自体、地域メディアとしての位置づけがあるところですので、そこの売却益を活用するに区財政の置きどころとしてどこがふさわしいかという観点から判断した中で、地域振興基金の元手とするのがいいということで充てて。","voiceIndex":92,"id":"exchange-034"},{"speaker":"藤原委員","kind":"質問","question":"平成２４年度、平成２３年度の補正を見ましたらありませんでした。私の質問の答弁だったんですけれども、でも、いきなりこれが出てきたので、今年度の状況をまず教えてください。そして、今年度補正をやらなければいけなかった理由についてお尋ねいたします。","respondent":"山崎ものづくり・経営支援課長","answer":"それがこの１月からそういう形に大分絞り込みがあったために、その資金に対する予算につきましては、予算の適正化の観点で、今回、補正予算に上げさせていただいたということでございまして、その他の資金については、減額をしておらずに。","voiceIndex":94,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問","question":"当初マイナスと見込んだものが最終補正でプラス２０億というのが私もあまり聞きなれないんですけれども、この見込みとの差どう見ているのか伺いたいと思います。先ほど、納税義務者数は３,７００名増えた、非課税の中で納税義務者数が上がったと、そういう答弁がありましたけれども、これが２０億円の主なものなのか、その様子を伺いたいと思います。","respondent":"高森税務課長","answer":"ちなみに、平成２５年度の納税義務者数ですけれども、集計はまだしておらないんですけれども、流動的でもありますけれども、当初の状況で見ますと、おおよそ２,５００人ほどが増加している状況です。","voiceIndex":97,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"この区民税の増等、住民の実感や実態との差について、区はその理由をどんなふうにお考えなのか伺いたいと思います。納税義務者数について、まだまだ不確定要素があるのかもしれませんが、２００万円と７００万円の区切りで考えると、最終補正の２０億円増とは、どこの区切りが伸びるという見込みなのか、年齢別での特徴などはあるのか、その見方を伺いたいと思います。","respondent":"高森税務課長","answer":"比率としては実は変わっていなくて、本当に納税義務者が増えているということで申し上げておきます。","voiceIndex":99,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"非課税の方の内訳、でも、比率としては変わっていない、納税義務者数が増えたんだというご説明、なので、例えば、２００万円と７００万円のこの区切りで見ると、どういう特徴があるのか。つまり、この２０億円増というのが、どういう見通しの中で組み立てたのか、そこを伺いたいと思います。","respondent":"高森税務課長","answer":"具体的なお話を申し上げますと、平成２５年度の当初予算におきましては、普通徴収分納税義務者数は８万９,０００人ほど、１人当たりの納付額が１１万円、特別徴収においては１２万４,０００人ほど。","voiceIndex":101,"id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"若い世代の雇用条件は依然厳しく、区もさまざまな事業を展開しているなど、厳しい状況がある中で、なぜ実感と実態が異なるのかはよくわからないので、改めて伺いたいと思います。ちなみに、品川区の人口動向について、例えば１年間で転入される方の人数や年齢別などの内訳もあわせて伺いたいと思います。","respondent":"高森税務課長、井浦戸籍住民課長","answer":"一方で、住民税の啓発活動等、区民の方に納期内納付の推進をしたり、口座振替の加入促進、そして納付いただけない方につきましては、滞納処分の推進によりまして。平成２５年１年間の転入者数ですが、品川区で１年間で２万６,８４９人です。年齢別の内訳ですが、三つで分けてございまして、０歳から１４歳が１,６０３人、１５歳から６４歳が２万４,４３９人、６５歳以上が８０７人。","voiceIndex":103,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"転入の傾向を伺いましたけれども、そういう大体２万６,０００人ほど毎年の転入というのは、大体ここ何年か同じような傾向が続いているのか。要するに、冒頭からの私の疑問は、生活している者にとってはよくなったという実感はないだけに、この２０億円、新年度でいえば２９億円、区民税を増収と見込んでいるんですけれども、この差は一体何かなと思いますので、改めて伺いたいと思います。","respondent":"井浦戸籍住民課長、高森税務課長","answer":"転入者数のここ最近の傾向ですが、平成２４年度、前年につきましては、２万６,９５１人、平成２３年が２万６,１８５人で、プラス２％、あるいはマイナス２％という形で推移しています。何を言われましても、私どもでは、あくまでも所得税の伸び率だとか、源泉徴収税額の特殊要因とか、営業所得でありますとか、給与所得だとか、分離課税の対象だとか、さまざまな所得の種類があるわけですけれども。","voiceIndex":106,"id":"exchange-040"},{"speaker":"中塚委員","kind":"質問・要望","question":"算定の根拠は実態でということだと思います。４月から消費税も上げようとされ、暮らしの問題を不安な声がたくさん上がっております。ぜひ税金の面からも区民の生活実態の把握、また、その特徴などをつかんでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":109,"id":"exchange-041"},{"speaker":"沢田委員","kind":"質問・要望","question":"繰入金についてなんですけれども、先ほど、午前中も藤原委員のほうから質問がありましたけれども、この繰入金というものについての考え方について伺わせていただきたいんですけれども、平成２５年の補正ということで、補正前は７３億１,４１１万２,０００円、補正後は５８億８,８１９万７,０００円ということで、１４億２,５９１万５,０００円の減ということでありますけれども。","respondent":"本城企画財政課長","answer":"基金繰入金についての基本的な考え方ですが、当初予算を計上いたしますときには、全体の歳出に見合った必要な財源の一部として繰入金を充てているわけですが、今回の公共施設整備基金と義務教育基金の繰入金につきましては、事業の実績の見合いで。","voiceIndex":112,"id":"exchange-042"},{"speaker":"沢田委員","kind":"質問・要望","question":"一昨年を見ると、予算では１０１億円ということでしたけれども、決算では２４億円ということで、昨年、一昨年を考えると、予算から決算に至るまでの間で５０億円以上の繰入金を使わずに済んだということだと思うんですけれども、今年度の補正の段階では、今、５８億円ということでありますけれども、この補正というのは、最終の補正ということで今回出ていることと思いますけれども。","respondent":"本城企画財政課長","answer":"こういう意味で、税収等の歳入の見込みと、今度は歳出の見込みをそれで必要な限りに繰り入れるという段階ではありますが、この後、今、委員のご指摘がございましたように、最終的には決算時ということになります。","voiceIndex":114,"id":"exchange-043"},{"speaker":"沢田委員","kind":"質問・要望","question":"できる限り最終補正は正確であるべきなのかと思いますので、そのあたりのことを伺わせていただきたい。","respondent":"本城企画財政課長","answer":"ただ、実際にまだ何カ月か若干の期間が残っている間、どうしても見込めない部分が出てきてしまったり、特に予算の執行に当たって相手方如何によって執行の可否がかかわるもの等、行政だけでは見込めないというところもどうしても出てきてしまいますので。","voiceIndex":116,"id":"exchange-044"},{"speaker":"沢田委員","kind":"質問","question":"８７ページの住宅・建築物耐震化支援事業についてお伺いいたします。","respondent":"品川木密整備担当課長","answer":"こちらの耐震化事業の補正の減額ですが、こちらは特定緊急輸送道路沿道建築物耐震化の部分に限られての補正の減額になっています。今回、補強設計、それから改修等を含めまして、予算のときに１５軒と出していたんですが、今回、半分の減額補正をしております。","voiceIndex":118,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１２ページ、債務負担行為補正、浜川雨水排水管、東品川橋架替工事、時間があれば３点目、１２２ページ、国保会計歳出で、保険給付費全般から、ジェネリック医薬品の使用促進について伺います。先月の２月２５日に城南第二小学校で改修計画の説明会がありまして、私も参加させていただきましたので、その上で幾つか確認させていただきたいと思います。","respondent":"多並公園課長","answer":"改修に当たりましては、特に子どもの遊ぶゾーンにつきましては、子どもたちのアイデアを入れた遊具等を入れまして、そのような子どもたちが遊びながら交通環境について学べるような、そのような総合的な公園にしたいです。","voiceIndex":122,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"確認","question":"今ご説明がありましたように、昨年の予特で交通公園という定義についてお聞きしました。確認ですけれども、国の定義として、交通公園とは、公園内に通常の道路とともに信号機、横断歩道、道路標識などを設けて擬似的な交通環境を再現して、遊びながら交通知識や交通ルールを学ぶための公園だと。これまでそのほかに存在したのかどうか、わかる範囲で教えてください。","respondent":"多並公園課長","answer":"今現在にして残っているところといたしましては、東品川公園が残っているところです。ここにつきましても、今後、交通安全対策、警視庁とも連携を図りながら、そのようなコンセプトでの整備を図っていく、そのように考えているところです。","voiceIndex":124,"id":"exchange-047"},{"speaker":"あくつ委員","kind":"質問・要望","question":"それで、昨年の決算特別委員会で公明党から、この整備計画に当たっては、自転車の安全対策、マナー、交通ルール、こうしたことを区民の方がしっかり学ぶ場として、講習会などを開催できる基幹公園として整備をしてくださいと、このような要望を出させていただきました。こういうようなこともなかなか周知がされていないという状況があって、そういう意味から、私ども、こういう要望を出させていただきました。","respondent":"多並公園課長","answer":"警視庁といたしましても、春や秋に交通安全運動に合わせた啓発活動など、今後行いたいということもありますので、そのようなところで連携を図りながら今後も進めてまいりたいと思っているところです。","voiceIndex":126,"id":"exchange-048"},{"speaker":"あくつ委員","kind":"質問・要望","question":"警察からの要請がさまざまあったということで、前回もそのようなご答弁をいただいて、今もそのようなご答弁をいただきました。このあたり、品川区において、この東品川公園の交通公園の機能を存続することにおいて、警察の要望というのももちろん大事だと思うんですけれども、品川区としてのお考えは何か議論があったのかどうか、その辺について伺いたいと思います。","respondent":"多並公園課長","answer":"警視庁との連携もさることながら、区の中でも交通安全担当とも、今後、区の中の啓発活動に使えないかということで相談しながら今回のコンセプトについても整備しているところであり、今後も工事を行い、開放した後には。","voiceIndex":128,"id":"exchange-049"},{"speaker":"あくつ委員","kind":"質問・要望","question":"八王子市の東浅川交通公園、年間利用者数がここはどんどん増加している。１２ページの債務負担行為補正で、浜川雨水排水管設置工事と、東品川橋の架替工事、１０２ページの債務負担行為の理由というところを読むと、浜川雨水排水管では工事ルートの変更とあり、またその後の説明文は、二つとも一緒なんですけれども、賃金、物価の上昇とありますけれども、それぞれその理由について具体的に教えてください。","respondent":"平澤経理課長","answer":"一つ目に、浜川雨水排水管建設工事、こちらにつきましては、下水管のルートの変更ということで、地中障害物があったのがわかりましたので、そちらに関すること。それとあわせて、物価スライドということで、この間の物価の上昇に伴うものです。","voiceIndex":130,"id":"exchange-050"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これとともに一定の公共工事においては、この公共工事標準請負契約約款第２５条、これはいわゆるスライド条項というものなんです、これは前からあるみたいですけれども、これの積極的な適用を国として地方自治体にも求めた、こういうことがあったと思います。このスライド条項の適用というのは、もちろん新しい２月から適用になった新労務単価を適用しているということだと理解しております。","respondent":"平澤経理課長","answer":"こちらにつきましては、インフレですので、まず工事期間が１２カ月以上ないといけないです。あわせまして、１.５％を超える部分について適用するというものです。したがいまして、今行われている案件の中では、この２件が対象ということで、事業者からご協議をいただいです。","voiceIndex":132,"id":"exchange-051"},{"speaker":"あくつ委員","kind":"質問","question":"１.５％の上昇は何を１.５％上昇なのかというのをもう１回お伺いしたいのと、基本的にこの協議というのは業者からの申し出がないとなかなか受けられない、事業者からの申し出があれば受けるというのは原則だと思うんですけれども、その点、品川区からの周知というか、そういうものはされていらっしゃるのか伺いたいと思います。","respondent":"平澤経理課長","answer":"今回、個別の指導ですが、まず初めに、１２カ月を超えるような長期にわたる工事というのは、区の場合はなかなかないということでございまして、その案件につきましては、いわゆる大企業が中心ということで、この契約約款につきましては。","voiceIndex":134,"id":"exchange-052"},{"speaker":"あくつ委員","kind":"質問・要望","question":"これが２月２８日付の記事です。これが正確かどうかわかりません。次に、３点目です。国保会計歳出で、保険給付費からジェネリック医薬品の使用促進について、本年度分について伺いたいと思います。生活習慣病が主だと思ったんですけれども、実は私、首をお祭りのときに御神輿を担ぎ過ぎて、ご存じのとおりあんまりなれていないものですから、首が回らなくなってしまいまして、病院に行って湿布を行ったと。","respondent":"間部国保医療年金課長","answer":"ジェネリック差額通知につきましては、長期にわたりましてお薬を服薬する可能性が高い生活習慣病を中心に設定しています。","voiceIndex":136,"id":"exchange-053"},{"speaker":"あくつ委員","kind":"質問","question":"細かくやっていただいているなということでうれしかったんですけれども、昨年７月から、７月、１０月、そして今年の２月ということで、３回にわたってこの差額通知が行われていると思います。事業開始から約半年が経過しましたけれども、差額通知の対象者は何名だったのか、また、切り替えがどれだけ進んだのか、わかる範囲で教えていただければと思います。","respondent":"間部国保医療年金課長","answer":"ただ、ダブりもありますので、実人数については１万５００人という実績があります。２月末現在の切り替え率ですが、約７％です。","voiceIndex":138,"id":"exchange-054"},{"speaker":"石田（し）委員","kind":"質問","question":"私からは、３８ページ、特別区財政調整交付金について、５６ページ、雑入、被災地派遣職員給与、６９ページ、７１ページのシステム開発費、１００ページ以降の債務負担行為に関連して質問します。時間があれば、ほかもやりますが。予算書を見ると、３４０億円になっていますので、まずその点をお知らせください。","respondent":"本城企画財政課長","answer":"都区財政調整交付金につきましては、１目であります普通交付金のほかに２目に特別交付金が１０億円ございまして、特別交付金の１０億円もプラスしたものが全体として補正後の３５０億円になるという、こういうことです。","voiceIndex":142,"id":"exchange-055"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"５６ページ、雑入ですが、被災地派遣職員給与費負担金、これについて、まず何人の職員の方が派遣されているのか、また、どのくらいの期間を派遣職員として派遣されているのか、また、９７ページに、単身赴任の手当というのが出ているんですが、品川区で単身赴任というのはなかなか考えられないのかなという中で、この手当の関連性もあわせてお聞かせいただきたいと思います。よろしくお願いします。","respondent":"堀越人事課長、福島臨時給付金担当課長、秋山情報システム課長、本城企画財政課長","answer":"単身赴任のところですけれども、こちらは被災地のほうに派遣している職員に対して一定の要件に沿って単身赴任手当を支給しているものでございまして。想定されたシステムをつくれないかですが、この給付金自体が、ある意味、急に降って湧いたような話でもございまして。今般のこういう急なシステムの場合は、そういう要件を定めることができませんので。消費税の債務負担行為の関係ですが、この補正の中の全体の金額の中に消費税８％を見込んだ額として計上しています。","voiceIndex":144,"id":"exchange-056"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"システムの件ですが、想定をしてそのシステムをつくってほしいというわけではなくて、例えば、何歳から何歳までとか、そういった区切りでやるようなものが多い中で、じゃあ、ここに来そうだからこのシステムをつくっておこうではなくて、全体で把握している中で、例えば要件を打ち込めば、その該当者たちが抽出されて、それで事が進むというようなシステムは、現時点で存在しているわけであって。","respondent":"秋山情報システム課長、平澤経理課長","answer":"支給の管理です、届け出てきた申請書の中身を入れ込んで、振り込みなり何なり支給管理、進行管理をしなければいけない、そういう機能もつくり込まなければいけないということで、この辺の要件がかなり。複数年次にわたる契約と消費税の関係です。長期継続契約につきましては二つございまして、いわゆるリースの部分、それからあとは、庁舎管理等を含めました委託契約、こういうこと。","voiceIndex":149,"id":"exchange-057"},{"speaker":"石田（し）委員","kind":"質問","question":"システム開発費、１点だけ最後にお伺いしたいんですが、先ほど、今まで使っていたシステムをベースに新たに構築をしていくとありましたが、これは、そうしたら、例えばほかの自治体、ほかの小さな市と比べたらあれなのかもしれないですけれども、例えば２３区である程度共通のシステムというんですか、そういったものが構築されているのかどうか、そこだけを最後にお聞かせください。","respondent":"秋山情報システム課長","answer":"品川区で導入したシステムですけれども、ほかの区の採用の状況はちょっとわかりませんけれども、聞いた情報では、５区ほどで今、採用を検討しているということですので、開発費用についてはある程度聞いているというふうに考えています。","voiceIndex":152,"id":"exchange-058"},{"speaker":"石田（し）委員","kind":"質問","question":"時間が余ったので、８５ページの都市開発費の百反歩道橋架替についてですが、このエリアは、今、幾つもの工事が重なって工事がされている中で、例えば、百反の架け替えの工事をしていて、車で信号待ちをしていると、曲がったらすぐ別の水道の工事だったり、電気の工事を行っていて、そこでもまた待たなければいけない。よろしくお願いします。","respondent":"溝口都市開発課長","answer":"工事につきましては、連絡会を開きまして、百反歩道橋の工事業者または大崎駅西口の工事業者、また警察関係、また地元の町会そういったものを集めて定期的に連絡調整を進めながら工事を行っているものです。","voiceIndex":154,"id":"exchange-059"},{"speaker":"石田（し）委員","kind":"意見","question":"わかりました。しっかりと連携をしていただいて、通る人たちがスムーズに通れるように、またそこで変なお怒りをいただくよりは、連携をしっかりやっていただければと思いますので、ぜひ今後もしっかりと進めていっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":156,"id":"exchange-060"},{"speaker":"渡部委員","kind":"質問・要望","question":"その増要因、ほかに何かありましたら教えていただきたいのと、いわゆる率で言いますと、先ほど、実績に変わりないということだったんですが、確認として、普通徴収でたしか当初予算は９２.７５％、特別徴収で９９.３５％という収納率を組まれた上での計算だったと思うんですが、この数字がどのような形で、まだ決定はされていない、当然決算されていないわけですから確定はしていないんですけれども。","respondent":"高森税務課長","answer":"一方で、先ほどもちょっと触れさせていただきましたけれども、口座振替納付の勧奨事業を実施しておりまして、こちらのほうもおかげさまで平成１９年には１万７,５００件ほどだったんですけれども、平成２５年１２月には３万２,０００件ほどということで。","voiceIndex":158,"id":"exchange-061"},{"speaker":"渡部委員","kind":"質問","question":"よくわかりました。滞納繰越の方々に関しましても、いい数字で上がってきているということなんですが、実際問題、まだこのような少しよくなっている状況の中でも、滞納繰越ではないんですが、分納で納めたいですとか、ちょっと今まとまって今年は納税できそうもないみたいなご相談の件数自体はどうでしょう、例年と比べて多いか少ないか、景気動向も関係してこようかと思うんですが、わかれば教えてください。","respondent":"高森税務課長","answer":"済みません、今、手元にあるのが年度末の集計と平成２５年度については１月末の数字ということなんですけれども、相談件数につきましては、平成２４年度、電話、来庁相談等については３万２,０００件ほど、平成２５年度は１月末の段階で２万９,０００件ほどということですので。","voiceIndex":160,"id":"exchange-062"},{"speaker":"渡部委員","kind":"確認","question":"次、融資あっせん、先ほどもお話を聞きました。僕も数字を見ていまして、今回初めて上がってきたなという部分と、もともとの中小企業対策費の中で信用保証料の補助、４億５,３８１万７,０００円の予算が上がっていたものに対して、補正で１億７,８４０万８,０００円でしょうか、減額をされている。","respondent":"山崎ものづくり・経営支援課長","answer":"先ほどの国の制度の変更によって、そこの部分の予算は今回減額をさせていただいたところですけれども、それ以外の融資に実は相当数回ってきておりまして、まだまだ資金需要は一定程度あるというふうに思っているところです。","voiceIndex":162,"id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"歳入の４２ページ、国の部分の土木補助金、４８ページ、都の土木補助金、歳出のところは８４ページ、都市開発費で伺いますので、よろしくお願いします。","respondent":"溝口都市開発課長","answer":"歳入減額補正の件です。西品川一丁目地区につきましては、一つ大きなものとしては、当初、１６３号線の設計を予定しておりましたが、それにつきましては、ＪＲとの協議のおくれに伴いまして減額しているものが一番大きな理由になっております。","voiceIndex":166,"id":"exchange-064"},{"speaker":"飯沼委員","kind":"質問","question":"開発の補助金がどのように使われているのかということを知りたいんですが、使われなかった分、マイナスになっている分がどう処理されているのかというのを知りたいのが、疑問点が４３ページの歳入、国の補助金なんですけれども、そこと８５ページの歳出のところに額の差があるんですね。どのように処理されて、どこに返されているのか、どう協議されるのかというところを教えてください。","respondent":"溝口都市開発課長","answer":"先ほど、財調等の話がありましたが、それにつきましては、先ほどお話しした補助対象事業費の３分の１の区負担分につきましては、財調または都市計画交付金でまかなわれる、そういった仕組みになっているものです。","voiceIndex":168,"id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問","question":"補助対象のところが３分の１が国費、３分の１が区費で、３分の１が組合ということなんですけれども、その区のところの３分の１、財調の部分と都市計画交付金のところがどこにどうあらわれるのかというのがちょっとわからないので、そこを教えてください。","respondent":"本城企画財政課長","answer":"今回の補正の基本的な仕組みといたしましては、一つは都市計画交付金のところは東京都の補助金という中の位置づけで歳入されまして、そのほかの基本的には当該年度に２５％分が都市計画交付金で来まして、その後、２年目から４年間かけて財調で算定されるということになります。","voiceIndex":170,"id":"exchange-066"},{"speaker":"飯沼委員","kind":"意見","question":"今、都市計画交付金、都の補助のところが、初年度２５％、あと、２年目から４年間で財調上に残りがなるわけですけれども、ここの部分、実際に使われていない部分がどう戻されていくのか、どこに置かれているのかを知りたいので、疑問がそこなんですけれども。","respondent":"本城企画財政課長","answer":"都市計画交付金と財調でまかなわれているということで、財調の算定に当たっては、基本的に実績に応じて財調が基準財政需要額の中で算定されますので、使われなかったということではなくて、実際にかかった分について財調から歳出されるという形です。","voiceIndex":172,"id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問","question":"実績ということであらわれていく。その後の年度に対しては、最初、４分の１ですか、４年間でということで、その後の処理はどういうふうにあらわれていくのか教えてください。","respondent":"本城企画財政課長","answer":"若干繰り返しになってしまったら申しわけないんですが、都市計画交付金で２５％の後に、その後の４年間で、それぞれ実績を確認されたものということで、それぞれの実績を算定して、全体で４年間で交付されてくるという形です。","voiceIndex":174,"id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問","question":"初年度の当初の予算のところもお伺いしたいんですけれども、今、国が３分の１、区のところが３分の１で、２５％の都市計画税と７５％の財調ということなんですけれども、その辺で具体的にそれぞれのところ、都市計画税が幾ら入っているか、また財調が幾ら入っているかというのは、きちんとどこかに書かれているのでしょうか。西品川と大井一丁目と別々に、どういうふうに書かれているのか教えてください。","respondent":"本城企画財政課長","answer":"今、財調の関係で２５％以外の部分は、４年間で財調から来るということで、それで、計算としてどこにあらわれるかというと、いわゆる財調算定上の基準財政需要額というところに実際かかった実績が加算されることによって、その計算の結果。","voiceIndex":176,"id":"exchange-069"},{"speaker":"飯沼委員","kind":"質問","question":"今の部分ですけれども、私たちが目にする予算書とか、補正とか、こういうところにはあらわれなくて、財調の基準財政需要額の算定のところにまで踏み込んでいかないと、私たちはそこを知ることができないのかどうか教えてください。","respondent":"本城企画財政課長","answer":"そういう意味では、財調にしろ、補助金にしろ、計算過程の詳細について全て予算書の中に書かれているわけではございませんが、ただ、財調という東京都と区の間の役割分担を踏まえた交付金ということなので、その中で言えば。","voiceIndex":178,"id":"exchange-070"},{"speaker":"飯沼委員","kind":"質問","question":"いまの財調の仕組みからすると、目に触れることができないので、やはりその辺まできっちりわかるような表記の仕方、工夫が必要であると思いますが、この点はいかがでしょうか。","respondent":"本城企画財政課長","answer":"予算書全体の構成の中でなかなか基準財政需要額の個々の分まで書くのは難しいところがありますので、そういったことについては、付随的な説明も含めた形で丁寧にご説明していくこととして考えているところです。","voiceIndex":180,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"質問・要望","question":"初めに、西品川一丁目、大井一丁目の南地区の状況を伺いましたけれども、西品川では組合が設立され、大井一丁目南のところはまだ設立されていない、阻んでいらっしゃる方がいらっしゃいますが、どちらも住友不動産が強引に進める開発、住民の追い出し、今、品川区民が不安や先の見通しがつかない状況に追い込まれている、この間、たびたび質問で取り上げしていますけれども。","respondent":"溝口都市開発課長","answer":"少し再開発の仕組みについてご説明をします。権利変換というものにつきましては、従前資産を反対、賛成にかかわらず、しっかり評価した上で、その評価に基づきまして従後の資産をどのようにしていくのかというのを決めていく形になっております。","voiceIndex":182,"id":"exchange-072"},{"speaker":"飯沼委員","kind":"質問・要望","question":"実際的に権利変換後の評価、価値、具体的に示されていません。そして、どちらにも判を押さなかった人が、この後、強制収用されるのかどうか、ここをはっきりお答えをしていただきたいと思いますし、私は区が税金を投入して、こういった地域の方々を分断していく、地域からは、仲よく暮らしていた地域の人たちが、開発に協力をする賛成派、協力をしない反対派、ばらばらになっている、地域が壊れています。","respondent":"溝口都市開発課長","answer":"これはあくまでも権利者間の公平性を期するために、反対者であれ、賛成者であれ、しっかりと権利変換をしていくための制度になっておりますので、一方的に皆さんを追い出すような再開発事業を進めているものではございません。","voiceIndex":184,"id":"exchange-073"},{"speaker":"こんの委員","kind":"質問","question":"私のほうからは、４８ページの妊婦健康診査事業補助金、同じく７５ページでも母子健康診査、それからもう一つが、７３ページの生活保護費国庫支出金返還金について、この２点をお伺いいたします。改めてお聞きするんですが、この制度変更の背景と、現在の財源は一般財源として確保されているんですが、今後の財源の確保、財調の関係はどうなっているのかをお聞きしたいと思います。よろしくお願いします。","respondent":"江部健康課長、本城企画財政課長、竹田生活福祉課長","answer":"これにつきましては、国の補助事業がなくなり、全国的に今、一般財源で対応するですので、区としてもそのように対応しているものです。今、答弁がございましたように、一般財源化されたことに伴いまして、特別区においては財調で算定される形になったという経緯です。不正受給等の返還金に関するご質問ですが、平成２４年度の実績を申し上げますと、収入した金額が８,４９０万円余、その内訳としましては。","voiceIndex":187,"id":"exchange-074"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、１４回が確保されているということは、昨年度の決算特別委員会でもそのようなご答弁をいただいたので、改めて確認をさせていただきました。今後の妊産婦健診で１４回程度ということでされているんですけれども、いわゆる検査項目としてあるその項目以外で、自己負担になっている部分がかなり多くあるという声を聞いています。一部この改正に伴う動きも教えていただきたいと思います。","respondent":"江部健康課長、竹田生活福祉課長","answer":"今、委員お尋ねの少子化対策等その他新たなニーズがあるということであるならば、必要があれば、その検討会が再度開始されるものと考えていますが、今のところはそういう情報は得ておりません。返還金に当たるものについて若干ご説明しますと、保護費は１カ月前払いであること、あるいは、収入があった場合は翌月等に申告してさかのぼって認定する等の理由から返還金が生じているものです。","voiceIndex":191,"id":"exchange-075"},{"speaker":"こんの委員","kind":"質問・要望","question":"一部法改正がありまして、いわゆる返還金について自治体間で調査を強化できるという体制のご答弁がございましたけれども、これが７月１日から行われていくということですけれども、これまでやはり公的な、例えば年金、企業年金だとか、厚生年金だとか、こうしたものはご自分でいただいたものに対してどういうふうに申告をしていくのか、これは受給するときに、このご説明は受けているはずですけれども。","respondent":"江部健康課長、竹田生活福祉課長","answer":"ただ、一人ひとりかなり違う健診内容になっておりますので、一律に公費で助成する妊婦健診制度というところにどういうふうに救い込むかというのは課題が多いかと思いますが、ここは研究してまいりたいと思います。今後も生活保護法が適正に執行できるように、与えられた権限を有効に活用して保護の実施に努めてまいりたいと考えています。","voiceIndex":194,"id":"exchange-076"},{"speaker":"高橋委員","kind":"質問","question":"本会議でも労務単価を、積算の基準、平成２５年は８回上げた、そして今年の２月には７.１％、これは国指示のような形でやったようです。被災地は８.４％。金額は１００万円からという状況もあったりしますけれども、区内の中小企業の方々にとっては非常に貴重な公費なんですが、労務単価や、さまざまな資材単価などをアップして、このような当初予算が組まれていたのでしょうか。","respondent":"平澤経理課長","answer":"本件につきましては、適用されていない場合は、昨年の５月に実施しました特例措置を実施するということで、事業者のほうから協議をしていただきまして、旧単価で積算した部分につきましては、新労務単価で新たに契約をし直すという段取りを組んです。","voiceIndex":198,"id":"exchange-077"},{"speaker":"高橋委員","kind":"質問","question":"とすると、新労務単価でこれらは積算されているという認識でよろしいんですか。","respondent":"平澤経理課長","answer":"全てがということになりますとあれなんですけれども、ない部分について、旧労務単価で積算した部分については新労務単価で、新労務単価で積算した部分についてはそのままでです。","voiceIndex":200,"id":"exchange-078"},{"speaker":"高橋委員","kind":"質問","question":"さらにまた、まだまだアップ要因があって、それがさらにまた新年度に入ってさまざまな状況の中で値上がりして工事をしなければいけない状況になると、そのときには、その業者には、この金額でやっていただくわけになるのでしょうか。それとも値上がった分をさらに何らかの手当てをするか、それとも業者のほうに負担するということはないわけだと思うんですけれども、その点についてはどうでしょうか。","respondent":"平澤経理課長","answer":"もう一つが単品スライドというものです。こちらは、例えば燃料費とか、鋼材が１％を超える範囲で上昇した場合、こちらにつきましても一つひとつの品物につきまして協議をして上げすることもできるです。","voiceIndex":202,"id":"exchange-079"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、それぞれの値上がりに対して今のようなお話で対応をしていっていただくというお話だと思うんですが、これは建設工事のお話で、今お話しあったように、スライドや新労務単価でというお話なんですけれども、事業の委託、例えば児童センターで業務委託している、あるいは指定管理で数年にわたって契約している、そのような中で労務単価のアップがあった場合は、どのような形で、工事関係というのは。","respondent":"平澤経理課長","answer":"それにつきましては、協議の上ということで、そういった契約変更があるのかもしれませんけれども、それにつきましては、ご相談いただきまして、個別の中身でやるような形になるわけですが、基本といたしましては、事業者の見積もりに基づいて契約しているものですので。","voiceIndex":204,"id":"exchange-080"},{"speaker":"高橋委員","kind":"確認","question":"介護士や保育士の方の待遇については、単価を上げてさまざまなことが行われているんですが、今、あるかもしれないけれども、基本的にそういうことはないという、そういうような形であったんですけれども、今、金額と質の両方を担保していくのはなかなか難しいところだと思うんですが、このような形では、工事と事業者との話ではありましたけれども、見積もりの段階で想定しなかったけれども。","respondent":"平澤経理課長","answer":"委員ご指摘の想定を超えるような物価上昇がどの程度のものになるのかというのは相談の範囲になると思います。そういう状況になりましたら、そういったようなご相談について真摯に受けとめて相談に対応していくというのが筋道だと考えています。","voiceIndex":206,"id":"exchange-081"},{"speaker":"高橋委員","kind":"質問","question":"もし行われていないとすると、中小企業や零細企業などへの救済になるんですが、その辺のところのお考えはいかがでしょうか。","respondent":"平澤経理課長","answer":"設計ということになりますと、どういうことが想定されるかということになるわけなんですが、そちらにつきましては、大きな検討課題であることは間違いないということで、今、どういった形でできるかということを検討しています。","voiceIndex":208,"id":"exchange-082"},{"speaker":"高橋委員","kind":"質問・要望","question":"資金繰りが非常に逼迫している区内の中小、零細企業への救済になりますので、ぜひ前向きに検討して、先ほどの工事の前払金と同じような形で検討を進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":210,"id":"exchange-083"},{"speaker":"大沢委員","kind":"質問・要望","question":"その前に２点だけ確認をさせていただきたいんですけれども、朝一番の本日の平成２５年度品川区各会計補正予算というところで、企画財政課長から、この補正予算を編成しましたということで、やむを得ない事情により、またこのやむを得ない経費の中でのということで編成をしましたということのお話をいただいたんですけれども、そういう表現でいいんですか。","respondent":"本城企画財政課長","answer":"「編成」という言葉自体は法律用語ではない、地方自治法の用語ではないとは思います。自治法上だと「調整」という言葉を使っておりますので、そういう意味では、「編成」ということは自治法では「調整」という形での意味を基本的には考えているというふうに理解しています。","voiceIndex":212,"id":"exchange-084"},{"speaker":"大沢委員","kind":"質問","question":"その自治法云々という難しいことではなくて、補正予算、もう既に行われたか、平成２５年度に行われて、あるいはこれから行われるということで、本来であれば、これからまた起こり出すだろうということに関しては「編成」、もう既に起こってしまったことに関しては「編成」という表現は当たらないんじゃないですか、どうなんですかということ。","respondent":"本城企画財政課長","answer":"そういう意味では、言葉足らずなところがあったかもしれません。提案といいますか、案という形でご説明するべきものだと考えております。","voiceIndex":214,"id":"exchange-085"},{"speaker":"大沢委員","kind":"質問","question":"ご説明するべきものということではなくて、表現についてお話をしているわけでありまして、やはり僕らも言葉にはきちっとした意味合いを使いたいなと、これは後から足りなかったものを補っていくんだから、計上していくという行為が正しいと思うんですけれども、どういうふうにお考えですか。「編成」ではなくて「計上」。","respondent":"本城企画財政課長","answer":"そういう意味では、「編成」とか「計上」とか、いろいろご説明する上では概念をしっかりして説明していくことが非常に大切だと思いますので、そういう用語については改めて研究します。","voiceIndex":216,"id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"それともう一つなんですけれども、財政調整云々について、難しいので僕もよくわからないんですけれども、ここのことについては、ただ国、都からということで、先ほどから答弁いただいていると、来るということでの意味合いが強くて、本来であれば、先ほどおっしゃっていた財政基準、今、算定をしている、ちょっと言葉は悪くなりますけれども、ぶんどってくるというような意味合いの。","respondent":"本城企画財政課長","answer":"そういう意味で、もともと本来的に区税であったものを共有しているものなので、来るという表現ではないほうがいいとは思います。","voiceIndex":218,"id":"exchange-087"},{"speaker":"大沢委員","kind":"質問・要望","question":"表現はもういいです。そこのところはお考えがある程度はやはり言葉に出てきてしまいますので、気持ちの上で、やはりほかから来る財源として十分な、非常に重要な財源ですので、そこは来るのではなくて、わざわざ足を運んで取りにいくというような、そういうような意識の中でいろいろなことをしていただきたい。これは僕は合っているかどうかわかりません。","respondent":"柏原行財政改革担当課長","answer":"ケーブルテレビですけれども、株を売却いたしました。品川区の持ち分といたしましては７％ということにはなっておるんですけれども、基本的には南東京ケーブルテレビにつきましては、会社そのものは何かが大きく変わったというものではございません。","voiceIndex":220,"id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"ところが、私は、皆さん、小さいサンプリングになりますけれども、最近のケーブルというか、東京でも営業活動の熾烈を極めているような、要は、非常にご熱心な営業活動をしているということで話を伺いますけれども、会社は今後、今、売ったばかりですので、区からちょっと距離を置いたほうがいいですけれども、今後どうなるかわからないですけれども、今後、大丈夫なのかどうか。","respondent":"柏原行財政改革担当課長","answer":"その辺は個別にどういった細かいことまで営業活動の強さといいますか、確認はしないといけないかなと思いますけれども、ただ、意気込みでいろいろなものを、体質そのものを、営業しないとだめだということではなくて、新しいことをどんどんやっていこう。","voiceIndex":222,"id":"exchange-089"},{"speaker":"大沢委員","kind":"意見","question":"今はもう会社、この世の中の目まぐるしい経済状況の中で、要は、営業活動のスパンも非常に短くなっている。これが今、かつては１０年だ、２０年だという、特にサービス業においては３年だったり、５年だったり、２年だったりするんですけれども、そこの営業の短くなってくるスパンと創業支援について、ちょっと何か、短いんですけれども、考えがあったら言ってください。","respondent":"山崎ものづくり・経営支援課長","answer":"区の武蔵小山の創業支援センター、あるいは西大井のほうで統計をとりまして、６割を超えているような状況です。そうしたさまざまな起業されてからの継続の支援についても努めてまいりたいというふうに考えてあります。","voiceIndex":224,"id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"私からは、もういろいろとお話が出ております３４ページの特別区民税等について、それから７１ページ、保育園職員費について、７９ページの被災者雇用助成事業、８９ページのスクールカウンセラーの財源更正、あと８９ページの小中一貫教育寄附金収入などについてお伺いしたいと思います。２０分あるので全部行けるかなと思います。","respondent":"本城企画財政課長","answer":"そのような中で予算案をつくるときに、どうしてもそのときの経済状況がどういう方向に向かっているのかということを踏まえて考えることになってくるですので、ちょうどこの当初予算を組むときには、まだ経済の先行きが厳しい状況ということを基本認識にして。","voiceIndex":227,"id":"exchange-091"},{"speaker":"あべ委員","kind":"質問","question":"もしかすると、比較的裕福な方々が増えて、そちらのほうが全体を引き上げている一方で、非課税世帯は減っていないということでしたし、国民健康保険料、これは収納率が下がっているのか、それとも支払義務者と言ったらいいんですか、加入数が減っているということなのか、１人当たりが減っているということなのか、ここの国民健康保険、後期高齢者医療保険は、どうして減っているのか。","respondent":"間部国保医療年金課長","answer":"最終的には、今、八六、七％という予測を立てておりまして、その相差の分を減額補正という形になっております。後期についても、大体９８％から９９％で組んでありまして、最終的の見合いということで実績見合いで減額補正という、大体このような考えです。","voiceIndex":229,"id":"exchange-092"},{"speaker":"あべ委員","kind":"質問","question":"次に行きます。区の認可保育園数は増えているはずなんですけれども、この時期で減額が出てくるのは当初からの人件費が減っているという、以前、ご説明を受けていたことがあるんですけれども、これは人数も減っているんですか。それとも年齢、比較的高齢の方が定年退職などをして、年齢が若返ったことによる減なんでしょうか。それはどのような形で減になっているか教えてください。","respondent":"堀越人事課長","answer":"マイナス改定がありますのと、それから、若手の職員数を一定数、保育士を採用しておりますので、そういった年代層の違い等がありまして、こういった３億６,８００万円余というような形での減額となってあらわれているというものです。","voiceIndex":231,"id":"exchange-093"},{"speaker":"あべ委員","kind":"質問・要望","question":"済みません、聞き方が悪かった。そうすると、マイナス３億８,０００万円あるのであれば、それをさらにプラスして質を上げるだけの人件費、何らかの形で充てていくことも考えるべきだと思っているんですけれども、そこはどのようになさっているか教えてください。","respondent":"堀越人事課長","answer":"保育園の開設等も行っておりますし、人数についても一定数の増をここ数年図ってきておりますので、保育士としてのマンパワーにつきましては、適切な対応が図られているというふうに考えているところです。","voiceIndex":233,"id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、ハローワークを通してご相談いただいたところに事業の説明をしているというふうに聞いているのですけれども、もう少し広く、こういう事業がありますよということを広くアナウンスすることによって、それなら雇ってみようかという企業を刺激するようなこともあってはいいのではないかと思いますが、何かされていれば教えていただきたいですし、今後のお考え方も教えてください。","respondent":"堀越人事課長、山崎ものづくり・経営支援課長","answer":"保育士の人材の面ですけれども、採用につきましては、ここ数年、３倍から４倍の採用倍率があります。一定、能力のある人間を採用できているというふうに思っております。研修についても体系的にやっているところです。そうした意味では、現地のハローワーク、品川区のハローワークと、私ども就業センターを介して連携をとっておりますので、そうした意味でも、十分雇用が創出されるようなことを受けとめまして。","voiceIndex":235,"id":"exchange-095"},{"speaker":"あべ委員","kind":"質問","question":"スクールカウンセラーについて伺います。スクールカウンセラー、財源更正ということなんですけれども、区でスクールカウンセラーに入っていただいていて、今度、都でも入るようになったというくらいの理解しか私していないんですけれども、この補正の間に、区のカウンセラーというのは何人ぐらいいらして、それで都の仕組みができて、都のカウンセラー何人が入ってこられたのか教えてください。","respondent":"渋谷指導課長","answer":"済みません、今回のこの補正のスクールカウンセラー派遣に対する都支出金が、いわゆるスクールソーシャルワーカーの活用事業に関する補正です。区のスクールカウンセラーの数は、今、数えします。済みません。","voiceIndex":238,"id":"exchange-096"},{"speaker":"あべ委員","kind":"質問","question":"私、勘違いしていました。もともと区のソーシャルワーカーがいらして、それが都になったということになる。そうすると、同じ方に対して給与の出もとが変わったということなのか、それとも人をチェンジすることになったのかということを教えてください。","respondent":"渋谷指導課長","answer":"区のスクールソーシャルワーカーは、既に品川区で今年度から採用させていただいたんですが、東京都のほうでも平成２５年度からスクールソーシャルワーカー活用事業というものを開始いたしまして、各区で採用しているスクールソーシャルワーカーの事業に対して。","voiceIndex":240,"id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"ちょっと私が理解していたのと違ったので。カウンセラーについては、都の制度が入ったときに、区の方が辞めて都の方が入っていらして、だから同じ学校でカウンセラーが継続できなかったという例を聞いたものですから、今回もそういうことがあったのであれば、非常にもったいない話だと思ったんですけれども、それはどういう違いなんでしょうか。ちょっと教えてください。","respondent":"渋谷指導課長","answer":"小学校のスクールカウンセラーにつきましては、区費のスクールカウンセラーは継続でございまして、平成２５年度については、都費でスクールカウンセラーが新たに週に１回ずつプラスで配置されたという経緯です。","voiceIndex":242,"id":"exchange-098"},{"speaker":"あべ委員","kind":"質問","question":"それから同じ８９ページで、小中一貫教育寄附金収入、去年の予算特別委員会でも伺ったんですけれども、寄附金をいただいた分だけ一般財源を減額して、一般財源にその額を入れるというのは、私はどうもやっぱり納得できないんですね。６９ページを見ましても、特養ホーム寄附金で１,０００万円分の寄附をいただいていて、その分、要は、福祉の予算を１,０００万円とって一般財源に戻している。","respondent":"本城企画財政課長","answer":"ただいまの件ですが、今ご指摘いただいたような形でご意見の趣旨は理解できるところですが、ただ、今回の財源の充て方についても、あくまでも、例えば特別養護老人ホームの関係でありましたら、寄附をいただいた方の意思に即した形でここの範囲の財源に充てているという意味では。","voiceIndex":244,"id":"exchange-099"},{"speaker":"あべ委員","kind":"質問","question":"今の、皆さん、おわかりでしたでしょうか。結局、受け取って、過ぎたものは区の一般財源なわけですよね。そうだと思います。やっぱりいただいたら、くださった方に対する、全額すぐに使えとは言いませんけれども、何かいただいたら、いただいたものがいただいたものとして生きるような使い方というのをもう少ししっかり考えたほうがいいのではないかと思いますけれども、もう一度ご答弁ください。","respondent":"本城企画財政課長","answer":"現在の取り扱いの考え方につきましては、繰り返しになってしまいますが、基本的にはご意思の範囲で、それにかなった形のものに充てているという意味では、意思に反した取り扱いではないとは考えているところでございまして、ただ、ご意見を踏まえて、どういうやり方がいいのかは。","voiceIndex":246,"id":"exchange-100"},{"speaker":"あべ委員","kind":"質問・要望","question":"研究課題の一つと言っていただけたので、ぜひ考えていただきたいと思います。その分野に使ったのだからいいということではなくて、やはり寄附される方はここで充実してほしいと、今、プラスアルファしてあげてくださいという、その善意をぜひ生かすような形でご検討をいただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":248,"id":"exchange-101"},{"speaker":"山元委員","kind":"質問・要望","question":"改めてこの不妊治療、一般不妊治療、これは品川区で行っていますけれども、それ以外には東京都で行っている特別不妊治療ですか、二つ助成が分かれているわけですが、違いといいますか、これを改めて教えていただきたいと思います。","respondent":"江部健康課長","answer":"その後、それでもできないという方に顕微受精、顕微鏡を使った受精、それから体外受精を行うということに対する助成を都道府県レベルでやっているのが特定不妊治療事業になります。これにつきまして、２３区はさらにそこに上乗せをするという形での事業を行っているです。","voiceIndex":250,"id":"exchange-102"},{"speaker":"山元委員","kind":"質問","question":"そうしますと、通算５年間というのは、私もちょっとよくわかっていないんですが、大体２年間ぐらいで次の段階に行くということであれば、５年というのはどういう基準で決められたのか、また、この５年間というのは、本当に使っているというんですか、その辺はどうなんですか。","respondent":"江部健康課長","answer":"確かに私どもの一般助成について、約２年程度継続した場合は、そのぐらいの期間で次の段階に移られるということになりますけれども、場合によっては間が抜ける方もいらっしゃるだろうということで、少し広めに５年としたのではないか、私も推測で申しわけありませんが。","voiceIndex":252,"id":"exchange-103"},{"speaker":"山元委員","kind":"質問・要望","question":"了解しました。間があけるというお話がありました。先ほども１年間で１００数件が増えたことに、その辺、わからないというお話でありましたけれども、改めてこの周知方法というんでしょうか、どのように、いろいろなところでなされているかと思いますけれども、どのように周知方法をなさっているのか、その辺を教えていただきたいと思います。","respondent":"江部健康課長","answer":"個別のとか、特別の周知ということはしておりませんで、通常の広報しながわ、それからホームページを通じまして、私どもの行っております一般不妊治療助成事業と、あわせまして、東京都の特定不妊治療助成がありますというあわせてのご紹介をしております。","voiceIndex":254,"id":"exchange-104"},{"speaker":"山元委員","kind":"質問","question":"例えば、婚姻届を出したときに、それは晩婚とは限らないので何とも言えないんですが、でも、そういうものが品川区でやっているということもお知らせするというのは、そういうお考えはありますか。いかがですか。","respondent":"江部健康課長","answer":"ただ、目に触れるという形では少しでも広い方にお知らせする必要はあろうかと思いますので、今後、検討します。","voiceIndex":256,"id":"exchange-105"},{"speaker":"山元委員","kind":"質問","question":"よろしくお願いしたいと思います。本当に赤ちゃんが欲しくてもなかなかできない、お医者さんへ行ってもなかなか思い通りにならないことに対して、やはりそういう区としても気軽にという言い方は変なんですけれども、お医者さんまで行かなくても、何か自分の重たい心、気持ちを相談に乗ってくれるような、そんなところを設けてはいかがと思いますけれども、いかがでしょうか。","respondent":"江部健康課長、亀井品川保健センター所長","answer":"品川区では、現在、その辺について、まだ実施しているものではございません。今、東京都が不妊相談センターというのを持っていまして、そこでは、今、家族計画協会が運営をしていますけれども、そういうところが窓口になっておりますので、そういうところを紹介したり。","voiceIndex":258,"id":"exchange-106"},{"speaker":"山元委員","kind":"質問・要望","question":"それは東京都は実は平日しかやっていないんですよね。本当にお仕事を持っていらっしゃる方がゆっくり話を聞いてもらいたいとかと思うと、やっぱり土日を使ったりとか、その辺は区で何か工夫してあげてほしいなと思いますので、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":261,"id":"exchange-107"},{"speaker":"原委員","kind":"質問・要望","question":"それからその次が、５０ページ、財産収入、財産運用収入の財産貸付収入約４,０００万円減の補正、これは何なんでしょうかと。それから、５６ページに行きまして、諸収入の雑入の雑入です。それからあとは、６６ページ、６７ページ、先ほど石田しんご委員のほうからもありました。ですから、ここについて、私の質問としては、この算出根拠をお教えいただければと思います。以上６点です。","respondent":"白鳥高齢者いきがい課長、平澤経理課長、多並公園課長、工藤総務課長、稲田道路課長、渋谷指導課長、秋山情報システム課長","answer":"完成につきましては、平成２７年２月開設予定ということで、こちらのほうの補助金関係につきましては、東京都の推進しております、従来。私からは、地所賃貸料マイナス４,０２７万９,０００円についてご説明します。私からは、公園駐車場等のところについての、まずは公園駐車場についての簡単なご説明をします。こちらのほうが１区当たり約９４０万円お支払いしていたものが、国からの１０分の１０の助成が来たということで。","voiceIndex":263,"id":"exchange-108"},{"speaker":"原委員","kind":"質問・要望","question":"理解いたしました。１０分の１０ということで、非常に耳障りがいいんですね。ですから、１０分の１０、いろいろとれるものをしっかりとできることをやっていただきたいと、それについてのご意見があれは、もう１回ご答弁いただきたいということと、それから、その次に今度は土木橋梁、これは予定どおりに終了するということで、ぜひともお願いしておきたいと思います。はほかは理解しております。","respondent":"工藤総務課長、秋山情報システム課長、白鳥高齢者いきがい課長","answer":"このような形で国から出るようなものは受けるという視点で今後とも対応したいというふうに思っております。例えば、一人月幾らで、その方がどのぐらいの月数働くのかということで、改修の改修費を積み上げてしたものがこの結果になっているですので。説明書きのほうの西五反田三丁目サービス付高齢者住宅ということと。","voiceIndex":271,"id":"exchange-109"},{"speaker":"原委員","kind":"質問・要望","question":"それからあともう１点のところの西五反田三丁目、もう少し具体的なことを聞こうと思ったのでありますが、それは何かというと、民間に任せるのか、それとも公のほうがいいのか、半分公で、そうでないほうがいいのかと、明日以降ありますので、これは順次タイミングで機会がありましたら、またお伺いしていこうと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":275,"id":"exchange-110"},{"speaker":"伊藤委員","kind":"質問","question":"それはそれでいいんだけれども、初めから低く見積もっておいて、結果としてお金を合理的に品川区に入れていく、もともと私どもの財源だと思っているので、そのもの自体については特に問題ないと思うんだけれども、やっぱり当初算定のところで財調についてはもっとしっかり考えるべきだと思うんですが、いかがでしょうか。改めて答弁をお願いいたします。","respondent":"本城企画財政課長","answer":"一定程度、財源ということになりますので、確実に見込んでいるというところもありますが、このような経済状況を加味したものです。","voiceIndex":279,"id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"議会ですから、なかなかお答えがあるのかもしれないけれども、もともと私どもの財源だと私たちは思っているわけなんです。聞いていましたか。もともと２３区の財源ですから、それを合理的な基準で吸い上げていくのは正しいと思うわけです。","respondent":"本城企画財政課長","answer":"財源の見込み方ですが、繰り返しのところがあったら恐縮ですが、基本的に一番基幹財源となるものですので、それについては合理的な範囲で一定程度確実に見込んでいくということが必要なことであるとは考えているところです。","voiceIndex":281,"id":"exchange-112"},{"speaker":"伊藤委員","kind":"意見","question":"前区長は、このことについて相当議論されていました。今の区長もそうですけれども、東京都と２３区のあり方の中で、財源のことは大きな問題ですよ。だから、それがたまたまここ何年か続いているので、もうそろそろこれは本気で東京都と２３区の関係を再度見直していくなり、新たな制度を構築していく時期になったのではないかと思うんだけれども、もう一度だけご答弁をお願いいたします。","respondent":"濱野区長","answer":"この１年間で大きく経済が変わったということで、財調の中身の数字についても大きく変わったものというふうに思っております。姿勢としては、今、伊藤委員がお話のように、市町村民税の分を我々がとるんだという、そういう心構えでやっていきたいと考えています。","voiceIndex":283,"id":"exchange-113"},{"speaker":"伊藤委員","kind":"確認","question":"もう１回確認しますけれども、国の第３子の所得制限撤廃がされなかったことで約８,８００万円マイナスだという話を聞いたんだけれども、ということは、新年度、それはされるんですか、されないんですか。それだけお願いいたします。","respondent":"立川保育課長","answer":"国におきましては、この分については実施するという予定になっておりますので、新年度予算におきまして、この就園奨励費におきましても予算を組んでいるところです。","voiceIndex":287,"id":"exchange-114"},{"speaker":"伊藤委員","kind":"確認","question":"ここのところは数字の確認ですからわかりました。８３ページの下水道合流改善事業がありました。もちろん正しい契約だったのだろうけれども、今は逆にどんどん値段を上げていかないと業者が応札できない状況であるにもかかわらず、この８３ページでは、逆に３億３,０００万円も落ちているという、その現状と、それからこれは一体何なのかということについて、改めて説明をお願いいたします。","respondent":"奥田河川下水道課長","answer":"今、委員からご指摘がございました８３ページの下水道合流改善事業につきましてですが、こちらは当初予算では、６億９,１００万円を見込んでございました。","voiceIndex":289,"id":"exchange-115"},{"speaker":"伊藤委員","kind":"確認","question":"これは冷静に考えて、本当にその工事がどれだけ低価格でできるのかということは、やっぱり議会として当然指摘せざるを得ない。確かに課長がご答弁されて工事も進んでいるのだろうけれども、これはどういうふうに工事の内容の担保になるとか、それから、進捗状況の確認であるとか、それから業者の指導等はどうされているのでしょうかということをぜひお聞かせください。お願いいたします。","respondent":"奥田河川下水道課長","answer":"関係各課の協力を得まして、施工計画の説明会を実施いたしまして、おかしいところがあれば指摘するような形でやっている。","voiceIndex":291,"id":"exchange-116"},{"speaker":"伊藤委員","kind":"確認","question":"品川区の対応はわかりますけれども、３億円がマイナスになるということは、相当業者が負担を被っていると言ったらいいのでしょうか、やっぱりどこかでこのお金を浮かすといいましょうか、そうしないとできないわけだから、いろいろな問題点があるんだけれども、もう既に工事が始まっているので、大切なことは、展開されている工事の品質、それから、例えばコンクリートの材質なり。","respondent":"奥田河川下水道課長","answer":"資材などもちゃんと適正に確保できているか、あるいは、なぜこういう低廉な価格になっているかということも業者に確認いたしまして、ちゃんと資材購入もできているということで、業者から提出いただいたものをちゃんと確認して問題ないということを確認して工事を進めてあります。","voiceIndex":293,"id":"exchange-117"},{"speaker":"西本委員","kind":"質問","question":"私からは、まず初めに、歳入のところ全般に関してお聞きします。二つ目は、いろいろ質問がありました。なぜこんな状況になっているのか、うがって見てしまうと、積み上げられる何かそういう仕組みがあるのかな、どういう目的でこれはされているのかなということをお答えください。そうすると、半分来たということは、ニーズに合っていなかったのかな、これはどういう分析をされていますでしょうか。","respondent":"本城企画財政課長、品川木密整備担当課長","answer":"制度改正ということで一くくりになったものでは、障害者介護給付費の審査会について、法改正についてシステム改修になったとか、予防制度自体の関係で新しくなったものも含めて。現状のこういった理由としましては、一つの法人の方がビル一つを持っていればスムーズに進むんですが、分譲マンション等の場合ですと、なかなか管理組合の合意ができないとか、そういったことで途中でとまってしまうもの、それから。","voiceIndex":296,"id":"exchange-118"},{"speaker":"西本委員","kind":"質問・要望","question":"制度変更にということなんですが、要は、国の要因が大きいですよという認識でよろしいんですか。逆に気になっているところ、国と都の支出金がマイナスだというところ、これはどこかで補填されているので問題なく事業を展開できていますよという認識でいいのか、それをお聞きします。考えによっては。そうじゃないんだよということであれば、その理由をお答えいただきたい。","respondent":"本城企画財政課長、品川木密整備担当課長","answer":"中には制度によって補助金自体がなくなってしまって一般財源化されたものもありますが、ただ、社会資本整備の交付金について、防災関係に行きましたり、あるいは子ども関係で都と国のやりとりがあったりして。これからの手立てですが、東京都と区と連携しまして、郵送、それから電話等により啓発を１軒１軒行っていく予定です。","voiceIndex":299,"id":"exchange-119"},{"speaker":"若林委員","kind":"質問・要望","question":"そこで、予算立ての話になるかもしれませんけれども、国からのいわゆる支出金、都の支出金、そして区の一般財源、これをひっくるめた予算立ての考え方、予算の立て方、そして今回、このような追加分が出てきた、この関係性をまずはご説明いただきたいと思います。","respondent":"中山障害者福祉課長","answer":"今回こちらは自立支援サービスで追加になったところは、特に緊急一時保護といいまして、ショートステイの見込みがすごく需要が伸びたこと、そして、子どものところでは、療育の伸びが大きかったこと、それによりまして、今回。","voiceIndex":303,"id":"exchange-120"},{"speaker":"若林委員","kind":"質問・要望","question":"そうしますと、それぞれ国と一般財源の割合というのは、それぞれ違う、それぞれサービスかなと思うんですが、これはそれぞれ、例えば、２分の１、４分の１、４分の１で、それぞれ国からも補助がちゃんとしっかり下りている。都からの４分の１で下りている。さらに区の一般財源も４分の１という、その枠組みの中での追加分というふうに理解していいのかどうかお聞かせいただきたい。","respondent":"中山障害者福祉課長","answer":"この自立支援サービスと、それから児童福祉法に基づきます障害児施設給付費につきましては、一定の割合で、必ず東京都、国から負担金として来るものです。","voiceIndex":305,"id":"exchange-121"},{"speaker":"若林委員","kind":"質問・要望","question":"いわゆる一定の国の補助であれば、国はこれぐらいの一定の需要があって、あなたの３０何万の人口で障害のある方が何人いてという需要に対して、あなたの区はこのぐらいが上限ですよというふうに言うのか、それともこういうものを踏まえて、区として、実は国の一定の基準はあるけれども、区としてはこういう傾向性があるので、次年度の予算ではこういうふうに設定させていただきたい。","respondent":"中山障害者福祉課長","answer":"ただ、少なくとも平成２５年度よりも平成２６年度のほうがかなりサービス量としては増えるのではないかという見込みを立てまして、平成２６年度については予算要求しています。","voiceIndex":307,"id":"exchange-122"},{"speaker":"若林委員","kind":"質問・要望","question":"わかりました。それから、８７ページの区営住宅管理更正減額、午前中のご説明で、この１,１００万円がいわゆる打ち切り計上になっている。そこで、この耐震化ではなくて建て替えに変更した内容についての説明をしていただきたいのと、今後の建て替えの目的、また、その用途、例えば複合化等、これからどういうふうにお考えされ進められていくのかお聞かせいただきたいと思います。","respondent":"大串住宅担当課長","answer":"建て替えに向けては、来年度１年間、こういったことに関しての調査研究を行いまして、それ以降、順次、設計、建て替えといったところに進めていく予定です。","voiceIndex":309,"id":"exchange-123"},{"speaker":"若林委員","kind":"質問・要望","question":"加えて、いわゆる今、品川区では公共施設の有効活用プランでありますとか、中長期の改修計画、こういうところで、いわゆる施設の老朽化対策としての耐震化、それから、建て替え、こういうことが言われているわけですけれども、今回あえて中延一丁目区営住宅を耐震化ではなく、そういった観点、これまでの品川区のプランの中で耐震化をこの区営住宅にやっていたけれども、これからは建て替えに変更したと。","respondent":"大串住宅担当課長、品川木密整備担当課長","answer":"それを踏まえまして、平成２７年度から設計等々を進めていきたいというふうに考えております。私から少し補足をします。現在、東中延一丁目・二丁目、中延二丁目・三丁目で、木密１０年プロジェクト先行実施地区を進めてあります。この中で秋ごろに全軒訪問しまして、そこの中でこういうニーズが出てまいりました。","voiceIndex":311,"id":"exchange-124"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それともう一つなんですが、基金は繰入金が１４億円が繰り入れがなくなったと、そして積立金の追加分が５９ページ、８９ページで合わせると、３８億円ということで、これをたしか５２億円の基金が当初予算よりも余っているというか、増えているということで確認させていただいていいか、この２点、お願いします。","respondent":"本城企画財政課長","answer":"先ほどの最終補正段階で積立取り崩しがあった結果、当初との比較ですが、これは委員ご指摘のとおり、補正額として積み立てました３８億円、一般会計では３８億円、それと取り崩しが逆に１４億円減となりましたので。","voiceIndex":315,"id":"exchange-125"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基金残高は７０８億円余ということと、それから、当初予算よりも５２億円もの基金が余ったというか、増えているということで、本当にゆとりのある財政だということが改めて確認できるわけですけれども、基金の積立金の中で具体的にお聞かせいただきたいのは、義務教育の施設整備基金が、今回、１５億円積み増しして１３８億円余になっているわけですけれども、小中一貫校の建設も、それから。","respondent":"本城企画財政課長","answer":"基金の関係ですが、義務教育基金については、今回の補正でも積み立てておりますが、これは中長期的には学校施設の改築等が確実に見込まれますので、将来に備えた形で今回も基金を積み立てているところです。","voiceIndex":317,"id":"exchange-126"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"中長期的ということなんですが、中長期の具体的なところも教えていただきたいんですが、学校も一応耐震化が済んでいるとなれば、２０年後とか、そういうところも、２０年後のために積み増して基金としてためていくという、そういう考え方になるのか、また、それよりももっと前に具体的な需要とか、それぞれあるのか、将来の需要というのは。","respondent":"本城企画財政課長、齋藤庶務課長","answer":"それで、築４０年以上たっている公共施設はかなりたくさんあります。そういうものにつきましては、確実に改築需要が見込まれますので、これらについて確実な財政手当をするために基金を積み立てているものです。私どもとしては、安定的な財源があればあったほど、教育委員会としてはありがたいですので、目標値は私どもで申し上げる立場にはございませんけれども、今後、老朽度プラス就学人口の動向もありますので。","voiceIndex":319,"id":"exchange-127"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"次です。５２億円、当初予算より増えているということなんですけれども、私はやっぱり５２億円当初よりも余ったわけですから、その分、区民の切実な要望というのは、本当にたくさんあると思いますので、その切実な要望にこたえるべきではないかなと思っているんですが、そういう区民の切実な要望にこたえるという点では、どういう検討がされたのかということをひとつお聞かせいただきたいと思います。","respondent":"本城企画財政課長","answer":"それらを含めまして、今の財調を活用した緊急的な防災だとか子育て支援を含めて、今回の予算編成におきましても、重点的に区としては重点課題として位置づけて全力で予算上の対応もしています。","voiceIndex":322,"id":"exchange-128"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は、こういう補正予算の中でも、これだけ５２億円が当初よりも増えたという、そういう状況の中で、これを活用して緊急要望、特に待機児解消、私はここのところに緊急に充てるという対策をとるべきではないかと思うんですけれども、その点はいかがでしょうか。","respondent":"本城企画財政課長","answer":"今回の補正のタイミングに関して申し上げれば、今回新たに財源が出てきて、補正予算の中では、これから新たな、今回、プラスで出てきた財源を、この最終補正で新規の事業として活用していくというのは、時期的な問題としては難しい面もありますが、ただ。","voiceIndex":324,"id":"exchange-129"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そこの中で実際に８９４人と、９００人近い子どもたちが認可保育園に入れないという、こういう状況になったわけですから、今の時点で、４月に入れなかったら、仕事を続けられないというふうなことを切実に訴えているわけですか、ぜひここのところは何らかの形で区が責任を持った対応をぜひとも、お金もある、そういうふうなところで取り組みもしなければならないと。","respondent":"本城企画財政課長","answer":"繰り返しになりますけれども、今までの基金も含めて、この間の財政的な評価を基盤としまして、平成２５年度予算も、そして平成２６年度予算も子育て支援を再重点課題の一つとして明確に位置づけて予算の執行をしていくことを考えているものです。","voiceIndex":326,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問・要望","question":"２点お聞きしたいと思います。１点目は、４３ページ、８１ページ、９８ページに出ていますけれども、商店街電線類地中化事業について。それと２点目が７３ページ、生活保護費更正減額についてお聞きしたいと思います。一体いつ終わるのか、この終了予定と、なんでこんなにおくれているのか、今年度の減額の内容についてお聞かせいただきたいと思います。","respondent":"稲田道路課長","answer":"今後の予定なんですけれども、現在、５工区に分けて工事を進めておりまして、そのうちの残り３工区と５工区の２工区が残っております。この３工区というのは、こちらの役所側のほうの通りから行きますと、国道に出る手前の１街区のところです。","voiceIndex":329,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、平成２７年度完成と、ちょうど１０年ですよね。本当にお客様にとって迷惑な話だったなという気がいたします。５工区に分かれていると言いましたけれども、最初の計画では西品川のほうから１、２、３、４、５とやっていく。それが途中で飛んでしまいましたよね。これはどうしてなのかという思いがいたします。その辺のことについて、しっかりとお聞きしたいと思います。","respondent":"稲田道路課長","answer":"委員おっしゃられるように確かに連続ではやっておりません。１工区、戸越銀座銀六商店街のほうから着工したんですけれども、その後、飛んで、その次の工区まではつながったんですが、その後、国道から戸越銀座の駅までという形でやってまいりました。","voiceIndex":331,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問・要望","question":"時間がなくなってきたので短く行きます。あそこは２９号線用地なんですよ。２９号線が通るから工事しないのかななんて、まちから出ていますので、そんな意味では早急にやってもらいたい。工事をしているかげんで車が９時過ぎまで入れないんですよ。そんなような状況の中で、自転車の撤去、計画的にやっているんですけれども、これをしっかりやっていただきたいと、ここをひとつご意見を伺いたいと思います。","respondent":"稲田道路課長","answer":"脇道の工事につきましては、来年度、完成させる予定です。それと、今の自転車と車と、その辺の関係なんですけれども、現場をよく精査しまして、そのようなことがないように努力してまいりたいと思います。","voiceIndex":333,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"しっかりとやっていただきたいと思います。それと２点目の生活保護費の更正減額、３億７,８６２万１,０００円、生活扶助その他の扶助費が４億８,７８１万円減っています。この辺の絡みです。医療費の場合は、ジェネリック等々で品川区でも予算をつけてしっかりと話をしているということなので、ジェネリックの転換率というんですか、それもどのぐらいになっているのかということを聞きたいと思います。","respondent":"竹田生活福祉課長","answer":"医療費がなぜ増えたかですが、今年度１月末までに医療扶助を受けた受給者の数が、対前年同期費と比べまして、月平均９７件増えているためと考えております。","voiceIndex":335,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問・要望","question":"１％、予測よりも減ったということで、この辺もしっかりと精査していただきたいと思います。やはり医療費のほうもそんなに伸びていくというのはやっぱりおかしいので、ジェネリックをしっかりこれをやっていただければ、随分違いますので、このことをしっかりお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":337,"id":"exchange-135"},{"speaker":"井上委員","kind":"質問","question":"私からは、歳出のほう、７２ページ、民生費生活保護費の扶助費、同７２ページ、衛生費保健衛生費の予防費、それから８６ページの土木費の建築費、９０ページ、教育費の学校教育費の学校給食費についてお伺いいたします。それから、予防費のほうの予防接種費の更正減額１億５,３６０万円について、午前中の議論で、件数の減は報告がありましたけれども、金額についての減額の内訳をお伺いいたします。","respondent":"竹田生活福祉課長、品川木密整備担当課長、伊津野保健予防課長、和氣学務課長","answer":"８月以降ということですので、今年度につきましては、あと８カ月ということですので、８倍しまして。当初は見込みとして期間として間に合うのではないかなというふうに予算を組んでいたんですが、結局のところ、大分期間がかかったということで。予防接種の減額ですが、まず子宮頸がんにつきましては１億１５４万２,６５０円、不活化ポリオにつきましては１,９９１万１,６００円。給食室の空調機設置工事については、これも順次、それぞれないところを順番に設置しているところでございまして。","voiceIndex":339,"id":"exchange-136"},{"speaker":"井上委員","kind":"質問","question":"厚労省は勧奨再開を目指しているようですが、私はこれ以上被害者が増えるということのないように、接種中止になることを望んでいるという前提で質問していきますけれども、品川区は以前、接種後に失神したという報告が１件あるということでしたが、その後、別の報告がありましたでしょうか。","respondent":"伊津野保健予防課長","answer":"それ以降は特に報告はございません。","voiceIndex":344,"id":"exchange-137"},{"speaker":"井上委員","kind":"質問","question":"関連して教育委員会に伺います。文部科学省が昨年の６月から７月に、全国の中学校、高等学校、特別支援学校、計１万６,７００校を対象に、２０１２年の１年間、ワクチン接種に関連した症状で３０日以上欠席、３０日以上、体育の授業または部活を休んだ、一定期間、教育活動に何らかの制限が生じた生徒を調査しております。品川区はどのように対応されて、結果をどのように報告されたのかお伺いいたします。","respondent":"和氣学務課長","answer":"学校からの報告経過ですが、品川区は該当はございませんでした。","voiceIndex":346,"id":"exchange-138"},{"speaker":"井上委員","kind":"質問","question":"それからもう一つ、東京新聞のほうでも、副作用の症状の訴えが、今、品川区でも１件もなかったという報告をされたということなんですけれども、２０１０年から任意接種が始まったにもかかわらず、調査対象としては２０１２年１年間に限った調査でしかなかったということで、それ以前に症状が出た方たちの調査がなかったということ、それで、初回の接種だけではなくて。","respondent":"伊津野保健予防課長","answer":"済みません、細かい数字は今お持ちしておりませんが、平成２４年度で、全部の数字で４,０００件と把握しております。ですから、初回接種ですから、それの約３分の１と考えます。","voiceIndex":348,"id":"exchange-139"},{"speaker":"井上委員","kind":"質問","question":"厚労省の言うところには、思春期の心因によるものの影響であるというような根拠のない指摘もあるわけですけれども、実際にそういった方たちの調査を品川区として独自にお願いしたいというふうに思いますけれども、保健予防課のほうではどのようにお考えでしょうか。","respondent":"伊津野保健予防課長","answer":"子宮頸がんの副反応につきましては、国のほうでも調査しておりますので、専門家の調査を待って、結論は待ちたいというふうに考えております。","voiceIndex":350,"id":"exchange-140"},{"speaker":"井上委員","kind":"質問・要望","question":"それで、もし４,９００名ぐらいのお子さんに対して単純に郵送してそういった調査をするということであれば、そんなに高額な予算はかからずにできるかというふうに思います。ですから、ぜひ考えていただきたいというふうに思いますが、先ほど、国がやっていくということでしたけれども、品川区ができない理由はないかというふうに思いますが、いかがでしょうか。","respondent":"伊津野保健予防課長","answer":"子宮頸がんワクチンにつきましては、確かに痛みが強いワクチンでありますので、調査をかければ多少なりの反応があったという回答はあるかと思います。","voiceIndex":352,"id":"exchange-141"},{"speaker":"井上委員","kind":"質問・要望","question":"こういった副作用のものについても、いろいろと出されているんですが、ぜひ品川区が今受けて、本当に隠れた症状を持たれている方がいるかどうかということを把握して、なかったらないでそれでちゃんと国にも意見が言っていけると思いますので、ぜひ対処していただきたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":354,"id":"exchange-142"},{"speaker":"浅野委員","kind":"質問","question":"中身につきましては、特定健診のほうが約１２％の減、保健指導に至っては５５％というぐらいの減だったと思いますが、このような減になったことについて、どのように区は認識していくのかということについてひとつお伺いしたいのと、平成２４年度も調べてみたんですけれども、特定健診はマイナス６％ぐらいで、やっぱり保健指導のほうが６割近くの減だったと思います。","respondent":"間部国保医療年金課長","answer":"保健指導につきましては１４.４％ということです。今現在、平成２５年度の実施状況ですが、特定健診については４０.１％から比較しますと、大体二、三ポイント減という形で推移しています。保健指導につきましても同様の減です。","voiceIndex":356,"id":"exchange-143"},{"speaker":"浅野委員","kind":"質問","question":"少しずつ平成２５年度のほうがよくなってきているということでありますけれども、やはり率としてはまだまだ考えていかなければならない。これはしっかりとフォローしていく必要があると考えています。この点について、今後どのような形で取り組んでいくのか教えてください。","respondent":"間部国保医療年金課長","answer":"こういう取り組みを始めていますので、まだまだなかなか数字は伸びていないんですが、だんだん効果が出てくるものだと考えておりますので、もうしばらくお待ちいただきたいなと思ってあります。","voiceIndex":358,"id":"exchange-144"},{"speaker":"浅野委員","kind":"提案","question":"こちちからの提案になりますけれども、代表質問の中でもコール・リコールということで、がん健診の例をとって出させていただきましたが、コールは健診を送るということでできていると思いますし、また、リコールについても、さまざまこういう広報ですとかやっているとは思いますけれども、直接届けるような、電話は難しいかもしれませんけれども、再度郵送ですとか。","respondent":"間部国保医療年金課長","answer":"そういった効果も含めまして、新たな、先ほども言いましたけれども、今、４５％の方が一切受診していない状況の中で、そういった心に響くようなフレーズを入れてみたりだとか、あとは、例えばまちなかで気軽に健診を受けられるようなことの検討を始めてみたらいいのかなと。","voiceIndex":360,"id":"exchange-145"},{"speaker":"浅野委員","kind":"意見","question":"なかなかデータを共有するということは非常に難しいと思いますし、また、医師会にそのデータを出すということになると、さらに難しいのかなと思いながら、このような取り組みも調査研究をしながら、今後とも特定健康診査、保健指導については力を入れていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":362,"id":"exchange-146"},{"speaker":"須藤委員","kind":"質問","question":"５２ページから５３ページの寄附金についてお尋ねします。それから、特別養護老人ホーム等整備で、特別養護老人ホームの整備で１,０００万円、それから重症心身障害者で５０万円というような数字が出ているけれども、この分け方は、１,０００万円と５０万円というのは随分極端に、１,０５０万２,０００円の寄附については、分け方なんだけれども、その辺の理由がなにかあるのかどうか教えてください。","respondent":"本城企画財政課長","answer":"予算の５２ページ、５３ページの記載の関係ですが、指定寄附金ということで、特別養護老人ホーム等整備ということを、以下、項目については財源更正ということで、寄附をいただいた部分をこちらの経費に充当しているということで、これに対応した歳出を新たに補正はしていない。","voiceIndex":364,"id":"exchange-147"},{"speaker":"須藤委員","kind":"意見","question":"先ほど来、お話があったように、一般会計に寄附して、減額補正をしましたというもののその次の減額補正したお金には色はついていないので、どう使っていくかわからないんだけれども、先ほど来、地域振興基金みたいな基金に入れているのか、そのあたりはどうなっているのかお聞かせください。","respondent":"本城企画財政課長","answer":"今の５２ページ、５３ページの財源更正と記述があるものにつきましては、特にこの部分、基金に積み立てているとかということではなくて、財源の内訳として、寄附も充当しながら特別養護老人ホーム等整備について活用しているという、そういう位置づけです。","voiceIndex":366,"id":"exchange-148"},{"speaker":"須藤委員","kind":"質問","question":"なおかつその部分が、行政とすれば一般会計が出さないで済んでいる分だから、ほかにまた区民の中に使えるような基金として、先ほど来、地域振興基金でもいいだろうし、ほかのいろいろ云々だとか、そういうこともいいだろうと思うんですけれども、何かそういう一般財源に戻して、また一般財源で使ってしまうという仕組みではなくて、何か考えたほうがいいと思うんですけれども、いかがでしょうか。","respondent":"桑村企画部長","answer":"そういう意味で、繰越金という形になりますので、この使い方については寄附された方、あるいは議会等でご理解いただけるような仕組みについて検討してまいりたいというように思います。","voiceIndex":368,"id":"exchange-149"},{"speaker":"須藤委員","kind":"質問・要望","question":"７３ページの休日・応急診療費追加分というのがありますけれども、休日診療費で追加というのは、休日診療については日にちで全部経費が決まってくるんだけれども、この追加というのは、特に何か大変な事業、インフルエンザがあったりとか、何かそういうことで追加をしたような仕組みでつくられたのかどうか教えてください。","respondent":"江部健康課長","answer":"休日診療の追加分につきましては、例年１２月から３月ぐらいの冬季期間に、やはりインフルエンザ等の流行期に受診する数が多くなるということから、通常配置している班数に、医師と看護師と事務で１班というふうな呼び方をしておりますが、１班追加するという形で、約１０日分。","voiceIndex":370,"id":"exchange-150"},{"speaker":"須藤委員","kind":"質問","question":"そのためにたいへんな状況になっているんだから、それならあらかじめきちんとその体制を組むようにしておいてやっていいと思うんだけれども、終わって大変だったからこうしてくれというような仕組みは、医師会でもこちらもなかなか言いにくいと思うので、むしろこういう状況ではこういうふうにしておきますよという体制をとっておいてあげたほうがいいと思うんですけれども、いかがでしょうか。","respondent":"江部健康課長","answer":"平成２１年度は大幅な件数が出ましたけれども、その後、おさまっているということがありますので、補正という形で、その不足分につきましては、医療現場の患者の数字について連絡を取り合いまして、追加したほうがいいだろうという確認をとりながら、その都度、その都度。","voiceIndex":372,"id":"exchange-151"},{"speaker":"須藤委員","kind":"質問・要望","question":"区民の皆さんが万が一のときに安心して医療ができるように、また医師会とか薬剤師会の人たちが万全な体制がとれる仕組み、一々区のほうへこういう状況だからお願いしますみたいな話をしていたら、なかなかそれがスムーズにいかないと思うので、あらかじめ行政のほうでこういう状況のときはそれなりの手当てをしてくれというような、看護師をつけてくれないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":374,"id":"exchange-152"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、１４８ページの介護給付費等準備基金積立金について伺いたいと思います。保険料も改められますけれども、まず第５期の現状を聞かせていただきたいと思います。第５期の初め、もう平成２３年度末の平均残高、平成２４年、平成２５年、平均２６年と、取り崩しや積み増し額はそれぞれどのくらい、そして３年の合計と、第５期最後の基金残高をお願いします。","respondent":"永尾高齢者福祉課長","answer":"取り崩しにつきましては、平成２４年度が４億３,０００万円、平成２５年度が２億２,０１８万４,４２３円、平成２６年度は、こちらは補正の額になっておりますけれども、１億９,２５１万９,０００円となっております。","voiceIndex":376,"id":"exchange-153"},{"speaker":"石田（ち）委員","kind":"質問","question":"でも、それが今言っていただいたように、最後の基金残高が見込みで１６億５,０００万円余ということで、これだけ基金残高が８億円余と言っていたものが１６億５,０００万円になっていくという、この余裕の基金ということで、第４期のときも、そして今答えていただいた第５期のときも、当初の取り崩しや基金残高が、これだけ取り崩しますと言っておきながら。","respondent":"永尾高齢者福祉課長","answer":"その年度年度で実情はあるんですけれども、平成２５年度で行きますと、実際の給付費の伸びが６％で見込んでいたのが、実際には４％だったというところでの差が出ているというところです。ただ、それは各年度によって多少原因が違ってくるかというふうに考えております。","voiceIndex":378,"id":"exchange-154"},{"speaker":"石田（ち）委員","kind":"質問","question":"それで、国のほうでも、第１号保険料の低所得者向け軽減の見直し案として、第一段階と第二段階は、保険料基準額５０％を３０％に、第三段階は７５％を７０％に引き下げるというふうに言っています。特例第四段階も１００％から引き下げることができますということで、自治体の保険料に対しての役割というのは本当に大きなものがあると思うんですけれども、その辺をどうお考えでしょうか。","respondent":"永尾高齢者福祉課長","answer":"現在、用意されている低所得者の軽減の件につきましては、これから国のほうでの結論が出た段階で、そのほかの見直しも出ておりますので、総合的に判断して、この準備基金をどう活用するか考えていきたいというふうに思っております。","voiceIndex":380,"id":"exchange-155"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひともこれだけしっかりある基金を保険料の軽減、また利用料の減免に使っていただきたいなと思います。特養ホームだけが保険料を上げる原因にはなっていないのではないかと思うんですけれども、この運営状況の中でも、特定施設の給付費合計を平成２５年度、平成２２年、平成２３年、平成２４年はもう出ているんですけれども、平成２５年度のものを教えていただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"平成２５年度決算の見込みですけれども、２９億１,０００万円余というふうに今試算しています。","voiceIndex":382,"id":"exchange-156"},{"speaker":"石田（ち）委員","kind":"質問","question":"１万６,０００件、これは特定施設だけで。それで、介護報酬についてもちょっと伺いたいんですけれども、要介護５で、収入は年金の満額の場合で、特定施設と新型特養を利用した場合の介護報酬について伺いたいんです。","respondent":"永尾高齢者福祉課長","answer":"特別養護老人ホーム個室ユニットの場合は、１万２３７円なんですけれども、個室ユニットの場合に、特養の場合はさらに加算が、それぞれ施設によってついてきますので、もう少し高い金額になるかと考えています。","voiceIndex":386,"id":"exchange-157"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これから介護の大改悪が進んでいくと言われていますけれども、こういったしっかりと基金を使って、そして介護難民がこのままだと本当にあふれてくると思うんですね。ですので、しっかりとこの基金を使って、そして利用料を下げて、しっかりとしたサービスを提供するということを強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":388,"id":"exchange-158"},{"speaker":"須貝委員","kind":"質問","question":"総務費全般からお聞かせ願いたいと思います。人事課だと思うんですが、共済企画センター寄附金というのがあるんですが、これは何なんでしょうか。毎年あるのか、なぜあるのか。これは同じく富岡町、宮古市にもそういうふうにしているのでしょうか。この中でお聞きしたいのは、基金の利子です。これだけの額が違うというのは、なぜなのかなとちょっと疑問を感じたので教えてください。","respondent":"堀越人事課長、工藤総務課長、久保田会計管理者","answer":"今回、４６９万１,０００円という、平成２４年度も４００万円、平成２３年度２００万円という形で。そういった中で、１４日から１５日にかけての突然の大雪だというところで、全町民が孤立状況に陥ったということで。利子にかかわるご質問ですけれども、この利子及び配当金は、いわゆる基金の中の運用として、国債等を購入しておりますので、それの購入時に。","voiceIndex":390,"id":"exchange-159"},{"speaker":"須貝委員","kind":"質問","question":"今、先に利子のほうなんですが、国債とか何かそういう運用をしていれば、私はあらかじめわかるんじゃないか。当初予算で３５０万円が５０４万円になるというのは、ちょっとこれ、大雑把な当初予算、見積もりなのかなと、それは質問ではなく意見だけ言わせていただきます。そして、先ほどの早川町への見舞金ですが、大変なのは、宮古市、富岡町ですよね。これは区民から皆さんから集めたお金。区の考え方です。","respondent":"工藤総務課長","answer":"そういった意味では、被害のほうも、先ほど申し上げましたように、全町民６６８世帯、１,１８３人が孤立状況に陥っているという状況の中で、やはり義援金等という部分ですと、やはり時間がかかると、そういった暇がないということで。","voiceIndex":394,"id":"exchange-160"},{"speaker":"須貝委員","kind":"質問","question":"今のお話、孤立したらお金使えないですよね。それから、４４ページ、教育費補助金について、地域の元気臨時交付金９,７９０万円、充当事業は小学校と中学校の校舎等整備になっていますが、これはどこの学校の何の工事でしょうか。教えてください。","respondent":"齋藤庶務課長","answer":"地域の元気臨時交付金につきましては、平成２４年、国の１兆４,０００億円の特別な交付金ができまして、地方の公共事業の軽減を図るということで設置されたものです。今回のものは、学校のトイレの改修です。三木小学校、東海中学校、冨士見台中学校になります。","voiceIndex":396,"id":"exchange-161"},{"speaker":"須貝委員","kind":"質問","question":"これらの学校、校舎等の整備ですが、これはもともと当初予算では全く載っていなかったんですか。そして、このたび、なぜ地域の元気臨時交付金を充てたのかお聞かせください。","respondent":"齋藤庶務課長","answer":"その実施計画に従ってどのようなものに充てられるかということで、教育委員会のほうでは、トイレが当たるのではないかということでお示しして、国から補助金を取り出したというものです。","voiceIndex":398,"id":"exchange-162"},{"speaker":"須貝委員","kind":"意見","question":"当初予算からそういう事業が載っていたということなら、区議会において予算審議の上、議決して一般財源で事業を執行するということが建前になっていたと思うんですね。それが１点。でも、本来は国から地域経済活性化雇用創出臨時交付金ということを国民にきちっと言って訴えているわけですけれども、その辺についておかしいんじゃないかなと思うんですが、ご見解をお聞かせください。","respondent":"本城企画財政課長","answer":"こちらにつきましては、当初予算の段階でこちらの学校についてのトイレ改修の事業の計画自体はあって、当初予算の段階では、国の補助金のみを活用する予定で事業の財源を含めて予算をつくらせていただいたところですが、その後になりまして。","voiceIndex":400,"id":"exchange-163"},{"speaker":"須貝委員","kind":"質問","question":"ならば、区が、それぞれの自治体が、こういうふうに使ってしまっているんですと、使っちゃうんですということは、心情的に、国民感情的に許されるのか、理解してもらえるのかなということも、やはりこれだけ立派な品川区、健全財政の品川区も考えていかないとまずいんじゃないかと思うんですが、いかがでしょうか。","respondent":"本城企画財政課長","answer":"こちらの補正の対応といたしましては、最終補正ということで、今回新たに財源の形で出てきたものですが、ただ、もともとこの地域の元気臨時交付金につきましては、さきの国の緊急経済対策の中でさまざまな事業を打ち出した中で。","voiceIndex":402,"id":"exchange-164"},{"speaker":"須貝委員","kind":"質問","question":"企画が頑張っているのはわかるんですが、ただ、新聞、これの報道等で、やはりいろいろ言われているじゃないですか。それから、先ほど、契約落差、例えば土木費なんかは２９億円減になりました。そして、実際、事業費というものが出ておりましたが、これだけ大きな落差がある。最初からポンと出して、はい、残りました。ですが、そういうところも考えなければいけないと思うんですが、簡単に一言、言えますか。","respondent":"本城企画財政課長","answer":"今のご意見に対してですが、予算につきましては、あくまでも適正な規模を見込んで合理的に作成し、その結果、きちんと執行した余りを可能な限り十分に使っていくという形で考えております。","voiceIndex":404,"id":"exchange-165"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ご答弁のほど、よろしくお願いします。これは結果であって、要因がもしわかるのであれば、教えていただきたい。少なくなるのはいいと思うので、要因を教えていただきたいということと、その減の中身で、新たに生活扶助を受ける人が予想よりは減ったのか、それとも今受けている人が生活保護から取り下げたというんですか、もしその数字がわかれば教えていただきたいと思います。","respondent":"竹田生活福祉課長","answer":"ジェネリックのところですけれども、ちょっと数字でご説明しますと、この取り組みを始めた平成２４年７月は、普及率は、当時、５.６９％でございました。","voiceIndex":407,"id":"exchange-166"},{"speaker":"いながわ委員","kind":"質問・要望","question":"先ほど、医療費が増えている、高齢者が多いということでございました。ありがとうございました。次、８１ページの都市計画道路なんですが、１６３号線に関して、東急の高架下、大井町線の交差部整備ということで、軒並み減額をされているということは、平成２５年度、こういった事業をやられていないという判断でよろしいのでしょうか。やらなかった理由を教えてください。","respondent":"稲田道路課長","answer":"この下に書いてあります事業認可取得、測量委託ですが、こちらにおきましては、東急電鉄が耐震補強工事を実施するというところで、平成２４年夏ごろに通知がございまして、私ども、東急電鉄の耐震工事とガード架け替え、非常に大きな工事でございまして。","voiceIndex":409,"id":"exchange-167"},{"speaker":"いながわ委員","kind":"質問・要望","question":"相手がいることなので、なかなか調整するのは難しいということでありますが、相手も相手で企業ですので、長期的ないろいろな部分で計画を立てていると思いますので、それにしっかり乗って、予定どおり行くようにしっかりと、道路課長のお話の中で、平成２６年度中には事業認可ということなので、これはしっかりと調整してやっていただきたいと思います。","respondent":"稲田道路課長","answer":"こちらの道路バリアフリー事業におきましての２,０００万円の減額です。これは大井三丁目１４番先の道路バリアフリーの改修工事です。こちらは、延長が２４０ｍありまして、歩道がついている道路です。","voiceIndex":411,"id":"exchange-168"},{"speaker":"いながわ委員","kind":"質問","question":"耐震のところで１点だけお聞かせください。先ほど、特定輸送道路のところが減額になったということなんですが、それに対しての診断助成の１００棟というのは減額されていないです、これはやったということでよろしいでしょうか。","respondent":"品川木密整備担当課長","answer":"診断については、おおむね件数どおり行っているというふうに考えております。","voiceIndex":413,"id":"exchange-169"},{"speaker":"たけうち委員","kind":"質問","question":"７８ページの産業経済費につきましては、この４月からいよいよ消費税が８％ということで、さまざま国のほうでも補正予算が成立しまして、また、今回の今日の審議の中でも、例えば低所得者対策としては臨時福祉給付金、また子育て世帯への対応としては臨時特例給付金ということで、それぞれシステム改修の費用が補正予算で盛り込まれておりまして。","respondent":"山崎ものづくり・経営支援課長、藤田都市計画課長","answer":"つきましては、３月にそうした国のほうと連携をしまして、区内中小企業を集めてそうした合同の説明会も予定しておりまして、そういう意味では、国は国のメニュー、それから区は区のメニューということで。このため、２回の開催予定が１回になってしまいましたが、補正による変更は行っていないです。","voiceIndex":416,"id":"exchange-170"},{"speaker":"たけうち委員","kind":"質問・要望","question":"ただ、ものづくり・経営支援課長がおっしゃったように、３月１３日ですか、ホームページに出ておりますけれども、中小企業の方たちにお知らせをして、平成２５年度の補正予算と平成２６年度の国のほうの予算の概要説明会とか、また、さまざまな申請書の書き方等をやっていただけるという非常にいいことだと思いますけれども、ただ、なかなかあのホームページを見る方は少ないのではないかなと思うので。","respondent":"山崎ものづくり・経営支援課長","answer":"消費税の関係につきましては、現在、既存の経営相談の窓口で、消費税の相談は随時受け付けているようなことで、日ごろはそういった対応をさせていただいています。","voiceIndex":419,"id":"exchange-171"},{"speaker":"たけうち委員","kind":"質問・要望","question":"本当に区としては直接的に補正予算で何か対応するというものではないと思うんですけれども、既にやっていただいているとおり、本当に国のほうではかなりさまざまな形の対応が出てきていますので、これはぜひ品川区内の中小企業の方、商店の方も含めて、ご相談に行ったときには、ぜひその窓口の方が、区としてはこれをやっているけれども、国のほうはちょっとわかりませんでは困ってしまうわけなので。","respondent":"山崎ものづくり・経営支援課長","answer":"したがいまして、私ども区の職員としまして、そうしたことをきっちり理解した窓口の対応とともに、同時に、商工相談部の専門の方々にもそうした趣旨を十分やりとりをしまして、万全な対応で本件については臨んでまいりたいというふうに考えてあります。","voiceIndex":421,"id":"exchange-172"},{"speaker":"渡辺委員","kind":"質問","question":"お願いします。５６ページの雑入の雑入が１点と、８５ページ、しながわ区民公園中央ゾーン整備基本設計の２点を伺います。右のところでの公園駐車場の事業納付金ということで、大きな内訳というんですか、特殊な事情というか、割合が多かった事情などがわかれば教えてください。","respondent":"本城企画財政課長、多並公園課長","answer":"雑入の件ですが、大きな増額、変更項目といたしましては、鮫洲入江広場の協定見直しによる増が１,５００万円余、それから特別区の厚生事務組合分担金の過年度の還付金についてが９７０万円余ということで。私からは、しながわ区民公園の設計の減額についての理由です。理由といたしましては、４２８万３,０００円の減額は、契約落差によるものです。","voiceIndex":424,"id":"exchange-173"},{"speaker":"渡辺委員","kind":"質問","question":"もう１点、区民公園のところなんですが、内容のところ、補正ですから、今年平成２５年で基本設計はほぼ見通しがつき、次年度に向かっていくと思うんですが、内容のところで、どういう変化、当初から各委員会でも指摘させていただいたと思いますが、中央に限らず、ゾーン別であり、連動して全体的な一体的な、区民公園全体のデザインの必要性というのは、議会からも主張していましたし。","respondent":"多並公園課長","answer":"その中では、業者からは、平日等、休日も含め、１日最大料金を上げる等、そこら辺の対応で行っていきたいということで、今、提案を受けて、推移を見守っているところです。もう１点の区民公園の件ですが、全体的に昭和５８年から開園してからもう３２年以上がたっている状況です。","voiceIndex":427,"id":"exchange-174"},{"speaker":"渡辺委員","kind":"提案","question":"公園の駐車場のところはわかりました。ぜひいろいろご検討、提案を見守りたいと思います。それは２５年前のときの区民ニーズと今が変わっていないということになってしまうのか。僕は絶対に大きな変化があるし、防災の役割も踏まえて、大きな公園、広い面積にしかできないことを最優先にすべきと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"しながわ区民公園の整備の方針ですが、今、委員のお話のとおり、ここのしながわ区民公園は唯一の総合公園です。そういう点では、ここでしかできないことを、また、広域避難場所に指定されている点では、一番考慮しなければいけない点だと考えています。","voiceIndex":429,"id":"exchange-175"},{"speaker":"渡辺委員","kind":"質問","question":"タイムスケジュールを聞かせてください。これは補正も含めて、基本設計が一つ含みになります。今、平場というお話がありました。区民公園が全区的な財産という考え方であれば、近隣には中規模の公園が幾つかありますので、そことの連動、転用も含めて整備されたらいいと思いますが、いかがでしょうか。","respondent":"多並公園課長","answer":"来年度以降、平成２６年度、予定ではクラブハウスの工事を行い、平成２７年度にはプールの工事を行い、その後、公園の下水道の復旧工事にあわせて、公園本体のほうの中央ゾーンの整備というところを全体的に考えているところです。","voiceIndex":431,"id":"exchange-176"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1000#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":127503,"voices":435}},{"id":"h26-20140304-3","meetingId":"h26-c-budget","date":"2014年3月4日","dateIso":"2014-03-04","committee":"予算特別委員会","time":"午前１０時００分～午後５時５１分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を169件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２６年度品川区一般会計予算","agenda":"平成２６年度品川区一般会計予算","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"おはようあります。７２ページの自転車駐車場使用料、それから８６ページの臨時福祉給付金補助金、子育て世帯臨時特例給付金補助金、それから歳入を増やすという観点で、区有地の有効活用で、３つお伺いします。時間があったら、歴史館使用料についてお伺いします。そしてシステム開発にも予算がかかるという話が昨日もありました。","respondent":"福島臨時給付金担当課長","answer":"職員体制ですが、基本的には私ども青少年育成課のほうで行いますけれども、こちらは全庁体制をとりたいと考えておりますので、現在のところ、臨時給付金実施本部というようなものを設置しまして、全庁を挙げて取り組んでいくということを考えております。","voiceIndex":4,"id":"exchange-001"},{"speaker":"沢田委員","kind":"質問","question":"改めて、申請による受付のことなのですけれども、申請で受け付けるということでしたけれども、以前も子ども手当等の申請のときに、申請に来られない方が結構いらしたかと思うのですけれども、未申請の方に対する対応というか、そういったことについて、１２月中旬まで受け付けるということでしたけれども、こちらから、そういったことがないように、せっかく国がこういった制度をするということですので。","respondent":"福島臨時給付金担当課長","answer":"なかなか高齢者の方で難しいという方もいらっしゃると思いますので、例えば民生委員協議会ですとか、高齢者クラブですとか、そういったところを通じまして周知を図りたいと考えています。","voiceIndex":6,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"駐輪場の使用料のことでお伺いしたいと思いますけれども、これはちょっと、１点だけなのですけれど、以前からもずっと駐輪場の件はいろいろと話が出ていますけれども、駐輪場が足りないというか、駐輪場は増えてきていると思うのですが、機械式の地下駐輪場のことで、以前もいろいろ技術的な部分での、まだなかなか難しいんじゃないかという話もありました。これからのことでお聞かせいただければと。","respondent":"谷口交通安全担当課長","answer":"品川区としましても、全く視野に入れていないわけではなくて、まちづくり、また再開発の中でそういう機会があれば、駐輪場も視野に入れながら進めていきたいと考えるところです。","voiceIndex":11,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"これは、これだけで終わらせていただきます。売電して年間４００万円の収益を見込んでいるという報道でしたけれども、こういったことを品川区としても考えられないのかなと思って、ちょっとお伺いさせていただきたいのですけれども、どうでしょうか。","respondent":"平澤経理課長","answer":"この２つのハードルをどういうふうにしていくかというのが大きな課題でございまして、委員ご提案の趣旨も含めまして、考えて、研究するということになると思いますが、当面、売却によっては、ここは検討していきたいと思っているところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"沢田委員","kind":"提案","question":"ぜひとも考えていただきたいと思います。ちょっと、あと時間が中途半端なんですけれども、歴史館使用料で１点だけちょっと確認させていただきたいと思います。歴史館が改築中でありますけども、茶室の使用料は消えておりますけれども、今後の、また改めて茶室のあり方というか、何度もお伺いさせていただいているのですけども、このことについて１点だけご確認させてください。明日、続きは総務費で。","respondent":"安藤文化スポーツ振興課長","answer":"歴史館の茶室ですけれど、茶室は、やはりもう、昭和初期に建てられまして、八十有余年、経過しています。そして、ここのところ、中の改修をしながら、文化活動をしてまいりました。しかし、最近、傷みがひどくなってあります。","voiceIndex":15,"id":"exchange-005"},{"speaker":"つる委員","kind":"提案","question":"税外収入という観点でも、議会からもさまざまな提案を、私もさまざまな提案をしてまいりました。そうして見れば、さまざまな資金調達の方法を模索していく必要があるのではないかなという視点で、問題意識で、質問させていただきたいと思うのですが、まずその観点で、品川区への寄附をしていただいている方の世代というのは、大体どのあたりの世代の方がいらっしゃるのか、わかればお願いします。","respondent":"寺嶋協働・国際担当課長","answer":"実際、寄附をいただいているときに、お名前、住所、普通、年齢等までは大体聞くのですけど、正式な数字としての統計は持っていないのですけれども、大体、基本的には、お見受けしたところですと、社会人の方、それから年配の方が多いので、おおむね３０代から。","voiceIndex":18,"id":"exchange-006"},{"speaker":"つる委員","kind":"提案","question":"これの活用について提案をしたいと思います。その内容によって、対価を求めない寄附型、対価として物やサービスを渡す購入型、対価として金銭を渡す投資型などがあると言われております。このような流れが大きな流れの１つの例えであります。設定についてはさまざま、サイトによってもできるのですが、まずここまでの段階でクラウドファンディングについてお考えをお聞かせください。","respondent":"寺嶋協働・国際担当課長","answer":"ただいま、委員のほうから新しいご提案をいただきました点につきましてですけれども、今の段階では、その手法についてさまざま検討している中、具体的な検討は入っていないのですけれども、考え方といたしましては、区の一応。","voiceIndex":20,"id":"exchange-007"},{"speaker":"つる委員","kind":"提案","question":"協働の観点で、長計の中も含めて活用できるのかどうか研究ということでありました。これは先般、自民党の渡辺委員のほうからも、なかなか寄附文化が日本では定着していないよというお話も、かつて決算だったでしょうか、あったと思いますが、アメリカとか、億を超えるプロジェクト。過日、オリンピック・パラリンピックに絡めて基金の創設等々ということが議会のほうからも提案をされた。","respondent":"寺嶋協働・国際担当課長","answer":"ただいまの委員のご提案ですけれども、世代という観点から見ますと、ネット等を活用したものということであれば、やはり若い世代等に普及する可能性があるというところは十分認識しております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"つる委員","kind":"意見","question":"ぜひ積極的に、使える資金調達法かなとは思います。５０ページ、３９９ページの地方消費税交付金であります。その上で、この一覧は総務省から示されているフォーマットを参考につくられたと思うのですが、この、まず配分の考え方と、それから５０ページの１３億円と、この３９９ページで言うところの１１億２千万円の、これは率改定によるものだと思うのですけれども、改めてご説明いただければと思います。","respondent":"本城企画財政課長","answer":"その間に、全国的な配分等のタイムラグが生じますので、消費税の改定を反映させたものは、なかなか現実に測定するのは難しいところがありますが、一応、国のほうの推計で、今回の反映分として。","voiceIndex":24,"id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"特段どこかを厚くしようとしながらも、この辺でやったということじゃないのかなと、今、ご説明で理解しましたけれども、どうでしょうか。お答えください。大くくりで見ちゃうと、これは人件費も入っているんじゃないかと、見る人によっては勘違いすると思うのですが、その辺までの説明というのは、国のほうから言われていないと思うのですが、一応これは確認したいなと思うんです。","respondent":"本城企画財政課長","answer":"予算等の記載とともに、これからホームページ等についても同様のＰＲをしていく形を考えているところです。","voiceIndex":26,"id":"exchange-010"},{"speaker":"つる委員","kind":"意見","question":"大きい話題としては、社会保障４経費を含め、そうしたものをやめていくよということは報道されていて、これから詳細で出てくると、何か人件費のことに使っているのではないのかと、見る人によっては、そういう方もいると思うので、その辺を、例えば１文を、そういうふうになっていませんとかという、国から出てきている文章を引用するとか、そういう形で明示するだけでも大分違うのかなと思いますので。","respondent":"本城企画財政課長","answer":"今、ご説明があったものも含めて、今回の趣旨が、置きかえがどのような使い途になっているのかを、人件費の除外も含めて明示する形で、わかりやすくＰＲしていきたいと考えております。","voiceIndex":28,"id":"exchange-011"},{"speaker":"向委員","kind":"質問","question":"各地域センター、文化センター、野球場、体育館とか、いろいろありますけれども、そういった区有施設において、けがをしたりとか、救急搬送されたりとか、そういった件数、データ、どのくらいあるのかなというのと、あとＡＥＤについてなのですけれども、主な設置箇所、ホームページにもざっと載ってはいましたが、件数をまとめてお伺いしたいのと、年間、ＡＥＤはどのぐらい区有施設で使われているのか。","respondent":"久保田地域活動課長、江部健康課長","answer":"ＡＥＤについてですけれども、基本的には地域センターのほうに設置はされてありますので、地域センターが開館している期間であれば、そういったものをご利用することもできますし、例えばＡＥＤについては。ＡＥＤの設置総件数のお尋ねについてお答えいたしますが、現在、区の全施設１９３カ所で２１０台です。","voiceIndex":31,"id":"exchange-012"},{"speaker":"向委員","kind":"質問","question":"ちょっと、使用頻度もわかれば後で教えてください。２１０台あるということで、この中で、そこはＡＥＤが置いてあると、ＡＥＤの除細動器というイメージなのですが、プラスで、応急セット、これも一緒に設置されているのかというのもお尋ねしたいと思います。けがをすると、何かしら出血があったり、そういったことも予想されると思います。そのあたりのセット状況もあわせてお伺いしたいと思います。","respondent":"江部健康課長","answer":"使用したという報告があります。それから、応急キットにつきましては、現在１７０台ぐらいは、もうリースに切り替えておりますが、その機械の中に入っておりまして、手袋とかタオルとかはさみとか、そういったセットは設置済み、備品については設置済みです。","voiceIndex":34,"id":"exchange-013"},{"speaker":"向委員","kind":"質問・要望","question":"わかりました。ほかの区有施設にもそういったところがもしあるようであれば、やっぱりＡＥＤ、探しに来る方というのは、それなりに緊迫した状況でいらっしゃると思いますので、そのあたりについても区のお考え、今、そういった足りないところがあるのではないかと、私以外の区民の方からもご指摘を受けている場合もあるかと思いますが、ちょっとそのあたりのことを教えてください。","respondent":"江部健康課長","answer":"設置に当たりましては、新しいところにつきましては大体、赤とかオレンジとかでＡＥＤ設置箇所という、シールですけれども、それにつきましては、要は出入り口、人が大勢集まるところ、わかりやすいところにつけてくださいということで。","voiceIndex":36,"id":"exchange-014"},{"speaker":"向委員","kind":"確認","question":"わかりました。一緒に確認すればよかったのですが、ＡＥＤが別に使用された後に、返却のために、どこの区有施設のＡＥＤなのか、例えば、これは区役所のＡＥＤですとか、中小企業センターのＡＥＤです、地域センターのものとか、そういうので、ＡＥＤの住所がわかる表記というのは張りつけてあるのでしょうか。","respondent":"江部健康課長","answer":"その機械自体には、ちょっと定かではありませんが、私どもでは、使われますと、一個一個に番号が振ってありますので、この機械が使われたとか、今、正確な受信ができていないというのがわかる。","voiceIndex":38,"id":"exchange-015"},{"speaker":"向委員","kind":"質問・要望","question":"確かにそうだなと思って、きちんと返すべきに返さなければ、きちんと部品交換もできませんし、そのあたりを一度チェックをお願いできたらなと思うのと、あとこれは要望なのですけれども、今、多分、東京消防庁のほう、１１９番しても、ＡＥＤの設置場所、特に案内はしてないですよということを言われたことがあるんです。それと、禁帯出図書の指定をする理由もあわせてお伺いしたいと思います。","respondent":"高山生活衛生課長、中元品川図書館長","answer":"では私のほうから、薬事衛生手数料にかかわります、医薬品販売業等の許可の申請についてご説明します。主に薬局・薬店と言われるものを合わせますと、区内の傾向としましては、大体３００弱の店舗があります。貸出し禁止の図書につきましても、こちらにつきましてはコピーをできるようになってあります。","voiceIndex":40,"id":"exchange-016"},{"speaker":"向委員","kind":"質問","question":"わかりました。薬事衛生手数料については、大体このあたりの数字ということで。ちょっと気になっていて、もしわかれば教えてほしいのですが、間もなく薬事法が変わりますよね。なので、せめて品川図書館だけにでも、メインのところだけにでも、大きな本、コピーできるような仕組みというのは、何とかお願いできないものかなと思うのですけれども、そのあたりを再度お伺いしたいと思います。","respondent":"高山生活衛生課長、中元品川図書館長","answer":"その余波としましては、実際には区内にありますので、薬局等を主体にします指導、ガイドラインの提示といったことが必要になってまいりまして、具体的には、店舗で、薬剤師のいる時間でないと売ることができないでありますとか。資料の一部分、原則として地図などの場合はその半分以下という規定がありますので、その辺のところを勘案いたしまして、大きなサイズのコピーを置いてしまいますと。","voiceIndex":43,"id":"exchange-017"},{"speaker":"向委員","kind":"質問","question":"それぞれ、よくわかりました。最後、１分ぐらいありますが、歴史館使用料ということで、歴史館で非常にさまざまな展示をしてくださっていると思うのですが、英語のホームページ、英語で詳しく、いろいろ拝見できるようなところがまだつくられてはいないのですが、そのあたりを、今の区の考えを最後にお伺いしたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"歴史館についてはホームページ等でご紹介させていただいています。今後、英語表記だとか、そういうものもするように検討します。","voiceIndex":46,"id":"exchange-018"},{"speaker":"鈴木（博）委員","kind":"質問","question":"８４ページの衛生費負担金、公害健康被害補償事務費についてお伺いしたいと思います。２０２０年の東京オリンピック・パラリンピックに向けて、世界に品川区をアピールするのに、この施設はまことに有用ではないかと思いますが、ほかの委員からもいろいろご質問を受けていたのですけれど、何かオリンピック・パラリンピックに向けて歴史館として、取組みとか準備なんかなされているのでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"これから、どういうことができるだろうか。今現在、企画展・特別展を中心にやってありますけれども、品川区民以外、日本国民以外に、全世界に対して、日本の伝統文化である品川のことを書く。そういうことも考えてＰＲしていきたいと考えています。","voiceIndex":49,"id":"exchange-019"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ありがとうございました。では次の質問に移りたいと思います。次は、６８ページの衛生使用料、保健所使用料、試験検査６,１３０件についてお伺いします。この試験検査６,１３０件とは、何の検査なのでしょうか。","respondent":"高山生活衛生課長","answer":"お尋ねの衛生使用料の試験検査につきましては、３保健センターで行っております、糞便と、それからぎょう虫検査に係る使用料の集計です。","voiceIndex":53,"id":"exchange-020"},{"speaker":"鈴木（博）委員","kind":"質問","question":"糞便検査というお話でしたが、まあぎょう虫検査はわかりますけれど、これはどのような病原体を検査されているのでしょうか。","respondent":"亀井品川保健センター所長","answer":"それで、あともう一つ、微生物学的検査ということで、いわゆる保菌者検査ですね。赤痢、サルモネラ、パラチフスそれからＯ１５７。その検査です。飲食関係とか、そういうところで、あと水道工事ですね。ああいうところで必要な場合に、依頼があればやっているということです。","voiceIndex":55,"id":"exchange-021"},{"speaker":"鈴木（博）委員","kind":"質問","question":"事務事業概要もちょっと拝見させていただいたのですけれど、この糞便検査の中で、赤痢とチフスとパラチフスと、腸管出血性、例えば大腸菌と、あとノロウイルスというのが書いてあるのですが、ノロウイルスの検査もしているのでしょうか。","respondent":"亀井品川保健センター所長","answer":"ノロウイルス検査をするときというのは、食中毒とか、あるいは集団感染が疑われたようなときにやることはありますけれど、こちらの使用料の中には、これは行政検査としてやりますので、一般区民からのノロウイルスの検査をしたいとかという問い合わせは時々ありますけれど。","voiceIndex":57,"id":"exchange-022"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ノロウイルスというのは、冬場に乳幼児が感染して、激しい水溶の下痢と嘔吐を繰り返す乳児冬季下痢症で、子どもの病気なのですが、これはいわゆるおなかの風邪、感染性胃腸炎で、潜伏期は１日から３日ぐらいで、糞便にさわった手とか汚染された水や食器を介してうつります。この辺のことは、心配される区民に積極的に情報提供をするべきではないかと思うのですが、区のご見解はいかがでしょうか。","respondent":"高山生活衛生課長","answer":"主にノロウイルス関係ですと、飲食店従事者の方ですと、いわゆる衛生協会のような組織に属さない場合がありまして、こちらが要望に応じまして調査などしている検査がありますので、主にそういった対応と、そういうケースがありました場合は。","voiceIndex":59,"id":"exchange-023"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ちょっと時間がないのですが、公害のほうに移りたいと思います。５６ページの衛生費負担金、公害健康被害補償費負担金と、それから公害健康被害補償事務費に関して、それに関連してお伺いします。これに関しては、今どのような対策がされているのでしょうか。","respondent":"野呂瀬環境課長","answer":"ＰＭ２.５に対してのお尋ねです。昨年の予算特別委員会でも、この春先になりますと非常に心配されるということで、東京都環境局のホームページによりますと、区内では、暫定指針値を超えるような事態が生じるとは考えにくいということで、ホームページ等で周知しております。","voiceIndex":63,"id":"exchange-024"},{"speaker":"中塚委員","kind":"提案","question":"私からは４３ページの歳入全般、１２８ページ、基金繰入金にかかわって、品川区の健全財政を伺いたいと思います。共産党の提案に従って区政を進めた時代に、品川区は赤字に転落した」との答弁がありました。そこで伺いたいのは、昭和５０年、昭和５１年、昭和５２年と３年間、それぞれ幾らの赤字か、当時の歳入状況にどんな社会的要因があったのか伺いたいと思います。","respondent":"本城企画財政課長","answer":"財政調整基金の取り崩しの関係ですが、平成２６年度につきましては、区財政の他の一般財源等の関係の中で、財政調整基金の繰り入れは不要だということで、今回、平成２６年度予算には計上していないというものです。","voiceIndex":66,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"昭和５０年と昭和５２年がいくらであったのかは後で教えていただきたいと思います。ですから、ここにもゆとりがあります。私は、昭和５０年代の歳入状況や社会的要因と随分と異なる中、今年のこの歳入状況で、建設費で２億円、運営費で年間２億円、定員１００名の区立認可保育園を１園に終わらず、さらにつくることが、なぜ将来に禍根を残すことになるのか伺いたいと思います。","respondent":"本城企画財政課長","answer":"ただ、対前年度比ですので、基金の残高等につきましても、過去の平成２１年前後に比べれば、まだ一般財源の税収等のそのレベルには、状況ではないということについては、改めてご説明させていただければと思います。","voiceIndex":68,"id":"exchange-026"},{"speaker":"中塚委員","kind":"質問・要望","question":"経済状況はいろいろあるから、もっと基金はためる必要があるのだと、そんなふうに聞こえましたけれども、私が伺ったのは、昭和５０年代と随分違うんではないかということなんです。今日、改めて当時の区財政を取り巻く経済状況を、歳入状況をどう認識しているのか。そして、ここと比べて、今、区立認可保育園をつくることがなぜ将来に禍根を残すことになるのか、ご説明いただきたいと思います。","respondent":"桑村企画部長","answer":"その意味では、何というのでしょうか、昭和５０年のころに比べれば、昭和５０年のころは相当苦労しているわけですので、私どものほうは正直言って、区債も起こせないような状態になってきた状態はもう繰り返したくないというのが。","voiceIndex":70,"id":"exchange-027"},{"speaker":"中塚委員","kind":"提案","question":"そこを伺いたいと思います。私もちょっと当時の議事録を調べてみました。改めて濱野区長は当時の背景について、共産党の提案に従って保育園をどんどんつくっていったから赤字になったと考えているのか、それとも財政状況とあわせて、根本的には地方自治体が行う行政内容に見合った財政配分が適正に行われていないと、財政構造そのものにあると思っているのか、根本原因は何なのか、改めて伺いたいと思います。","respondent":"桑村企画部長","answer":"その意味では、いわゆる人件費比率が相当高い時代であります。そのような施策を、今のいわゆる公立保育園でやっていれば、それこそ相当な経費がかかります。その後、私どもについては、一定それについて何か工夫ができないかということで行革を進めてきている。","voiceIndex":72,"id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"この状態で、当時の人件費比率にまで合わせたら、ではどれぐらいの保育園になるのかなとは思いますけれど、今求められているのは、来年の７月、１園で最後とする。なので、そこには飛躍があると思いますので、改めてその点、伺いたいと思います。特別区は膨大な行政需要を抱えています。濱野区長はこの立場と同じなのか、伺いたいと思います。それは一体、違うじゃないかと思うんですけどもいかがでしょうか。","respondent":"桑村企画部長","answer":"その意味では、保育園については、これまで幼保一体施設等につきましては公立で運営してまいりましたけれども、民間の私立認可保育園が私どもの区の中で開設できるのでしたら、取り立てて公立保育園をつくる必要はないというのが基本的な認識なのだろうと思います。","voiceIndex":74,"id":"exchange-029"},{"speaker":"中塚委員","kind":"提案","question":"もう一点伺いたいのは、濱野区長は、提案を、すべての提案をやると、６００億円の基金もすぐに枯れてしまい、やがては赤字財政にならざるを得ないと。私の提案で何かシミュレーションを行ったのか伺いたいのと、私が提案したのは、全てを一緒に実施しろと、こんなふうには提案しておりません。区民要望に正面から応える計画の策定を求めたんです。最後にもう一点。その点も伺いたいと思います。","respondent":"桑村企画部長","answer":"私も記憶しておりますが、今、少し上ってきているです。それが、基金の最高の残高から見れば２０億円ぐらい落ちておりますし、税金だってまだ追いついている状態ではありません。","voiceIndex":76,"id":"exchange-030"},{"speaker":"渡部委員","kind":"質問・要望","question":"何か、赤字、赤字みたいな景気悪い話が聞こえてきたんですが、しっかりとこれから質問させていただきたいと思います。家計でもそうですよね。そのためにどうするかというのも１つだと思います。さまざまな区民要望があるという中で、いろいろご苦労をされてきた中で、今回の予算が上がっているということが大前提だと思います。国に認められた小中一貫教育だと思いますが、この内容を教えてください。","respondent":"渋谷指導課長","answer":"小中一貫教育の国の委託事業ですが、これは分離型一貫教育を今後どのように進めたらいいのかということの研究を委託しているものです。","voiceIndex":79,"id":"exchange-031"},{"speaker":"渡部委員","kind":"質問・要望","question":"ありがとうございました。そうですね。初めてついて、分離型の小中一貫教育をどのようにやったらいいのかというのを、国が品川区に委託してきていますから、しっかりと施策を進めていただきまして、ますます国から委託金を、それこそ予算ですから引っ張り出せるように頑張っていただきたいと思います。終わってしまいました、１つ。次、１００ページです。都の委託金の中で民生委員経費が出されています。","respondent":"永尾高齢者福祉課長","answer":"こちらの都の委託金ですけれども、民生委員の人数に応じて、ボランティア活動費および交通費として付与するものですので、単価がございまして、それに対する人数というような計算になっております。","voiceIndex":81,"id":"exchange-032"},{"speaker":"渡部委員","kind":"確認","question":"地域においては欠員が相当出ているところがあって、たしか前に何度か質問させていただいているときに、その地域の方々で穴を埋めるというようなことをお伺いしたかと思うんですが、現状、あれだけの欠員があの地域で、荏原第３の話ですけれども、出ますと、これもう無理じゃないか。民生委員を選任、たしかこの間の１１月だったと思うんですが、やはり町会の方々、相当大変苦労されていました。","respondent":"永尾高齢者福祉課長","answer":"それで、区のほうでの支援といたしましては、もう本当に個別の地域での対応になりますので、ご近隣の、すぐ近くの民生委員の人にもお手伝いをしていただくのですけれども、調査の仕方なんかは、個別のご相談の中で対応をしているところです。","voiceIndex":83,"id":"exchange-033"},{"speaker":"渡部委員","kind":"確認","question":"要は横の連携をしながら、やはり地域の方々が実際そこに暮らしていらっしゃるのかですとか、いるのかと言ったらおかしいのですけれど、そのような確認もされたいと思うんですが、実際、今、品川区内、高齢者の方々、住民票がある方がですね、品川区にいるよと思われている方、間違いなくいらっしゃるのか、実は区の中でも不明な方がいるんですよというような感じなのか。","respondent":"永尾高齢者福祉課長","answer":"高齢者相談員も兼ねておりますので、月に１回の訪問または電話での対応などもしておりますので、その中で、現状の民生委員はきちんとやっていただいていると考えています。","voiceIndex":85,"id":"exchange-034"},{"speaker":"渡部委員","kind":"質問・要望","question":"というか、歩かれています。結構ご苦労されていて、いろいろなお声も入るのかと思うんですが、何とか変更できるようであれば、要望です。回答は結構なんですが、町会等々お話をいただいて、町会の方々にお願いをして、そのような活動をできるような仕組みをとっていただければいいなと思って、これは要望だけします。しっかり頑張ってもらって。これは要望にしておきます。次、１２４ページです。","respondent":"柏原行財政改革担当課長","answer":"細かいところはあれですけども、こちら、地所賃貸料のところに、旧第一日野小学校の関係、それから旧荏原第四中学校の賃借料、こういったところが大きなところで入っているものです。","voiceIndex":87,"id":"exchange-035"},{"speaker":"渡部委員","kind":"確認","question":"入っているという確認をさせていただいた上で、旧荏原四中なのですが、行革の中ではいろいろ話を確認しています。いま一度この場で、旧荏原四中、どのような形になっていくのか、現状、これからのことについてちょっとお話をお願いします。","respondent":"柏原行財政改革担当課長","answer":"旧荏原四中の貸し付けの関係です。現段階は青陵高校、こちらのほうが本年の９月までということで貸し付けをする状況です。その後、建物といたしましては仮設の校舎がありますので、その仮設の校舎は、あくまでこれは仮設でつくったものですので、取り壊しになります。","voiceIndex":89,"id":"exchange-036"},{"speaker":"渡部委員","kind":"質問・要望","question":"改めて了解いたしました。旧荏原四中跡地。その中でやはり、地域のための活動場所としての、やはりもともと公立学校ですから、それを貸すにしましても、それは当然借りる側の学校の事情もあるかと思います。ですけど、地域にとってあそこは大事な場所だったことには変わりありませんので、可能であればというか、なるべく土日等、グラウンド等の開放をお願いしたいのですが、その辺の考え方を聞きます。","respondent":"柏原行財政改革担当課長","answer":"新しく朋優学院との話になった場合も、そういったところは継続したいと思ってありますし、例えばスポーツの団体であるとか、そういったところの開放についても、お話は聞いてありますので、なるべくそういったところがうまく調整できるような形で進めていきたいと思ってあります。","voiceIndex":91,"id":"exchange-037"},{"speaker":"あくつ委員","kind":"確認","question":"私からは質問順に、１１０ページ、都支出金、認知症高齢者支援事業補助金。２つ目に９２ページ、国庫支出金、空き家等実態調査。３点目に、時間があればですけれども雑収入から宝くじ等助成金収入について伺います。この事業は、昨年１０月からスタートした東京都のモデル事業として、品川区が手を挙げた、認知症早期発見・早期診断推進事業のことだと思うのですが、その確認をさせてください。","respondent":"永尾高齢者福祉課長","answer":"昨年９月から実施しております、認知症早期発見・早期診断推進事業につきましての経費です。内容といたしましては、高齢者福祉課の保健師３名の職員費の部分と、あと実際の委託料および一般需要費等の経費に対する１０分の１０の補助です。","voiceIndex":95,"id":"exchange-038"},{"speaker":"あくつ委員","kind":"質問","question":"これはまあ、トップ記事になったので覚えてらっしゃる方も多いかと思います。こういった事業だったと思うのですけれども、これはどういう経路をたどれば、そういったことをやっていただけるのか。例えば、自分の身内が、ちょっと物忘れが激しいなとなった場合に、家族が在宅介護支援センターに行って、うちにも派遣してくださいと言えば、そういったことは可能なのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"この事業をご利用するためには、在宅介護支援センターに行くのが一番早いかなと思われます。現在、訪問をやっている、実際にやっている方、９人おりますけれども、その中のほとんどが在宅介護支援センターのほうからの依頼ということになっております。","voiceIndex":97,"id":"exchange-039"},{"speaker":"あくつ委員","kind":"質問・要望","question":"昨年９月からスタートして９人の方が利用されているということです。９軒ですか、９軒のお宅に訪問されているということだと思うんですけれども。来年度予算案に、全国１００カ所で専門家チームを設けるモデル事業ということで、仮称ですけれども、認知症医療支援診療所ということで、このモデル事業に対して、品川区には打診があったのかどうか、お聞かせいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"認知症医療支援診療所ですけれども、福祉部門については打診はございません。ちょっとはっきりと確定はしていないですけれども、多分、診療所になりますので、医師会のほうに直接行っているのではないかと想定されます。","voiceIndex":99,"id":"exchange-040"},{"speaker":"あくつ委員","kind":"質問","question":"東京都内で１２カ所、この認知症疾患医療センターですか、ちょっと正式な名称は忘れちゃいましたけれども、認定されていて、そこでやっているというところで、やはりかなり広大な範囲を荏原病院だけでカバーしなければいけないというところで、全国的にもやっぱり人が足りないという判断から、厚生労働省はこういうことに進んできたと聞いております。","respondent":"永尾高齢者福祉課長","answer":"品川区の特徴として、地域包括支援センターが、品川区の高齢者福祉課のほうに設置されております。それで、機能として２０カ所の在宅介護支援センターのほうにいるという、こういうやり方をとっております。","voiceIndex":101,"id":"exchange-041"},{"speaker":"あくつ委員","kind":"質問","question":"２０カ所の在宅介護支援センターに、今、認知症コーディネーターの方がいるということで、すぐにつながる体制だということなんです。次に、空き家対策について伺います。もちろん空き家等実態調査だということなのですけれども、それだけなのかどうかお聞かせください。","respondent":"大串住宅担当課長","answer":"委員ご案内のように、こちらは社会資本整備総合交付金、国の補助メニューの中の一つですけれども、地域住宅計画に基づく事業という、交付金の中に十いくつメニューがあるのですが、その中の今申し上げた地域住宅計画に基づく事業というものに該当しておりましたので。","voiceIndex":103,"id":"exchange-042"},{"speaker":"あくつ委員","kind":"確認","question":"たしか前に伺ったときに、空き家の活用についても、何かその目的に含んでいると伺った。それを確認したかったのですけれども、ちょっと時間がないので先に進みます。今回２万５,０００戸の空き家があるということで、８００万円の委託費用で、果たしてこれを実地調査、実際に現場に行って調べる。これ、それとも別の数字があって、それについて調査をかけるのかどうか、この辺について教えてください。","respondent":"大串住宅担当課長","answer":"この空き家、基本的には一戸建てを対象に考えておりますので、今、委員ご指摘がありましたけれども、この８００万円の予算で調査のほうはやっていく。このように考えているところです。","voiceIndex":105,"id":"exchange-043"},{"speaker":"あくつ委員","kind":"質問","question":"２万５,０００件のうちには、これ、アパート、マンションの空き室もたしか入っていると思うんですね。それで、今回、一戸建ての調査ということで、実際はどれぐらいの数を想定されるのか教えてください。","respondent":"大串住宅担当課長","answer":"今、委員ご指摘がありましたように、この２万５,０００戸につきましては、いわゆる長屋や共同住宅、こういったアパート、マンション、これらの空き室も入っているというところで、一戸建てとしましては、総数でいくと。","voiceIndex":107,"id":"exchange-044"},{"speaker":"あくつ委員","kind":"質問","question":"２万５,０００戸から２,０００戸ということで、まあちょっと現実的には見えてきたのかな。調査開始から完了まで、スケジュールがもし今わかるのであれば、どれぐらいの期間か少し教えてほしいんですけど。","respondent":"大串住宅担当課長","answer":"所有者の方、なかなか、今、委員おっしゃっていただいたように、特定するのは難しい。そういった所有者を割り出すというか探し出すというところが難しいと考えておりますので、概ね１年間ぐらいはかけて、この調査を行っていければと考えているところです。","voiceIndex":109,"id":"exchange-045"},{"speaker":"あくつ委員","kind":"質問・要望","question":"このようなご答弁をいただいております。続きまして、１４０ページ、雑入、宝くじ等助成金収入ということで、何度かこれ質問させていただいていますけれども、スポーツ振興くじ、サッカーくじｔｏｔｏの助成金について伺います。今回、この表記はありません。今回、計上されていないということで、その理由について改めて教えてください。","respondent":"齋藤庶務課長","answer":"ということで、天然芝か、これまで支給実績のない自治体にということになってしまいまして、今回、残念ながら歳入を見込めない状況になっているです。","voiceIndex":111,"id":"exchange-046"},{"speaker":"あくつ委員","kind":"確認","question":"改めて確認させていただいたのですけれども、このスポーツ振興くじ、調べたのですが、プロサッカーの指定された試合の結果、あるいは各チームの得点数を予想して投票し、的中すると当選金を受けることができる公営ギャンブルとなっております。その第１番目に来ているのが、誰もが身近にスポーツに親しめる環境の整備とあるわけです。このような認識でよろしいのかどうかお伺いします。","respondent":"齋藤庶務課長","answer":"学校のグラウンドは、汎用性、スポーツに制約がない、土で使ってもらうということでございまして、土が基本です。人工芝にした学校は、それぞれ事情がありますので、事情があればということもありますけれども、基本はあくまで土だということで、そういうことです。","voiceIndex":113,"id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"私からは、７２ページ、自転車駐車場使用料、６７ページ、シルバーセンター使用料、１２５ページ、旧第一日野小学校跡地等、時間がありましたら７６ページの住民基本台帳証明手数料についてお伺いしたいと思います。７２ページの自転車駐車場使用料について伺います。","respondent":"谷口交通安全担当課長","answer":"委員ご質問の見込みの関係ですけれども、この自転車駐車場使用料、２億７,０００万円になるのは、大井町の移設ならびに大森駅の増設。これを見込んでの数字です。","voiceIndex":119,"id":"exchange-048"},{"speaker":"大倉委員","kind":"質問","question":"例えば自転車、バイクの駐車場の利用について、管理をされているところがあると思うですが、その管理の費用についても、どのぐらい見込んでいるのかをお伺いします。","respondent":"谷口交通安全担当課長","answer":"管理におきましては、当面、１億９,７００万円を見込んです。もう一カ所、大崎エリアマネジメントがありますので、これは３,８００万円ほど、この合計額になります。","voiceIndex":121,"id":"exchange-049"},{"speaker":"大倉委員","kind":"質問","question":"例えば、先ほど午前中、沢田委員のほうからも地下駐輪場というお話がありましたが、そうした委託費が、駐輪場を地下にすることによって、機械式であれば必要がなくなるかどうか、教えていただければと思います。","respondent":"谷口交通安全担当課長","answer":"機械式は取り入れていないのですけれど、これは同じで、運営費が使われるのは同じようになります。","voiceIndex":125,"id":"exchange-050"},{"speaker":"大倉委員","kind":"質問・要望","question":"全く同じということなのかどうか教えていただきたいのと、機械ということなので、管理している人件費等が抑えられたりするのかなというところで、もう一度ご答弁いただければと思います。１００％超えて利用されている方がおりますので、今後のバイクの駐車場について、どのようにお考えかお知らせいただきたいと思います。","respondent":"谷口交通安全担当課長","answer":"ちなみに平成２４年度、先ほど委員のご質問の中でも利用率が多いとおっしゃっていましたように、平成２５年度、平成２６年２月１日現在は、全体の使用率、これにつきましては８０.１％、定期自転車７６.３％、定期バイクは７２.５％、当日自転車８６.９％。","voiceIndex":127,"id":"exchange-051"},{"speaker":"大倉委員","kind":"質問・要望","question":"稼働率、お教えいただきましてありがとうあります。どういった要因で下がっているのかもわかれば教えていただきたいのと、ニーズの把握を平成２４年度やったということですが、こうしたニーズの把握とか、どうやって区民が利用しやすい、定期にするのか、一時利用にするのかという考え方をどのくらいのスパンでやっていこうというお考えがあるのか、その辺もあわせてご答弁願います。","respondent":"谷口交通安全担当課長","answer":"この利用率につきましては、平成１３年に駐輪場を開設して以降、駐輪場をずっと整備を進めてきたところですけれども、平成２４年度に初めてこの利用率、当日利用であったり定期利用、その利用率、自転車は自転車、いろいろ見直しをしまして、ラックの幅を広げてほしいだとか。","voiceIndex":129,"id":"exchange-052"},{"speaker":"大倉委員","kind":"質問・要望","question":"いろいろな研究をしていただいて、バイクの利用がかなり増えているということで、予算でも、バイクでプラス３,０００台というぐらい、去年に比べて見込んでいるということで、バイクの駐輪場というのもぜひこれから検討していただいて、バイク大きいですから、道にとめるとすると、なかなか駐輪場に入れなくて、とめるとすると、邪魔になってしまうのと、区民の皆様の安全な交通を。","respondent":"谷口交通安全担当課長","answer":"オリンピック・パラリンピックということで、６年先ということではありますけれども、それは今からの傾向を見ながら、区としては考えていきたいと存じます。","voiceIndex":131,"id":"exchange-053"},{"speaker":"大倉委員","kind":"質問","question":"次に行きます。第一日野小学校跡地等について伺います。昨年の予算でこれも聞いたのですが、劇団四季が経営が安定するまでの３カ月間賃料を免除されて行ってきたということなのですが、過去にもそういった、免除をしてきた事例があるのかどうかお知らせください。","respondent":"平澤経理課長","answer":"そちらにつきましては、旧第一日野小学校、この表題にありますとおり、例えば土壌汚染の改良工事中の免除とか、そういったことをやってございまして、こういった一定の期間免除するというのは、それぞれの契約の中で絡めてやってあります。","voiceIndex":133,"id":"exchange-054"},{"speaker":"大倉委員","kind":"確認","question":"第一日野小学校跡地等の中に、劇団四季の賃貸料というのが入っている中で、昨年は３カ月分、賃料を免除されたということで、そうした、賃料を免除するというのが、今のご答弁だと、ほかにもたくさん契約上あるということなのかどうか確認と、そういうものが今後も、私、ちょっと見たときには、賃料を免除することによって、ちょっと劇団四季さん来てくださいというお話だったのか。","respondent":"平澤経理課長","answer":"この中の、平成２１年７月１５日から平成２２年６月１４日まで、こちらは施設の建設中であるということで、収益が全く見込めないというところで、こちらは免除しているです。","voiceIndex":135,"id":"exchange-055"},{"speaker":"大倉委員","kind":"質問・要望","question":"最後に、シルバーセンター使用料についてお伺いいたします。利用料は、さまざま団体が利用して、６０歳以上が基本的な利用だということで、夜間とか、高齢者の方はなかなか利用しにくいところを目的外使用でも使われているということなのですが、シルバーセンターの今現在の状況、稼働率等を教えていただきたいのと、シルバーセンターのそうした目的外使用について、今現在どのように考えているか。","respondent":"白鳥高齢者いきがい課長","answer":"この無料件数の１,２０８件の主な使用団体につきましては、区の高齢者福祉団体、あるいは障害者福祉団体が使用するということで、これらの団体につきましては全額免除と、そういうような状況になってあります。","voiceIndex":137,"id":"exchange-056"},{"speaker":"大倉委員","kind":"質問・要望","question":"どのくらい、稼働率、パーセンテージで伺えればと思っていたのですが、なかなか、見ると夜間等、今もまだ使用頻度が低いのかなという思いがあります。今後もぜひさまざまな税外収入というところで、ぜひ利用率を上げていただきたいと思いますので、その辺最後に何かありましたらお願いします。","respondent":"白鳥高齢者いきがい課長","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":139,"id":"exchange-057"},{"speaker":"藤原委員","kind":"質問","question":"５２ページ、財調、５４ページ、母子生活支援施設、１２６ページ、財産売払収入、１３２ページ、商店街事業用つなぎ資金貸付金返還金についてお伺いしますが、まず特別区民税についてお伺いしますけれども、区民税の徴収に、歳入ですけどというので伺うのではなくて、この区民税の流れからどういうふうに考えるかということで、ちょっと政策的に伺いたいのですけれども、補正でもお伺いしましたけれども。","respondent":"本城企画財政課長","answer":"配当割交付金については、それに加えて税率自体が３％から５％に変更したことの影響ということで、そういう制度的な要因が含まれているということ。","voiceIndex":142,"id":"exchange-058"},{"speaker":"藤原委員","kind":"質問・要望","question":"次に財調をお伺いしますが、これも１８億円の増で、久々に大幅の増ですけれども、まず法人住民税をどう見たかということについてお伺いしたいのと、それと配られた資料で、いわゆる特別区全体で約６６３億円の増になっていると思うのですけれども、品川区、平均的な区として考えると、この金額を２３で割ると、約２９億円になりますが、そうすると大ざっぱに１０億円ぐらい足りないんですけれども。","respondent":"本城企画財政課長","answer":"財調のもとになります調整三税の関係で、特に法人住民税の見込みについてですが、それは全体として約１７.４％ほどの増を全体の調整三税の中の原資として見ているところです。","voiceIndex":144,"id":"exchange-059"},{"speaker":"藤原委員","kind":"質問","question":"財産売払収入なのですけれども、物品売払収入がかなり増えていますよね、パーセンテージも。これはどういうことなのかということなんですけど、予定があるんだと思うのですけど、その辺ちょっとお伺いします。","respondent":"本城企画財政課長","answer":"大きなものは、清掃事務所の自動車を売り払った収入。それがこの中の大きいものを占めております。","voiceIndex":146,"id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"じゃあ次に、商店街に行きますが、これ、区商連から実際に要望があったんだと思うんですけれども、実際に貸し付け依頼するという方法をとっているので、区が直接という形にはなっていないところは、うまい仕組みをつくったなと思うのですけれども、その中で、平成２６年度の１,０００万円増となった理由と、それと実績はどのぐらいか。区商連に直接託していて、特に課題というものはないのか教えてください。","respondent":"米田商業・観光課長","answer":"こちらについては、商店街連合会のほうに資金を貸し付けた後、逐次報告を求めておりまして、資金が適正に使われているかというようなことの確認をとってまいりますが、今年は３,０００万円の貸付けをして、大体２,８００万円の実績があったというようなことです。","voiceIndex":150,"id":"exchange-061"},{"speaker":"藤原委員","kind":"質問・要望","question":"これからも商店街への支援、よろしくお願いいたします。最後に、母子生活支援施設についてお伺いしますが、これ、児童福祉法になっているんですよね。母子家庭の支援にもかかわらず、児童福祉法で定められている理由を教えていただきたいのと、それとこの予算書を見ますと、定員がたしか２０名だと思うんですけれども、３人という形で出ているんですけれども、この辺についても理由を教えてください。","respondent":"伊崎子育て支援課長","answer":"それから定員ですけれど、３人という現状ですが、利用者定員は２０人なのですが、実際に自己負担金というのを所得に応じていただいておりまして、所得上で大体、費用を負担いただく人数が平均３人ということで、それで計上しております。","voiceIndex":152,"id":"exchange-062"},{"speaker":"藤原委員","kind":"質問","question":"母子家庭の中には、離婚して家を出ていかざるを得ない方や、あと住むところがない、仕事もない、仕事が内定しても保育園に入れない、離婚するまでの期間に不安定な状況であった方もいらっしゃると思うんですけれども、その中で子どもの養育費も不安がある。そういう方を支援していく施設だと考えていますが、利用する条件、手続、それと入所してからの支援についてお伺いします。","respondent":"伊崎子育て支援課長","answer":"入所の手続ですけれども、子育て支援課におります母子自立支援員が、各母子世帯、あるいはそれに準ずる方からの入所のご相談を受けまして、安全の確保や自立支援等を総合的に勘案しまして、ほかの策の利用等も含め、最善と考える策を提案しております。","voiceIndex":154,"id":"exchange-063"},{"speaker":"藤原委員","kind":"質問","question":"品川区では、平成２５年だと思うんですけど、８２５件の離婚の届出があったと思うのですけれども、今後とも支援が必要な、特に母子家庭の方が増えてくるのかなという思いもあるんですけれども、その中で区として、母子家庭のセーフティーネットである母子自立支援施設を今後どういうふうに活用していくのか、区としてひとり親家庭に対してどういう支援をしていくのか、展望をお伺いします。","respondent":"伊崎子育て支援課長","answer":"やはり子育てと就労を両立させていくための支援が、自立の支援が一番重要だと考えておりますので、母子生活支援施設ひまわり荘では、自立ケアのための質を充実させていくべきであると考えております。","voiceIndex":156,"id":"exchange-064"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、６１ページの文化センターのところの荏原文化センターについてお伺いします。荏原文化センターが耐震改修工事のために、今年の９月から来年の７月まで閉館になるということで、ホールや会議室、プールが使えなくなります。プールについて伺っていきたいと思うのですけれども、荏原文化センターのプール利用団体の数、それと一般利用の人数を教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"荏原文化センターの耐震工事に伴う関係です。今お尋ねのプールの利用団体の数は、荏原文化センターの利用団体は１２団体あります。そして、プールの利用状況ですが、平成２４年度の実績で、個人開放、それから貸切り等を含めまして、７万３,７３８人です。","voiceIndex":159,"id":"exchange-065"},{"speaker":"石田（ち）委員","kind":"質問","question":"プール利用されている皆さんには、工事中のことをどのような対応をとられていて、説明会などやられたのか、どのような声が出されているのかを伺いたいと思います。それで、区としてこのプールの代替地を確保するというお立場に立っているのかも伺います。","respondent":"安藤文化スポーツ振興課長","answer":"それで私どもも、この工事の期間、来年の７月末までですけれども、大変ご迷惑をかけるということで、私どもも利用者の方々を対象に説明会を開催させていただきました。","voiceIndex":161,"id":"exchange-066"},{"speaker":"石田（ち）委員","kind":"質問","question":"もう割り振りが確定して、そこでオーケーですと言われている団体はどれぐらいあるのでしょうか。そして無理、ちょっと無理そうなんですという声はあるのか。それに、その理由は何なのか。そして、それについて区はどう答えているのか、お伺いします。","respondent":"安藤文化スポーツ振興課長","answer":"代替地のことですけれども、これも説明会のときにお話をさせていただきました。プールを約１０カ月ですけれども使えませんと。そのかわりに代替地として、今から建設するのはとてもじゃないけど無理ですよと。","voiceIndex":163,"id":"exchange-067"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはり、ずっと通い続けてそこでやり続けてきた団体においては、割り振られてもなかなか難しいという実態も私も聞いています。いろいろご紹介されているのですけれども、やっぱり遠くて行けないと。そういう団体は仕方ないですねと、我慢して納得していただくということなのでしょうか。そのための対策をさらに進めていただきたいなと思うんですけれども、いかがでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"その法人、団体にも説明会を行って、利用者協議会の団体がみんなで１００ほどありますけれども、その団体の方々にもご説明させていただいて、同じように各文化センターに分散して継続的に活動するだとか、また周りの我々の近くの地域センター等。","voiceIndex":165,"id":"exchange-068"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですけど、やっぱりその間のスポーツの確保というのを、しっかりと責任を持って区が進めていくべきだと思うんですよ。それで、仕方ないでは済まされない。プールから離れていってしまうと思うんですね。逆にそこから離れていってしまうという、そういった実態がありますので、区がしっかり責任を持ってスポーツの確保をしていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":167,"id":"exchange-069"},{"speaker":"こんの委員","kind":"質問","question":"そこで、まず現状をお聞きしたいのですけれども、認可保育園については、入園希望の園を選ぶ際、保護者の方はどんな理由でその園を選んでいるのか、その傾向性をまずお聞きしたいのと、また認証保育所の入園の状況についてですけれども、これは保育料に対する助成制度、スタートしておりますので、そうしたところからも見られるのかなと思うのですけれども、定員の充足状況ですね、どういう状況なのか。","respondent":"立川保育課長","answer":"１歳児につきましては２３０名の定員に対して２０４名の在籍という、こういった状況です。","voiceIndex":169,"id":"exchange-070"},{"speaker":"こんの委員","kind":"提案","question":"認証保育所は、定員数に対して０歳児が１９３に対して１３０。そこで、こうした現状を解消していく、活用していく、そうしたことで、以前、平成１６年に我が会派から、遠い園に対して送迎の、こうした対策をとったらどうかという提案をさせていただいたことがあります。でも、選んだら通うのに非常に大変だというところもあって、送迎バスをどうかという提案をさせていただいたことがありました。","respondent":"立川保育課長","answer":"しかしながら、今後の保育園の展開を考えたときに、こういう施策も有効ではないかということで、調査については進めていきたいと考えております。","voiceIndex":171,"id":"exchange-071"},{"speaker":"こんの委員","kind":"質問・要望","question":"いかがでしょうか。","respondent":"金子子ども未来事業部長","answer":"そういう意味では、私どもとしましても、当時八潮というのはなかなか定員が充足しないという状況がありましたので、品川区の中でこういうことができるかどうかというのも検討してまいりましたけれども、なかなかやっぱり、都市部の町が連立して続いているようなところでは。","voiceIndex":173,"id":"exchange-072"},{"speaker":"渡辺委員","kind":"質問","question":"私は、１４１ページ、宝くじ等助成金収入と、あと５８ページからの総務使用料全般で伺います。総務使用料全般というところでは、幅が広いので、ある意味、文化施設に絞って伺いたいと思います。先だって、常任委員会、区議会のほうでも同様の趣旨の勉強があったのですが、特に文化施設の、まず最初に利用率を、ホールだとかスタジオだとか講習室だとか、伺いたいと思います。","respondent":"安藤文化スポーツ振興課長","answer":"こみぷらにつきましては、申しわけございませんが、平成２５年度の４月から１１月の利用率です、３３.７％です。","voiceIndex":176,"id":"exchange-073"},{"speaker":"渡辺委員","kind":"質問","question":"もう一度聞きます。そして、次年度に向けてというのが、平成２６年度分は、１２月、１月と募集があって、説明会が１１月にあってという中で、どのような接点というか考えで何か当たられたのかだけを聞いたのが１点です。文化施設全般になっちゃったんですが、主要なところで、きゅりあん、スクエア荏原、五反田文化センターで、それぞれホール、スタジオ、講習室等の大まかな利用率があれば教えてください。","respondent":"安藤文化スポーツ振興課長","answer":"それから五反田文化センターのホールです。ホールにつきましては５８.４％、スタジオにつきましては８３.５％。荏原文化センターにつきましては、ホールは３６.１％となっています。","voiceIndex":181,"id":"exchange-074"},{"speaker":"渡辺委員","kind":"質問・要望","question":"学校の施設は、人工芝という点では、午前中のご答弁のように、過去３年間同一のものでは申請は受けられないということはガイドにも明記されていて、これはやむを得ないと。この助成金の性格上、Ａ、Ｂ、Ｃの３つの区分の中で、Ａなら１００％、Ｂなら７０％、それに対する上限金ですね、結構な金額なんです。この辺に対する助成金へのアプローチの考え方、もう一度伺いたいと思います。","respondent":"本城企画財政課長","answer":"ご指摘ございましたように、今お話の中でも、それらを含めてこれからさまざまな施策を各部署でやっていく上で、財源面での確保をきちんとしなければいけないというのは大前提であると思いますので、そのあたり、改めて調査して、さらに活用できるものがあるかどうか。","voiceIndex":185,"id":"exchange-075"},{"speaker":"渡辺委員","kind":"質問","question":"ちなみにクラブハウス等だと７,５００万円が上限です。全体への利用率が、もう７割だ、８割だというのが、概ねは文化施設を絞ります。これは抽選だとか調整を経ての数字ですから、需要というのは、またその何倍もあると思っています。ひいてはそこへ投資することが、守りに入らずに投資することが区民サービスの質の向上になると思いますが、まず大くくりな見解をお知らせください。","respondent":"安藤文化スポーツ振興課長","answer":"それと、都有地だとか、そういうところも、今回のオリンピック・パラリンピックのホッケー会場となる見込みです。そういうところも含めて、今後、都のほうにも、区としてそういう施設の状況について交渉していきたいと考えています。","voiceIndex":187,"id":"exchange-076"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ありがとうございました。この点について、国や都との交渉に決意といいますか、それが１点伺いたいのと、先ほど文化センターを１つ例に伺いましたが、現状の施設の有効な活用というんですかね、手の入れ方。そういったところを転用していくというのは、待つのではなくて、どんどん積極的な改修というのが必要だと思いますが、この辺いかがでしょうか。","respondent":"安藤オリンピック・パラリンピック推進担当課長、安藤文化スポーツ振興課長","answer":"それで、軟式野球連盟を中心に今盛んに動いています。そういうことは私たちも察知しています。私たちも、東京都ならびに組織委員会のほうにその旨、会場の確保または大会費等、これは強く、粘り強く求めていく所存です。委員のおっしゃるように、鏡のついた部屋、音楽については非常に高うあります。そんなことで、今後研究しながら施設のあり方も考えていきたいと思っています。","voiceIndex":189,"id":"exchange-077"},{"speaker":"西本委員","kind":"質問","question":"４５ページの特別区民税。特に滞納繰越分に対して２８％と。決算か予算か、以前も質問したんですけど、いろいろ滞納の方には指導をされていろいろやっていますよということをおっしゃっていたと思うんですね。それ、どうなっているでしょうかということです。２つ目は、８６ページに、国庫補助金の中で、私立幼稚園に対する就園奨励費というのがあります。基本額が２種類ありました。","respondent":"高森税務課長、立川保育課長、品川木密整備担当課長","answer":"この辺のところを踏まえますと、ちょっと寂しいかもしれませんけれども、２８％が今の段階では妥当ということでちょっとご理解いただきたいと思います。そういった意味で、幼稚園同士の比較というのは比較的できるところですけれども、保育園につきましては。それで、この件に関しては、やはり国の補助が出ていないということで、東京都、区とも連携して、国のほうに補助のほうが出ないかということで。","voiceIndex":193,"id":"exchange-078"},{"speaker":"西本委員","kind":"質問","question":"そういった場合に、もちろん長時間保育をする場合には、これは受益者負担という考え方になるかと思いますので、それは課されるべきものだと思いますけれども、基本的な考え方の中では、今後どういうふうな負担を保護者の方々にしていただくべきなのかというのは、それは進めていく中で、やはり考え方が出てくるはずなので、その辺のお考えをお聞きしたいと思います。それから、木密１０年プロジェクト。","respondent":"今井制度改革・待機児童対策担当課長、品川木密整備担当課長","answer":"委員ご指摘のとおり、施設型給付や家庭的保育事業も地域型保育給付のほうになってまいりまして、施設のほうでは支援給付という形になりますが、あわせて地域子ども・子育て支援事業の中で。これから、この木密地域不燃化１０年プロジェクト、本格実施地区も１２月から前倒しという形で始まりまして、来年度から全軒訪問という形で、一軒一軒訪問していくような体制をとっていこうかと思います。","voiceIndex":197,"id":"exchange-079"},{"speaker":"山元委員","kind":"質問","question":"私からは６３ページ、こみゅにてぃぷらざ八潮と、それから９３ページの耐震シェルター等設置助成、また時間があればその下の道路バリアフリー事業についてお伺いしたいと思います。過日、区民委員会でお話がありましたけれども、今回、こみゅにてぃぷらざの２階の区民活動施設において、第１講習室、第２講習室、第３講習室、第５目的室を、また倉庫を、協働推進施設にすると。","respondent":"安藤文化スポーツ振興課長","answer":"それとまた、利用率についても、低いところがございましたので、そこを転用させていただいたです。そして今後の見通しですけれども、協働のほうも需要がありますので、ますます今後、協働推進室として活発になろうと考えています。","voiceIndex":201,"id":"exchange-080"},{"speaker":"山元委員","kind":"質問","question":"本当に、今、活動拠点室というんですかね、今、８つ使われていらっしゃると思いますけれども、これからそれぞれ、このような部屋がつくられるのかなと思いますけれども、どのぐらいつくられるのかということと、それから、このお部屋は、部屋が幾つぐらいできるかということをお聞きしたいのと、それからちょっと基本的なことを、お部屋をつくる場合、冷暖房みたいな。","respondent":"寺嶋協働・国際担当課長","answer":"空調につきましては、こみゅにてぃぷらざ八潮は全館空調になっておりますので、今のところ個別空調をつける予定はございません。","voiceIndex":203,"id":"exchange-081"},{"speaker":"山元委員","kind":"質問","question":"実際に私自身もここをお借りしているんですが、今まではちょっと暖房がきかない部屋も若干あったみたいなものですから、そう思って、ちょっと今お聞きしました。多分、たまたまだったのかもしれません。点検していただければと思います。するとまたちょっと低くなってと若干心配してるんですが、その辺、皆さん使っている方たちのご意見というのはどんなのがありますでしょうか。","respondent":"安藤文化スポーツ振興課長","answer":"そしてまたメイプルセンターのそういうカルチャースクールも、今後そこで展開していきます。ですから、部屋が少なくなっても、空いているところでそれを展開させていただきまして、ますますにぎわいのある施設にさせていただきたいと考えています。","voiceIndex":205,"id":"exchange-082"},{"speaker":"山元委員","kind":"質問・要望","question":"本当にうれしいことだと思います。それは結構です。それからすみません、シェルターについてご質問させていただきたいと思います。去年の予算は５４０万円ということで、約２００万円近く、今回は減ってしまったということでありますけれども、この辺、どうしてこんなに減ったのか。とりづらくなる状況があるというか、補助金なのであれですが、その辺もしおわかりになれば教えていただきたいと思います。","respondent":"品川木密整備担当課長","answer":"こちら、耐震シェルターの件ですが、来年度から東京都のほうの補助が打ち切りになってしまいました。その関係で、以前までの区費投入分は維持するというような形で見直しをかけて、今回、件数減となっております。","voiceIndex":207,"id":"exchange-083"},{"speaker":"山元委員","kind":"質問","question":"さまざまいろいろなアイデアをいただいてという思いはあるんですけれども、その辺は、現場の課長としてはいかがなんでしょうか。","respondent":"品川木密整備担当課長","answer":"ただ、最近の傾向としましては、やはりシェルターというのは、そもそもが経済的に厳しい方、そういう方について、耐震化ができない方について使っていたというものがあります。","voiceIndex":209,"id":"exchange-084"},{"speaker":"山元委員","kind":"意見","question":"何かそういうものも見ていただいて、何か参考にしていただくと、またちょっと捉え方が違うのかなと思いますので、よろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":211,"id":"exchange-085"},{"speaker":"井上委員","kind":"質問・要望","question":"５件とも質問を先に申し上げます。２点目です。それから予算が減額されて、ひとり親世帯に十分な支援事業が引き続き提供されるのか危惧していますが、区の見解を伺います。３点目です。知的障害者グループホーム使用料、昨年同様、１９戸となっておりますけれども、上大崎に新たにできる知的障害者のグループホームについてはどういう扱いになるのか伺います。以上５件、お願いいたします。","respondent":"本城企画財政課長、伊崎子育て支援課長、中山障害者福祉課長、渋谷指導課長、立川保育課長、福島青少年育成課長","answer":"ＰＲ、周知の仕方についてですが、先日の広報の中で特別区民税の変更についてのお知らせをしましたり。ひとり親家庭自立支援給付金事業の減のことですけれども、こちらは、高等技能訓練促進費の予算の減ということでございまして、これは。ということで、合計としましては２４戸ということになるのですけれども、歳入、実際の使用料といたしましては。私のほうからはまず１点目、特色ある教育活動経費、インクルーシブ教育システム構築モデルスクールについてご説明申し上げます。","voiceIndex":213,"id":"exchange-086"},{"speaker":"井上委員","kind":"質問","question":"今のひとり親家庭のところで、私は推移をお伺いしたので、単年度ではなく、どのように増えているのかということをお願いしたいと。それから公立保育園でも、利用者の推移はどうですかということをお伺いしていますので、そちら答弁漏れなのでお願いしたいと思います。","respondent":"福島青少年育成課長、立川保育課長","answer":"児童扶養手当につきましては、平成２２年度が１,８１５人、平成２３年度が１,８３９人、平成２４年度で１,８８４人です。区立幼稚園の預かり保育の推移ですけれども、延べでお話しいたしますと、平成２３年度、２万７９３人、平成２４年度、２万４,７６８人、平成２５年度、こちらは１月末見込みですが、２万５,８０９人ということになっております。","voiceIndex":220,"id":"exchange-087"},{"speaker":"井上委員","kind":"質問・要望","question":"それから私立幼稚園の預かり保育というのは、ぎりぎり就労の方とか、あとはほかの要件でも預かり保育ができるんですが、実際に預かり保育をしている方のお話を聞けば、兄弟のための用事であるとか、平日行わなければならない用事、そういったことで、それでなおかつ有料ですから、利用されている方は非常に最小限の状況ということですので。","respondent":"中山障害者福祉課長、立川保育課長","answer":"医療との連携というところの課題もありますので、今現時点での精神障害者の方のグループホームの具体的な計画というのはございませんが、やはりそういった医療機関との連携も図りつつ、区内にも整備していければと考えているところです。今後につきましては、やはり国の動き等見ながら、この辺の預かりについては、一定、検討していく必要があるかなとは考えているところです。","voiceIndex":223,"id":"exchange-088"},{"speaker":"井上委員","kind":"質問・要望","question":"幼稚園に預けている方が、わざわざそこから引き取りをしてオアシスルームにというようなことは現実的ではありません。ぜひ前向きに検討いただきたいと思います。それから通過型のグループホーム、そこが空きがあることと必要であるということはニーズが違うと思いますので、なぜ空きがあるかということも慎重に考えていただいて、検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":226,"id":"exchange-089"},{"speaker":"原委員","kind":"質問・要望","question":"非常に、おっしゃるとおり、９割というのは非常に大変なことでございまして、１点ちょっと、もう少し聞きたかったのは、プラネタリウムのことがあるものですから、その辺をお話をいただきたいなという。何でなんだろうと、私は腑に落ちない部分もいっぱいあるんですけれども、そういうこともあるものですから、これについて、本当になかなか大変な行政サービスなので、思いを語っていただければと思います。","respondent":"安藤文化スポーツ振興課長、安井土木管理課長、稲田道路課長","answer":"私からは、プラネタリウムのことについてご説明申し上げます。屋外広告物の関係ですけれども、特に最近、電柱等に、不動産広告、いろいろな広告等が非常に張られているということで、こういったものについて撤去等。我々、道路の管理におきましては、全ての人が障害等支障なく普通に使えているというところを進めていきたいと感じているところです。","voiceIndex":234,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"８３ページ、家庭あんしんセンター運営費。それと８９ページになりますけど温暖化対策事業。時間があれば７１ページの創業支援ということで。多分、３番目のはちょっとぎりぎりなので、ちょっと１番目の、家庭あんしんセンターについて質問をします。平成１６年に児童福祉法が改正されて、法的な位置づけがなされましたけれども、まず家庭あんしんセンター、どんな仕事をしているのか教えてください。","respondent":"伊崎子育て支援課長","answer":"家庭あんしんセンターの機能ですけれども、家庭あんしんセンターは母子自立支援施設としての、母子家庭の自立を支援するための施設です。それから子育て支援センターとしまして、地域の子育て家庭への支援をする機能。","voiceIndex":239,"id":"exchange-091"},{"speaker":"大沢委員","kind":"質問・要望","question":"ここのところ、子育て支援課というところもありまして、事務事業概要の中には、子育て支援課がさまざまな連携ということで事業を行っている、この中の一つにあるんですけれども、ここで区役所の本庁にある子育て支援課と子育て支援センターの役割分担と関係がちょっと見えにくいので、教えていただきたいと思います。","respondent":"伊崎子育て支援課長","answer":"子育て支援課、本課におきましても、虐待相談を受けておりまして、子育て支援センターと子育て支援課で連携をとりまして対応しておるところです。","voiceIndex":241,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問","question":"今、虐待等々で、同じ種類の仕事がぶつかっているんですけれども、ここらのところの情報というか、連絡調整型の交通整理はどのようにつけているのか教えてください。","respondent":"伊崎子育て支援課長","answer":"子育て支援課のほうで、虐待相談の第一義的な通報を担うとともに、同じ機能は子育て支援センターのほうも担っているのですが、継続的な支援を必要とする家庭に対する事業につきましては、子育て支援センターのほうで一義的に行っております。","voiceIndex":243,"id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"今、一義的ということが２つ出ましたけれども、そこの中の一義的なところ、２つの言葉の中に「一義的」という言葉が２つ出るということは、本来であれば一義的、二義的というような、然るべきところがあっても当然と思うんですが、そこら辺のあたりは整理ができていないやに私は受け取るんですけども、どういうふうに整理をされてお考えになるのか教えてください。","respondent":"伊崎子育て支援課長","answer":"それから継続して支援が必要だという家庭についての訪問等のサポートは、子育て支援センターが担っているです。","voiceIndex":245,"id":"exchange-094"},{"speaker":"大沢委員","kind":"質問","question":"そうしたら、そこのところで今、相談業務を行っているということですけれども、例えばどんな場合に相談業務を行う。どんな場合に相談業務に応じて家庭訪問などを行っているのか教えてください。","respondent":"伊崎子育て支援課長","answer":"子育て支援課と子育て支援センターで、そういった１つの役割を担っているところですが、子育て支援センターの養育訪問のほうは、引き続き相談を継続していく、訪問を継続していく世帯だということを、子育て支援課あるいは子育て支援センターで。","voiceIndex":247,"id":"exchange-095"},{"speaker":"大沢委員","kind":"質問","question":"事務事業概要、お答えというか、しっかりとしたご答弁なんですけど、実際のところ、それで済んでるんですかね。ちょっと教えてください。","respondent":"伊崎子育て支援課長","answer":"お子さんに対する相談は非常にさまざまですので、当然、子育て支援課および子育て支援センターのほうでの対応よりも専門的な相談が必要な世帯に対しては、保健所あるいは児童相談所、必要な機関等をご紹介しまして、そちらと調整して対応しています。","voiceIndex":249,"id":"exchange-096"},{"speaker":"大沢委員","kind":"質問","question":"次に移ります。子育て支援センター、６つ機能が先ほどあるということで、その中に養育支援保護という項があって、これはちょっと厚生労働省のガイドラインを読みます。この中で、保健医療の連携体制に基づく情報提供および関係機関からの連絡等、報告等により把握されていると書いてあるのですけれども、この要支援家庭の把握というのはどのように具体的に行われているのか教えてください。","respondent":"伊崎子育て支援課長","answer":"品川区では、出生届が出されたお子さんに、すくすく赤ちゃん訪問というのをやっておりまして、その中で、保健師や助産師等が訪問した世帯で引き続き訪問等、相談が必要な世帯についての情報を子育て支援課のほうにいただいております。","voiceIndex":251,"id":"exchange-097"},{"speaker":"大沢委員","kind":"質問","question":"訪問は手段であって、要支援家庭の把握をどのようにしているか。ということは、訪問して要支援家庭の把握をしているということでいいのでしょうか。教えてください。","respondent":"伊崎子育て支援課長","answer":"そういった方につきまして、引き続き訪問を行ったり、あるいは子育て支援センターのほうの養育支援の訪問につなげたりということをしております。","voiceIndex":255,"id":"exchange-098"},{"speaker":"大沢委員","kind":"質問","question":"じゃあ、この、さまざまなということ、先ほど連携という話も出ましたけれども、やはりいろいろなところに連携する事業であるがゆえに、相談機能というのが分散してしまって、一元的にできるのかどうかというのが心配なところがあるんですけれども、そこのところをどういうふうにお考えになりますでしょうか。どういうふうにすれば相談機能が強化できるのかとお考えでしょうか、教えてください。","respondent":"伊崎子育て支援課長","answer":"子育て支援センターと子育て支援課のお子さんの相談、児童相談につきましては、同じ機能を持つということで、お子さんの相談のデータを共有しております。ですので、そこで、２カ所で別々の対応をするということはないように、連携をとって対応を図っているところです。","voiceIndex":257,"id":"exchange-099"},{"speaker":"大沢委員","kind":"質問","question":"今、情報の共有ということでおっしゃいましたけれど、情報の共有を円滑に行うためにどのような工夫をしているのか教えてください。","respondent":"伊崎子育て支援課長、金子子ども未来事業部長","answer":"情報の共有のためには、それぞれの立場でそれぞれが何ができるかという役割をそれぞれの機関が認識するということが大事ですので、必ず年に１回、地域養育支援、養対協と言われておりますけれども、養育支援対策協議会を持つとともに。子育ての相談というのは、もちろん、今、課長のほうでるる説明申し上げたとおり、子育て支援課、それから子育て支援センターのほかにも、児童センター、保健所、さまざまなところで受けています。","voiceIndex":259,"id":"exchange-100"},{"speaker":"若林委員","kind":"質問・要望","question":"９２ページの空き家等実態調査についてですが、これは要望します。その上で、町会・自治会のご協力のもとに業者への委託という流れなんですが、ぜひ今後の老朽化対策、また活用策、いずれにしてもやはり不動産団体との連携は、これは初動の時点からしっかりと、連携の仕方はいろいろあると思いますが、いずれにしても区としてこの事業に取り組みますよというところの呼吸合わせというんですか。","respondent":"大串住宅担当課長","answer":"午前中、ご答弁申し上げましたように、町会・自治会、こういった地域の方々のご協力、あわせて今委員からおっしゃられたような形での不動産業界団体との連携、こういったものも深めながら、この調査を実りあるものにしていきたいと考えています。","voiceIndex":264,"id":"exchange-101"},{"speaker":"若林委員","kind":"質問・要望","question":"続きまして、８７ページの国庫補助金の中で地域生活の支援ほか４事業という歳入があります。はこの地域生活の支援ほか４事業、「ほか」にどういう事業があるのかというのを教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"地域生活の支援ほか４事業、どういったものがあるかというお尋ねです。こちらのほうですけれども、地域生活の支援ということと、成年後見支援、支給決定の審査会、それから心身障害者福祉会館の運営費、障害者生活支援センター運営費です。","voiceIndex":266,"id":"exchange-102"},{"speaker":"若林委員","kind":"質問","question":"そこで、この地域生活支援事業においては、区市町村で実施する事業として、いわゆる必須の事業が１０あります。それからいわゆる任意事業として、大くくりですけれども、１つは日常生活支援。２つ目の枠で社会参加支援、これが５事業あります。どのようにチョイス、選択をされて、また選択をされない事業についてはどういうご判断をされているのかというのをお聞きしておきたいと思います。","respondent":"中山障害者福祉課長","answer":"任意事業の中で対応していないものというのは多分ない、細かいものも入れればおそらく大抵のものは採用していると思っているところですが、社会資源等の関係もありますので、こちらのほうにつきましては、社会資源を整えつつ。","voiceIndex":268,"id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"引き続き、任意事業も含めて、しっかりとニーズを捉えて進めていただきたいと思います。そこで、そもそもいわゆるサービス必要量の全体像をどのように捉えて、それを区として計画を、次年度の予算を策定する際に計画を立てられ、その上で国また都と、いわゆる折衝というのでしょうか、交渉というのでしょうか、そういうものがどういう模様で行われているのかというのを、１つ教えていただきたいと思います。","respondent":"中山障害者福祉課長","answer":"そういった全体の調整を踏まえた上で、こちらのほうの計画には載せているです。地域生活支援事業のほうも、基本的には考え方としては同じです。","voiceIndex":270,"id":"exchange-104"},{"speaker":"若林委員","kind":"質問・要望","question":"昨年末、八王子市のほうに、いわゆる重度訪問介護についての視察を行ってまいりました。ご様子を聞いてきました。私も、今の課長の答弁の理解の中で考えていたのですが、地域性もあるんでしょうか、聞きましたら、国は意外と柔軟に、そこら辺のいわゆるサービス量について、自治体が上げたことについて、柔軟に対応してくれますよという担当者のお話を伺いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":272,"id":"exchange-105"},{"speaker":"高橋委員","kind":"質問","question":"よろしくお願いします。５４ページの保育園保育料。次に、あと１４０ページ、諸収入の中の都市基盤整備費収入。ちょっと間近の感じがあるんですけれども、１１４ページ、都支出金で、土木で道路関係のところの話を伺いたいと思います。そして、本来の事業と延長保育等の特別な事業というのでしょうか、それもまた収入の枠組みというか区分が別れているのですが、そのあたりの理由をお尋ねいたします。","respondent":"本城企画財政課長、金子子ども未来事業部長","answer":"この仕分けの仕方なんですが、いわゆる決算統計上、普通会計の部分で示されているもの、この区分けに合わせまして、こちらもこのような区分としています。保育園保育料につきましては、従来から全体の経費を国と都、それから市町村と、保護者である利用者で、それぞれ負担するという考え方がありまして、保育料については負担金のほうに入っているという、特殊な事情があります。","voiceIndex":274,"id":"exchange-106"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、今、保育園保育料のほうでお話が来て、幼稚園のほうは使用料のほうに入るのは、これは保護者だけが負担しているものでは。使用料という、表現的に、どうしてこちらに入るのかというところの区別。逆に言うと、もしかしたら保育園保育料も本来は使用料のほうに入るはずなのか、今のような事情で負担という観念で、あとは措置ですか、そちらの関連の流れの中にあるのか。","respondent":"金子子ども未来事業部長","answer":"説明が足りなくて失礼しました。","voiceIndex":277,"id":"exchange-107"},{"speaker":"高橋委員","kind":"質問","question":"そうなると、これは先ほど決算の書類とか予算の話ですが、庁内で職員の方々がお使われになっている中での、予算上だと、もう一緒にしているというか、計算上、そういう形でやられているのかということと、それから、今、保育園、幼稚園という形ですが、幼保一体の施設が区には幾つもあるんですが、そこでのいわゆる保育料については、ここではどのような形で区分されているのでしょうか。","respondent":"立川保育課長","answer":"幼保一体施設につきましては、施設によって年齢区分型と、あと並列型ということで、４歳、５歳児が幼稚園部門、０歳から３歳までが保育園部門ということで、明確に分かれている部分につきましては、負担金と使用料というのは明確に分けて収納しています。","voiceIndex":279,"id":"exchange-108"},{"speaker":"高橋委員","kind":"質問","question":"かなり非常に法的ないろいろな縛りがあるのかもしれませんけれども、複雑でちょっとわかりにくい部分があるので、何らか区民の方にとってもわかりやすいような形だとあれなのですが、新制度に向けての歳入の区分についてはどのようにお考えでしょうか。","respondent":"今井制度改革・待機児童対策担当課長","answer":"新制度に向けましては、やはり利用者負担のことでいろいろと設定してまいりますけれども、現在の区立幼稚園と施設型給付のほうに移行するかどうかにつきましては、今検討中ですので、このような区分がどのような形で適切かどうか、今後判断してまいります。","voiceIndex":281,"id":"exchange-109"},{"speaker":"高橋委員","kind":"質問・要望","question":"新たな新制度の中で、いろいろな、国のほうから次々に出てきますので、その動向を見ながら、ちょっとこのような形で、いろいろな経緯がありながらも区分しているのですが、わかりやすい形にしていっていただけることを要望いたします。よろしくお願いします。平成２５年度は５億９,５００万円だったのですが、こちらの内訳はどのようなものなのでしょうか。","respondent":"溝口都市開発課長","answer":"今年の１月に竣工しました大崎西口南地区に関連いたしまして、東西自由通路の維持管理等、そういった費用が入っておりますので、額については大きく変動しているというものです。","voiceIndex":283,"id":"exchange-110"},{"speaker":"高橋委員","kind":"質問","question":"そうすると、歳出のほうにある、今お話のあった大崎駅西口広場の整備費の費用などはこちらからという形になるわけだと思います。そうすると、この事業について、区にとって、引いては区民の方のメリットといいますか、サービス向上について、どのようにお考えでしょうか。","respondent":"溝口都市開発課長","answer":"再開発事業を行うことによって、公共基盤の整備はかなり進められていると思います。そういったものを区の資産だけでなく民間を活用することによっての整備というのは、区民にとってもよりよい効果がありますので、再開発事業を行っていくように考えているものです。","voiceIndex":285,"id":"exchange-111"},{"speaker":"南委員","kind":"質問","question":"７２ページの土木使用料について、ちょっと。それと１３２ページの諸収入の奨学金貸付金返還金について伺います。自転車の一時利用というのが、大体１日１回につき幾らかと。それから大森駅水神口あるいはその周辺の自転車駐輪場でどのくらいの歳入を見込んでいるのか。そこから伺います。","respondent":"谷口交通安全担当課長","answer":"ご質問の大森駅の一時利用につきましては、１日１５０円だったと思います。全体的な歳入については、今のところ現在、年間３００万円を見込んでおります。","voiceIndex":288,"id":"exchange-112"},{"speaker":"南委員","kind":"質問","question":"何とかここを、区としては周辺の放置状況を解消するということで、ここに設置したいということだったのですが、それについては、一定の期間は、まあやむを得ないけれども、しかしきちんとした計画を持って、その以降は撤去してほしい。品川区がこの駐輪場の関係で事業を展開していらっしゃいますが、駐輪場を設置するという目的はまず何かということをちょっと伺って、大森の関係に進んでいきたいと思います。","respondent":"谷口交通安全担当課長","answer":"大森駅周辺の整備計画ですけれど、住民の説明会も４回実施しまして、住民の皆さんとも１０回以上の、いろいろ協議もした中で、いろいろご説明して、計画的に、品川区の都市基本計画の中で進めていきますということで、ご説明申し上げたところです。","voiceIndex":290,"id":"exchange-113"},{"speaker":"南委員","kind":"質問","question":"私が伺ったのは、駐輪場を品川区が設置している、その目的は何かということを聞いたんです。１６５台設置した、あそこのところは、歩行者の安全確保および防災対策上の活動確保ができると考えているのかどうか、まずその見解を伺いたいと思います。","respondent":"谷口交通安全担当課長","answer":"通行の安全確保ならびに防災上には、全く問題がないと考えております。","voiceIndex":292,"id":"exchange-114"},{"speaker":"南委員","kind":"質問","question":"しかし、震災が、災害が発生したときに、ああいう通行の柵を３つ置いてあって、うまくみんな、きちっと避難できるでしょうか、急いで。その点について１つ。合意したというふうな認識なのでしょうか。私は合意していないと思っていますので、そこについては、やっぱり皆さんの願っている方向で、やっぱり撤去を一刻も早くできるように段取りするべきだと思っていますが、そのあたりの見解を伺います。","respondent":"谷口交通安全担当課長","answer":"これは当然、パイプ柵を設けまして、自転車の本来の走行レーンである車道を通っていただく。は降りていただく。あくまでも住民の皆様の要求に基づいて安全対策を実施したものです。","voiceIndex":294,"id":"exchange-115"},{"speaker":"南委員","kind":"質問・要望","question":"住民の皆さんがそういうふうな要望をされたのは私も承知しています。しかし、地区が、区が設置している基本的な見解にやっぱり反するじゃありませんか。それから、合意がとれているというふうな認識あるんですか。ちょっとそこのところを再確認したいと思います。これについて、現在、返還している方々の人数が何人か。最も少ない返還額、幾らか。そして、その人数。これをちょっと教えてください。","respondent":"谷口交通安全担当課長、福島青少年育成課長","answer":"住民の皆さんとの合意の関係ですけれど、工事に当たりまして、住民の皆様はご理解を得られて座り込みをやめたということで、合意が得られたと理解しております。平成２６年２月２１日現在で、返還者は９０１名です。返還の対象ですけれども、月１,０００円から振り込んできているというものがあります。平均は、特に出していませんが、大体３万から５万円ぐらい。","voiceIndex":296,"id":"exchange-116"},{"speaker":"南委員","kind":"質問","question":"駐輪場の件で理解を得られたというふうに考えていると。そういう金額の支払い返還をしている、こういう状況について、どういうふうに品川区としては見解を持っているのでしょうか。何というのでしょうか、額そのものが、私はこの不況の中で、非常に厳しい中で、一生懸命努力して返還していらっしゃると思うのですけれど、そういうあたりの見解は、どういうふうに見ているのでしょうか。伺います。","respondent":"福島青少年育成課長","answer":"一方で厳しい状況の方もいますので、そういう方につきましては、十分相談に乗りまして、本人が返せる範囲で、毎月々払っていただく。そのように丁寧に対応しています。","voiceIndex":299,"id":"exchange-117"},{"speaker":"南委員","kind":"質問・要望","question":"今、日本だけですよね。ＯＥＣＤ３１カ国の中で、教育費の無償化がされていない。しかも、そういう状況の中で、２０１２年にようやく、３３年間もこれについては批准してこなかったのですけれども、これをようやく批准するようになったと。自民党も２０１２年の総選挙のときには、無償化をしようという、そういう公約を掲げているんですね。こう思うのですが、この給付型について、いかがでしょうか。","respondent":"福島青少年育成課長","answer":"区としましては、今までどおり、貸付につきましては、都の貸付制度がありますので、それを補完していくという形で進めていきたいと考えています。したがいまして、とりわけ給付について創設するという考えはございません。","voiceIndex":301,"id":"exchange-118"},{"speaker":"南委員","kind":"質問・要望","question":"創設する考えはないとおっしゃったけれども、しかしあえて私は、こういう経済不況の中で、しかも高校を卒業しても就職先もない。多くの借りている方たちは、返還していく気持ちはあるけれども、現実的に返せない。したがって、やっぱり区として将来の子どもを豊かに健全に育てる意味で、しっかり修学していただくという意味で給付制をつくるべきだ。このことを強く求めて、もう時間がないので終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":303,"id":"exchange-119"},{"speaker":"あべ委員","kind":"質問","question":"私からは、５２ページの特別区交付金。それから５５ページの職員互助会、５８ページ、各種手数料、これは広く全体について伺いたいと思っています。時間があれば、３９９ページの、今日ご説明もあった消費税に関連してもお伺いしたいと思います。特別区交付金。高目だった去年から５.３％アップということで、さらに高く見積もっているのですが、ここまで少なく見積もる必要があるのか、再度伺いたい。","respondent":"本城企画財政課長","answer":"その点で、確かに、ちょっと繰り返しになりますが、きちんと確実に見込むという、そういう方針の中で、個々の事業をきちんと見た結果だと考えております。","voiceIndex":305,"id":"exchange-120"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。それから次に行きます。これ、ここで質問することが妥当なのかどうか、職員互助会で、第二庁舎で売店を展開されていたと思うんですけれども、それが今年の３月でおしまいということになりました。改めてお伺いします。その検討には区が直接かかわるのかどうか。その見通しといいますか、今後どのような形にしていくのか、見通しを教えていただければと思います。","respondent":"本城企画財政課長、平澤経理課長","answer":"こんな事情とご理解していただければと思います。区の施設としては以上３つでございまして、こちらにつきましては、営業上の課題が多くあり過ぎるということで、３月１５日をもって閉店するということを聞いてあります。","voiceIndex":307,"id":"exchange-121"},{"speaker":"あべ委員","kind":"質問","question":"すみません。ちょっと、交付金のほうはあまり理解していないのですけれども、品川区が今、大きな事業が、しかもピークを迎えているときに、ほかのところより少ないという、ちょっと不思議な気がします。私が伺ったのは、今後どうするつもりか。どのような検討をするかということをお伺いしました。誰がどのような形で何を目指して検討していくのかということを教えていただければと思います。","respondent":"平澤経理課長","answer":"初めに防災センターの売店につきましては、職員関係ですので、こちらは今後検討していく。どういう売店、自動販売機等を含めまして、どういうものを置いていくのが最も有効、効率的、または財産の種目として適切なのかということを考えていくです。","voiceIndex":310,"id":"exchange-122"},{"speaker":"あべ委員","kind":"質問・要望","question":"ごめんなさい。これは要望、強い要望としておきます。各種使用料、手数料等とありますけれども、今回はこういったものと消費税との関係を伺いたいと思います。ここには出てきていないんですけれども、水族館あるいは保養所などについては、消費税の値上げに関連した、消費税増税に関連した値上げというのがあると聞きますが、ほかに区に関係するもので消費税の影響があるものというのはありますでしょうか。","respondent":"本城企画財政課長","answer":"今後、今回、消費税が改定になった結果で、決算の関係でもきちんとして、改めてあり方について確認し、その中でということで、平成２６年度は改定しません。","voiceIndex":312,"id":"exchange-123"},{"speaker":"あべ委員","kind":"質問","question":"ありがとうございました。伺おうと思ったところまで答弁していただいたので、ありがとうあります。今は利用できたとしても、次に上がったときにはどういう処理をしていくのか。テレビ番組の中の地域情報の中に、品川のものが取り扱われているのを私は見たことがないものですが、この番組制作や情報提供という面では、今、ケーブルテレビと品川区はどのような関係になっているか教えてください。","respondent":"柏原行財政改革担当課長","answer":"品川の情報もそこに出るということで、そういった形で入ってきていますので、そういったところをより強化していきましょうという調整はしているといったところです。","voiceIndex":314,"id":"exchange-124"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういった取組みというのは、今もつまりあるわけですね。調整を続けているということだと思います。近隣の区市が出てくるのと同じぐらいは品川のニュースに出会いたいなと考えていますので、ぜひ情報提供ですとか、あるいは積極的に取り上げてもらうような、何らかの働きかけをぜひしていただきたいと思うのですけれど、すると、どこの部署になるんですか。","respondent":"荒井広報広聴課長","answer":"番組につきましては、番組審議会というものがございまして、２カ月に１遍実施しています。そちらのほうに、品川区としてもオブザーバーとして出席しておりますので、今の委員のご意見を、そちらの番組で反映させていきたいと考えています。","voiceIndex":316,"id":"exchange-125"},{"speaker":"浅野委員","kind":"質問","question":"時間があれば、９２ページの土木費補助金について質問します。これは、どのような整備が対象になっているのでしょうか。最終で、たしか１２事業ぐらいあったかと思うのですけれども、それぞれが全てこういう補助の対象になっているのかどうかということ。非構造部材耐震化、こちらのほうの補助率はどのぐらいになっているのかという内容について教えてください。","respondent":"齋藤庶務課長","answer":"上から３つ目、小学校７分の２、２,４９６万３,０００円。これはトイレでございまして、鈴ヶ森小、伊藤小、源氏前小を予定しております。上２つ、小、中と書いてあります、３分の１、３分の１というのは、いずれも八潮学園です。","voiceIndex":319,"id":"exchange-126"},{"speaker":"浅野委員","kind":"質問・要望","question":"次に１０２ページの教育費負担金の件ですけれども、水道管直結化事業の取組みの件ですけれども、過去にも何回か質問が出ていますが、毎年、大体４カ所ぐらい、最近は行われているのかなと思います。以前、答弁の中では、平成２８年度まで実施するというようなことも出ていたかと思いますが、都の事業の考え方と品川区の取組みについて教えてください。","respondent":"齋藤庶務課長","answer":"今後ですが、平成２８年度まで、可能な限り補助金をいただきまして、水道管直結化事業を進めたいのですが、水道管との勾配、レベルの関係もありますので、難しい学校もありますけれども、可能な限り補助金をいただいて、１００％を目指したいと考えております。","voiceIndex":321,"id":"exchange-127"},{"speaker":"浅野委員","kind":"質問・要望","question":"ぜひとも１００％を目指していただきたいと思います。万一、もしできないところとか、補助金がないところであったとしても、これは区の費用を使ってでも全校そろえていただきたいなと、そのように考えておりますけれども、この点についてはいかがでしょうか。","respondent":"齋藤庶務課長","answer":"これはかなりの費用がかかってしまいます。区の単独の費用でどこまでできるか、なかなか、検討はしておりますが、難しいところもあるかなということで、すみません、決意のほど述べました。","voiceIndex":323,"id":"exchange-128"},{"speaker":"浅野委員","kind":"質問","question":"物理的に難しいところは、これは何としてでも超えるというわけにはいかないかと思いますけれども、心意気だけはしっかりと受けとめておきたいと思います。次に、こころの健康づくり事業について質問します。ほかにもたくさんあるかと思いますが、この事業を行う目的、そしてこれまでの取組みと、どのような成果が出ているのか、またどのような成果を出そうとしているのかについて教えてください。","respondent":"大石荏原保健センター所長","answer":"あるいは普及啓発活動といたしまして、職員の対応マニュアル、あるいはこころの電話帳というリーフレットをもって、あるいは関係機関の強化といたしまして、庁内外のレギュラーの対策のネットワーク、こういったものを行っておりまして、自殺をする人の身近な人が。","voiceIndex":325,"id":"exchange-129"},{"speaker":"浅野委員","kind":"質問","question":"まさに、身近な人が気がついていただけるかどうかというのが、最後の砦。結果についてはここではお話ししませんけれども、これはホームページとかどのぐらいアクセスがあるものなのか、どのぐらいの利用がされているのかということを１つお伺いしたいと思います。それともう一つ、こころの健康相談。どのぐらいを目指すと言ったらおかしいですけれども、来るべきものと考えているのか教えてください。","respondent":"大石荏原保健センター所長","answer":"それ以外に電話の相談ということもありますが、それぞれ必要な、こういった医師の相談に関しましては、保健師等が必要なものをある程度選別してやっておりますので、数というのがどのぐらいの目安ということはないと思いますが。","voiceIndex":327,"id":"exchange-130"},{"speaker":"浅野委員","kind":"質問・要望","question":"これからも充実した相談体制をとっていただきたいと思います。２０１２年は区内の自殺者は７１名というデータがあります。これを少しでも減らせるように頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":329,"id":"exchange-131"},{"speaker":"松澤委員","kind":"質問","question":"私からは、４４ページの特別区民税、５０ページの地方消費税交付金、５８ページから６３ページにかけての集会所使用料、文化センター使用料に関連して、時間がありましたらもう一点ぐらいお聞きしたいと思います。初めに４４ページ、特別区民税についてお聞きしたいと思います。色がついているとしたら、今年度の予算の中でどの事業に充てられたのかということをお聞きしたいと思います。","respondent":"高森税務課長、本城企画財政課長","answer":"均等割の５００円がいつまで続くかというと、平成２６年から１０年間の予定です。住民税の均等割引き上げ分の財源がどこに充てられたかという問題ですが、これについては防災関係の施策ということで、総額７６億円ほどの事業規模を持っておりますが、一般財源として、今回均等割が上がった分を。","voiceIndex":331,"id":"exchange-132"},{"speaker":"松澤委員","kind":"質問","question":"１０年間の時限立法ということですけれども、やはり均等割額に上乗せして皆さんが払っている１０年。これは１０年間払うわけですから、これが防災の均等ではなくて、しっかりと毎年毎年、１億円、これをこの事業に充てたんですよというふうに私はすべきじゃないかと思うんですね。その考え方についていかがでしょうか。","respondent":"本城企画財政課長","answer":"この中の、平成２６年度の対応としては、考え方の整理としては、その充実の１つの用途として均等割引き上げ分を充てたという、そういう形の、今回における整理だということでご理解いただければと思います。","voiceIndex":334,"id":"exchange-133"},{"speaker":"松澤委員","kind":"質問・要望","question":"いや、あまり理解できないですよね。では次に行きます。これも、そうするとまた平らにしちゃうんでしょうかね。これ、先ほどの区民税と比べると、消費税ですから薄くしましたという形で当然答弁されると思うし、そうかなと思うんですけど、私はこれに比べると、１億円の区民税のほうは、しっかりとした目的を持って、これに使いましたよというふうにしてもらいたい、そういうふうに思いましたので。","respondent":"本城企画財政課長","answer":"今回の消費税の引き上げ分につきましては、冒頭の資料の中でもご説明させていただきましたが、３９９ページの表にもありますが、この引き上げに伴って１１億円余の額が今度新たに生まれたということで、それについては。","voiceIndex":336,"id":"exchange-134"},{"speaker":"松澤委員","kind":"質問","question":"次へ行きたいと思います。５８ページから６３ページまで、集会所使用料、文化センター使用料に関連して。文化センター使用料のほうについてはいろいろ各議員からお話、質問等がありましたので結構ですけども、この地域センターの集会所ですね。回数は実績見合いということでしょう。これ利用率、相当、利用率は高いと思うんですけど、利用率はどれぐらいになっているのでしょうか。お伺いいたします。","respondent":"久保田地域活動課長","answer":"集会所の利用率ですけれども、平成２５年度の４月から１月までの集計ですけれども、全体で見ますと６０％となっています。","voiceIndex":338,"id":"exchange-135"},{"speaker":"松澤委員","kind":"意見","question":"６０％ということは、若干まだまだ空いているということだと理解していきたいと思います。実は地域センターの集会所、ここのところ、荏原第五、荏原第三、きれいに直りましたけれども、高齢者の方から言われるのは、カラオケの機械があるといいなと言うんですね。区長、笑ってますけれども。実際に、ないんですよね。これはなぜ地域センターにはないのか。その辺についてお聞かせください。","respondent":"久保田地域活動課長","answer":"例えば音が出ない、日本舞踊とか、そういうあまり音が出ないようなものについてはご活用いただいているところですけれども、基本的には他の利用者のご迷惑にならないような、大きな音の出ないご利用をお願いしています。","voiceIndex":340,"id":"exchange-136"},{"speaker":"松澤委員","kind":"質問・要望","question":"利用者に聞きますと、持ち込んでやってると言うんですね、自分たちで。いや、実際そうですよ。黙認しているのかもしれませんけど。いや、実際にね、防音設備がしっかりして、使えるんですから。ちゃんと調べて、ここは使えるなというところは使えるようにしていただきたいと思います。いま一度お聞きしたいです。","respondent":"久保田地域活動課長","answer":"もし、そのような形でカラオケを持ち込みでやっているといったことで、他のお客様の迷惑になっているような場合は、私ども注意をして、使用をやめてもらうということになりますので、申しわけございませんが、そんな状況になりましたら。","voiceIndex":342,"id":"exchange-137"},{"speaker":"松澤委員","kind":"質問","question":"この件はまた改めて、ちょっと分が悪いんで。実は集会所、文化センター、今たばこを吸う人にとっては、分煙ということで、喫煙室ができていると思うんですけど、これ、全て喫煙室があるんでしょうか、その点お聞かせください。","respondent":"久保田地域活動課長、安藤文化スポーツ振興課長","answer":"今、品川区のほうは分煙という考えで施設の整備を進めてありますので、集会所につきましては基本的には分煙になっていまして、喫煙コーナーを設けているというところが現状です。そしてまた旗の台文化センターにも簡易な喫煙所があります。それから、東品川文化センターについては、外のところに灰皿が置いてあると記憶をしています。","voiceIndex":344,"id":"exchange-138"},{"speaker":"松澤委員","kind":"質問","question":"実は、話題になっておりました五反田文化センター。ですから、表で皆さん吸っていると言うんですね。それがやっぱりどうしても見苦しいということで、何としてもつくってもらえないかという話がある。表側に物置きみたいな部屋があるんで、あそこを使えないかなんて話もあるんですけど、この辺、一番新しい施設にないというのはどういうことなのか。その辺改めてお聞きしたいです。","respondent":"安藤文化スポーツ振興課長","answer":"それで、館内では禁煙ということで進めてまいりましたけれども、委員ご指摘のように、外のところで缶コーヒーを飲みながら、たばこを吸うというお話も伺ってありますが、こちらとしては、禁煙法もできましたことで、館内は禁煙とさせて。","voiceIndex":347,"id":"exchange-139"},{"speaker":"松澤委員","kind":"質問","question":"今の答弁、何か納得いかないですよね。禁煙だから、外で吸う分には構わないというふうに。出たらほっとくというふうにとれるんですけども。あれはやっぱり、私にお話しされた方は音楽関係者で、やっぱりみっともないですよ、表で皆さんが吸ってらっしゃるのはということなんですけど。その辺、改めてつくる気はないんですか。外につくれると思うんですけど。考え方がちょっと私はおかしいと思って、改めて。","respondent":"安藤文化スポーツ振興課長","answer":"そしてまた学校も利用しています。そんな中で、当初から禁煙にしていくという、館内は禁煙です。それで、外で吸うという方につきまして、極力注意を促して、固まって吸うことはやめていただく。","voiceIndex":349,"id":"exchange-140"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはり、それはおかしいと思う。施設の外って、道路に出ろと言うんですか。みんな、玄関先ですよ。玄関先、駐車場のところで吸ってるわけですから、やっぱりそれは何とかしなくちゃいけない。これは、禁煙にしたということはすばらしいですけども、やはり出た方が吸う場所はやっぱり指定してつくらなくちゃおかしい。これ、考え方を改めていただきたいと思います。それと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":351,"id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１９ページの住宅・建築物耐震化支援事業についてお伺いしたいと思います。木造住宅の耐震化についてお伺いしますので、よろしくお願いします。木造住宅の耐震改修の助成制度の費用が、上限が１５０万円で、２分の１まで出てますけれども、この１５０万円の内訳、国、都、区の分がそれぞれ幾らなのか、そして区の分というのは財調算定されるのかをお伺いしたいと思います。","respondent":"品川木密整備担当課長","answer":"それから７５万円から１５０万円に変更したときということですが、こちらのほうは、平成２３年度から耐震改修というか建替え。改修のほうですね。改修のほうの金額は１５０万円に、それから建替えのほうも１５０万円に変更しています。","voiceIndex":353,"id":"exchange-142"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１５０万円に引き上げて大幅に増えたということなのですが、今回、除却の助成を１０分の１０に引き上げたということは、さまざまな利用の拡大ということで、対象が広がるということで、これはいいと思うんです。建替え助成であれば１５０万円が受けられたのにもかかわらず、除却費用になると１５０万円までは受けられないという方が出てしまうということについては、区としては認識されてますでしょうか。","respondent":"品川木密整備担当課長","answer":"委員のお話ですと、多分、建替えの費用１５０万円まで出るところを、除却の費用が仮に１００万円までしか出なかったらどうなんだと。金額５０万円、もらえないではないかというようなお話かとは思いますが、こちら、あくまで耐震の制度です。耐震をやる。","voiceIndex":355,"id":"exchange-143"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"建て替えるということが、私は一番の耐震化というふうなことになると思うんですけれども、じゃあ建替えによって１５０万円まで今までは出た。それが除却ということで１００％にしたとしても、減額になる方が出るということは認識されますか。そのことについて伺います。","respondent":"品川木密整備担当課長","answer":"認識というよりも、どこに税を投入していくかという考え方です。要するに、耐震化をしていくところに税を投入していくという考え方でやっていくです。","voiceIndex":357,"id":"exchange-144"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"耐震建替えというのは、まさに耐震化そのもので、耐震建替えこそ誘導すべきということで、私は、部長とかも委員会の中で、ずっとそういったことを誘導していきたいんだということでおっしゃっていたと思うんですが、耐震建替えが耐震化と言わずに、除却が耐震化というところの意味がわからないんですけど。","respondent":"品川木密整備担当課長","answer":"耐震化ということは、耐震性のない住宅を改善していくです。","voiceIndex":359,"id":"exchange-145"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"それが、除却しかしないということによって、私は耐震建替えをする人によっては、減額になってしまうということで、耐震化に対しての、私は減額になるという、そういうところで、耐震建替えが、今まで誘導できていたものが、逆に減るということになると思うんですけど、その点についてはいかがでしょうか。","respondent":"品川木密整備担当課長","answer":"今までの耐震除却、平成２３年度から耐震除却を行ってまいりました。その中で、１５０万円を切るという件数はほとんどございません。そういう中で、とにかく耐震性を保つということは、建替えはそうなんですけれども、建替えも、建替えをする前に除却します。","voiceIndex":361,"id":"exchange-146"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"耐震建替えをする場合には、今まで１５０万円が出ていたものが、除却の１００％では置きかえることができない。年間でも５６０戸というのが区の目標ですから、これを進めるというところでも、私は耐震建替えの助成を減額するということになってしまう、除却１００％では置きかえられない。私はこの減額制度というのは、減額になることはやめるべきで、建替え制度の廃止はやめてほしいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":363,"id":"exchange-147"},{"speaker":"須貝委員","kind":"質問・要望","question":"私は、１２８ページ、公共施設整備基金繰入金の内容についてお聞きします。そして、あとちょっと、歳入全般について宿題がありましたので、ちょっと教えていただきたいと思います。公共施設整備基金の繰入金の内容についてお聞きしたいと思います。","respondent":"本城企画財政課長","answer":"公共施設整備基金の繰入金の内容ですが、こちらの充当事業として掲げてあります、公園・児童遊園整備ほか６事業ということで、このほかの事業といたしましては、平成２６年度としまして、総合区民会館の運営費、それから文化センター維持運営費。","voiceIndex":365,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"財源の充当先の一部、今ご説明がありましたが、これは公共施設整備基金ですよね。それが、充当先の一部が総合区民会館の運営費として３億円、そして文化センターの維持運営について３億円に充当するというふうになっておりますが、これ、整備基金ですよね、公共施設の。運営に、運営費として、維持費として、こちらに財源として充当するというのはいいんですか。教えてください。","respondent":"本城企画財政課長","answer":"実際は、整備自体にそれぞれの、今申し上げました総合区民会館等々、運営費ではなくて整備費自体に充てているものです。そういう意味で、公共施設整備基金の趣旨にかなった形の繰り入れで対応しているものです。","voiceIndex":367,"id":"exchange-149"},{"speaker":"須貝委員","kind":"意見","question":"じゃあ、すみません。ここに書いてあるというか、歳入予算見積書に書いてある、これは、総合区民会館の運営費として、それから文化センターの運営というふうに書いてありますが、これは違うということですね。あくまで、何かを、施設を整備するということでいいのか。もう一回だけお答えを。","respondent":"本城企画財政課長","answer":"運営費というのはあくまでも利用面で、実際のその中の整備自体に充てているのが今回の繰り入れの使い方です。","voiceIndex":369,"id":"exchange-150"},{"speaker":"須貝委員","kind":"質問","question":"書き方云々はあると思うんですが、ちょっとこれはやっぱり紛らわしいんじゃないかなと。やはりきちっと、例えばほかのほうは、小規模介護施設整備費、それから都市再生総合整備事業、それから橋梁改修事業とか、あと公園・児童遊園整備とか、やはりこういうふうにわかりやすく書かないと、これ。もう一回いいでしょうか、それは間違いないということは言えるんですね。","respondent":"本城企画財政課長","answer":"重ねてのご答弁になりますが、整備費自体に充てているものです。","voiceIndex":371,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"わかりました。次に、昨年、決算特別委員会でちょっとお話をさせていただきました。そして、今年の２０１４年１月に頭取の退任が発表され、処分はその他大勢にわたり、ＯＢを含む計５４人の大量処分が行われることになったというふうな報道があります。現に民間企業の中においては、もう既に業務上の何らかの処分を行っているのですが、品川区はどうするのでしょうか。教えてください。","respondent":"久保田会計管理者","answer":"この説明を聞いた後に、これまでのみずほとの関係から言うと、私どもの大事な交付金を扱っているというところがありますので、これに対して品川区単独で、いろいろな体制をするというようなことは、なかなかこれは難しいとは思いますけれども。","voiceIndex":373,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"暴力団事件があった、どうだこうだ、入札に対して取消処分とかいろいろあります。私は、品川区の今もうメインバンクですから、確かに多くの影響が出ると思います。それぞれやり方はあると思うので、やはり品川区も、全国に対して品川区も範たるものがあるんですから、何かきちっとした方針がないと、まずいのではないかと思うのですが、再度お聞きしたいと思いますので。","respondent":"久保田会計管理者","answer":"みずほ銀行に対するいろいろな対応というのは考えられるかもしれません。１つのパフォーマンスがあるかもしれません。だけど、私たちがやはり考えなくちゃならないのは区民の利益です。今のみずほ銀行との仕事がとまれば、区民の皆さんにお支払いするお金もとまってしまいます。","voiceIndex":375,"id":"exchange-153"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"よろしくお願いします。私からは、５４ページの総務費負担金について、それと５８ページからの使用料について、それと国、東京都の支出金全般についてお聞きいたします。しかしながら、その一方で、職員互助会から品川区国際友好協会までの４件に関しては、前年度比プラスになっているのですが、その理由を教えていただきたいと思います。とりあえずよろしくお願いします。","respondent":"平澤経理課長、本城企画財政課長","answer":"こちらについてご説明します。１つ目の、庁舎負担金の上のほう３つ、東京都品川都税事務所、東京都第二建設事務所、東京法務局品川出張所、こちらにつきましては区の庁舎を区分所有しています。ただ、回数と金額の伸びが必ずしも連動していないということに関しましては、回数については、午前、午後、夜間の区分とか、その回によって単価が違っているものとかありますので。","voiceIndex":378,"id":"exchange-154"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"使用料の部分、目的外利用で、庁舎のところはご説明いただいたのですが、そのほかの施設について、この目的外利用がどこまでオーケーなのかということと、目的外利用での使用料というのがどのようになっているのか、その点を教えてください。少子化対策に充当されるものがあれば教えていただきたいのと、区として、この少子化対策をどのように位置づけ、また考えていられるのか、その点もお知らせください。","respondent":"本城企画財政課長、福島青少年育成課長","answer":"それの中で、その目的外、本来の目的以外で利用する場合という形での目的外利用ということで規定して、それに即したそれぞれ使用料ということで、条例上、整備してきているという形です。私からは少子化対策についてご説明します。私どものほうで、品川区次世代育成支援対策推進協議会を持ちまして、それに基づきまして、こちら行動計画を策定しています。","voiceIndex":381,"id":"exchange-155"},{"speaker":"石田（し）委員","kind":"質問","question":"少子化対策についてなのですが、この中の、さまざまな支出金がある中で、どの事業が実際に少子化対策として充てられているのか、その点を教えてください。よろしくお願いします。","respondent":"福島青少年育成課長","answer":"私どもの計画表では、子育て支援ですとか、あるいは在宅子育て支援、さらには子育てと就労の両立支援等々、さまざまな事業について計画していますが、それを全体として包括するような補助金を充てているわけではなく、個別の事業ごとに補助金が入ってきているという関係です。","voiceIndex":384,"id":"exchange-156"},{"speaker":"石田（し）委員","kind":"意見","question":"ありがとうございました。少子化対策というと、どうしても何か、この予算書を見ていても、子育て支援等が中心的に行われてしまっているのかなと思います。この支出金の中でも、多くの事業の中に、例えば子育て支援の中に少子化対策の一環の部分が入っているよということだと思いますが、ぜひ、少子化対策は少子化対策でしっかり取り組んでいただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":386,"id":"exchange-157"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私は６９ページ民生使用料の中の特養ホーム地域交流室使用料で、杜松のところを聞きます。それから１１０ページの都の民生費補助金の中のシルバー交番設置事業補助金、２点伺いたいと思います。補助金としては、平成２５年度より８０万円ほど減っておりますけれども、歳出のほうの事業の全体額では４００万円強、予算として平成２６年度は増えておりますので、その辺も含めてお教えいただきたいと思います。","respondent":"永尾高齢者福祉課長","answer":"それで、今回は仮称ふれあいステーション事業というふうになっておりますけれども、こちらにつきましても、現状のケアサポート事業と、支え愛・ほっとステーションの事業についてのかかわりとか役割分担というのを平成２６年度に調整検討いたしまして、できるだけ。","voiceIndex":388,"id":"exchange-158"},{"speaker":"たけうち委員","kind":"質問・要望","question":"杜松のほうはわかりました。わかりました。そうしますと、全区展開していくための布石を平成２６年度打っていくという考えでいいんでしょうかね。その上で、やる内容は、今やっている、地域センター管轄で２カ所あると思うんですけど、ここでは内容が何か大きく変わるとか、何かがなくなるとか、何かがつけ加わるとかということではないという理解でよろしいのでしょうか。","respondent":"永尾高齢者福祉課長","answer":"こちらは移転になりますけれども、その後の活用については、これからの検討ということになっております。ふれあいステーションの事業につきましては、今後どういう形で全区に広げていくかという、そういう手法も含めまして検討していく予定です。","voiceIndex":390,"id":"exchange-159"},{"speaker":"たけうち委員","kind":"提案","question":"わかりました。在宅介護支援センターの後については、何か非常にちょっと狭いかなとは思うので、なかなか何をというのは、私のほうも提案できないんですけれども、さっきいろんな障害者のお話が出たりとか、いろいろな、やっぱり福祉に関連するようなものに使ってもらえるといいなということだけ要望させていただきたいと思います。その上で、また別の、仮称ふれあいステーション事業ですね。","respondent":"永尾高齢者福祉課長","answer":"介護保険の改正が今見込まれているところですけれども、その中でも、地域包括ケアの重要性というのが、今叫ばれております。やはり公助だけでは、高齢者の生活を支えるということは、現状ではとても無理だという状況。それは皆さんが認識していることかと思います。","voiceIndex":392,"id":"exchange-160"},{"speaker":"たけうち委員","kind":"質問","question":"予算特別委員会の資料で、補助金一覧があるんですけれども、これを私、見てて、よくわからなかったので、ちょっとお聞きしたいのですけれども、この国と都の支出金が出ている内容と、この次の、国と都ではなくて補助金一覧というのがあるのですけれども、その補助金一覧表の中で、例えば民生費の中で、１９ページの「新」とついているところに、例えば認証保育所保育従事者職員等処遇改善事業とありますけど。","respondent":"本城企画財政課長","answer":"ですから、そういう意味で、全て、区単独でやっているもの以外の、今後ともどちらかの補助金を募っていく一覧という形で整理したものです。","voiceIndex":394,"id":"exchange-161"},{"speaker":"たけうち委員","kind":"質問","question":"すみません。例えば、１６ページのほうで、品川区国際友好協会とか、いろいろな品川区の関連する団体とか、いろいろなところに補助金を出して、これは区単独で出しているのかなと思って、その中に国とか都が、都から出ているのも両方に出ているんですね、名称が違うんですけど。そこがわかりづらいんだけど、どう考えたらいいんですか。","respondent":"本城企画財政課長","answer":"申しわけありません。あくまでも、補助金一覧等につきましては、区から団体等に出している補助金です。一方、初めにご説明しましたのは、都あるいは国の補助金を活用したものということで、そういった観点の違いということで、あくまで補助金一覧は区が主体となって補助する。","voiceIndex":396,"id":"exchange-162"},{"speaker":"本多委員","kind":"意見","question":"６５ページのしながわ中央公園と、１１５ページのしながわ中央公園拡張整備。ほか税外収入について聞いていきます。最初に、しながわ中央公園の使用料について、青陵中学・高校が今年の秋ごろに校舎・グラウンドなど新設完了いたしますけれども、しながわ中央公園の利用頻度、使用料について、これまでと変わりがあるのかどうか、その辺を聞かせてください。","respondent":"安藤文化スポーツ振興課長","answer":"お尋ねの青陵の利用の件ですけれども、今、中央公園については、学校の優先枠としてつけてあります。そこに今、青陵と、それから区立の豊葉の杜ですけれども、豊葉の杜が今校庭が利用できないということで、あわせて利用しています。","voiceIndex":399,"id":"exchange-163"},{"speaker":"本多委員","kind":"質問","question":"学校法人青蘭学院、青陵中学校・高校の利用、ほかの学校とあわせてですけど、全体の中ではそんなに、平成２４年度、平成２５年度は変わりがないというのがわかりました。青陵が使うのは、今までと、校舎が新設されるわけですね、校舎とグラウンドは、独自の学校の敷地内に。それでどう変わるのかと。この平成２６年度の予算で変わりがあるのかないのか、それだけ教えてくれますか。","respondent":"安藤文化スポーツ振興課長","answer":"この計上のところにつきましては、とりあえず平成２５年度決算とほとんど変わりないような状況で計上させてもらっています。ですから、基本的には変わりないと認識はしています。","voiceIndex":401,"id":"exchange-164"},{"speaker":"本多委員","kind":"確認","question":"ほぼ今までと同じという使い方で、わかりました。お互いさまだと思うんですね。区も使用率が上がるほうがいいですし、相手方の学校法人もやはり使えたほうがいいと思いますので、その辺のお互いさまというような、そこが確認できればなと。それだけちょっと、もう一度教えてくれませんか。","respondent":"齋藤庶務課長","answer":"使用率に応じてです。したがいまして平成２６年度に限っては半々ということになります。","voiceIndex":403,"id":"exchange-165"},{"speaker":"本多委員","kind":"確認","question":"それとあわせまして、このＪＴ跡地の特徴としながわ中央公園とを取り巻く、真ん中に中小企業センターがありますけれども、これは現状のままでいくということで伺っているのですが、その辺に対して変更がないのか確認させてください。","respondent":"多並公園課長","answer":"今回の都市公園の拡張、いわゆる都市計画変更に当たりましても、中小企業センターのところは除いて、それ以外の部分ということで、今のちょうどＪＴ跡地の部分を変更し、公園整備とするという形で考えているところです。","voiceIndex":409,"id":"exchange-166"},{"speaker":"本多委員","kind":"質問・要望","question":"当然、今の現状で中小企業センターはいくということで、わかりました。これまで庁舎の屋上がなかなかちょっと難しそうなので、ぜひ中小企業センターの屋上を活用していただきまして、周辺が、やはり公園ですとか防災ですとか、多目的の用途ですので、ぜひ中小企業センターの屋上にも、多目的といいますか、使途、目線を広げて考えていただきたいと思いますがいかがでしょうか。","respondent":"米田商業・観光課長","answer":"そういったことで、それなりに屋上のほう、有効活用しておりますけれども、今の委員のご提案の趣旨も踏まえまして、再度、有効活用、もっと図れないかということについては、改めて検討してまいりたい。このように考えてあります。","voiceIndex":411,"id":"exchange-167"},{"speaker":"本多委員","kind":"質問","question":"検討してください。それで、税外収入なんですけれども、今日もずっと質問が出ていますけれども、これまでの税外収入の推移というのを、概算、概要で結構ですので、近年こうですというのを教えていただければと思います。","respondent":"柏原行財政改革担当課長","answer":"近年で申しますと、例えば広告料収入の部分でございまして、こういったところでは、広報しながわであったり、しながわガイドであったり、こういったところでの広告料収入が、年間で、ちょっと古いデータではありますけれども、平成２１年度、平成２２年度。","voiceIndex":413,"id":"exchange-168"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、ちょっと時間があるので、細かいことを２つだけ最後に質問させてください。５５ページのみずほ銀行の、この使用料とか家賃については異論はありません。おそらく区では、今のスペースでは無理と言うと思うのですが、そうじゃなくて、みずほ銀行に対応を求めてほしいと思うんです、それが１つ。物価が高騰しているので、この辺の補助金はその辺を盛り込んであるのかないのか、それだけ教えてください。","respondent":"久保田会計管理者、溝口都市開発課長、齋藤庶務課長","answer":"みずほ銀行のＡＴＭについて、早く直るように、厳重に申し入れていきたいと思っています。そういう形でお願いしたいと思います。再開発事業に関する補助金の関係ですけど、これにつきましては、もととなる事業費につきましては、原価高騰等、そういったところも十分考慮しながら。豊葉の杜学園、すみません、平成２６年、この４月からグラウンドができますそうです。平成２５年度までの枠組みは青陵と折半だったです。","voiceIndex":415,"id":"exchange-169"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1002#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2014-01-01&TermEnd=2014-12-31"}],"sourceMeta":{"pages":0,"characters":122491,"voices":420}}]);
